let cachedProducts: ProductItem[] | null = null;

/**
 * Returns a flat array of all product items from products.json,
 * enriched with parent category metadata (category, categoryIcon, pill).
 */
export function getAllProducts(): ProductItem[] {
  if (cachedProducts) return cachedProducts;

  const result: ProductItem[] = [];

  for (const group of productsData as ProductCategory[]) {
    if (group.items && Array.isArray(group.items)) {
      for (const item of group.items) {
        result.push({
          ...item,
          category: group.category,
          categoryIcon: group.icon,
          pill: group.pill || undefined,
        });
      }
    }
  }

  cachedProducts = result;
  return result;
}

/**
 * Quick lookup by product ID / SKU (e.g. "tir10_set", "reta10_vial").
 */
export function getProductById(id: string | number): ProductItem | undefined {
  if (!id) return undefined;
  const targetId = String(id).trim().toLowerCase();
  return getAllProducts().find((p) => p.id.toLowerCase() === targetId);
}

/**
 * Quick lookup by product name or full name (case-insensitive & fuzzy matching).
 */
export function getProductByName(name: string): ProductItem | undefined {
  if (!name) return undefined;
  const target = name.trim().toLowerCase();
  const all = getAllProducts();

  // 1. Exact match on ID, name, or fullName
  const exact = all.find(
    (p) =>
      p.id.toLowerCase() === target ||
      p.name.toLowerCase() === target ||
      p.fullName.toLowerCase() === target
  );
  if (exact) return exact;

  // 2. Partial / substring match
  return all.find(
    (p) =>
      p.fullName.toLowerCase().includes(target) ||
      target.includes(p.name.toLowerCase()) ||
      p.name.toLowerCase().includes(target)
  );
}

/**
 * Returns all product categories with their items.
 */
export function getProductCategories(): ProductCategory[] {
  return (productsData as ProductCategory[]).filter((c) => Array.isArray(c.items));
}

/**
 * Calculates the tiered shipping fee in Pesos based on region and total item count
 * from shipping_config in products.json.
 */
export function calculateShippingFee(region: string, totalItemCount: number): number {
  const normalized = (region || "").toLowerCase().trim();
  const config = (productsData as ProductCategory[]).find(
    (p) => p.type === "shipping_config"
  )?.rates;

  if (!config) return 0;

  let rates = config[normalized];
  if (!rates) {
    if (normalized.includes("luzon")) rates = config["luzon"];
    else if (normalized.includes("visaya")) rates = config["visayas"];
    else if (normalized.includes("mindanao")) rates = config["mindanao"];
    else rates = config["other"];
  }

  if (!rates) return 0;

  if (totalItemCount <= 1) return rates["1"] ?? 0;
  if (totalItemCount === 2) return rates["2"] ?? 0;
  return rates["max"] ?? 0;
}
