"use server";

import { db } from "@/lib/db";
import { orders, orderItems, orderEvents, products, shippingMethods } from "@/lib/db/schema";
import { eq, sql } from "drizzle-orm";
import { orderSubmissionSchema } from "@/lib/validation/schemas";
import { uploadPaymentProof } from "@/lib/google-drive/client";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

// ============================================================
// SUBMIT ORDER (Customer action)
// ============================================================

export interface OrderSubmitResult {
  success: boolean;
  orderNumber?: string;
  error?: string;
  fieldErrors?: Record<string, string[]>;
}

export async function submitOrder(formData: FormData): Promise<OrderSubmitResult> {
  try {
    // --- Parse form data ---
    const rawItems = formData.get("items");
    const parsedItems = rawItems ? JSON.parse(rawItems as string) : [];

    const rawData = {
      customerName: formData.get("customerName"),
      customerPhone: formData.get("customerPhone"),
      customerEmail: formData.get("customerEmail") || undefined,
      deliveryAddress: formData.get("deliveryAddress"),
      city: formData.get("city"),
      province: formData.get("province"),
      postalCode: formData.get("postalCode") || undefined,
      shippingMethodId: Number(formData.get("shippingMethodId")),
      paymentMethod: formData.get("paymentMethod"),
      items: parsedItems,
    };

    // --- Validate form data ---
    const parsed = orderSubmissionSchema.safeParse(rawData);
    if (!parsed.success) {
      return {
        success: false,
        error: "Please check your form and try again.",
        fieldErrors: parsed.error.flatten().fieldErrors as Record<string, string[]>,
      };
    }

    const data = parsed.data;

    // --- Fetch shipping method server-side ---
    const shippingMethod = await db.query.shippingMethods.findFirst({
      where: (sm, { eq, and }) =>
        and(eq(sm.id, data.shippingMethodId), eq(sm.isActive, true)),
    });

    if (!shippingMethod) {
      return { success: false, error: "Selected shipping method is unavailable." };
    }

    // --- Fetch products server-side (never trust client prices) ---
    const productIds = data.items.map((i) => String(i.productId));
    const dbProducts = await db.query.products.findMany({
      where: (p, { inArray, eq: eq2, and }) =>
        and(inArray(p.id, productIds), eq2(p.isAvailable, true)),
    });

    const productMap = new Map(dbProducts.map((p) => [p.id, p]));

    // Validate all products exist and are available
    for (const item of data.items) {
      const product = productMap.get(String(item.productId));
      if (!product) {
        return {
          success: false,
          error: `Product is no longer available. Please refresh the page.`,
        };
      }
    }

    // --- Calculate totals server-side ---
    let subtotal = 0;
    const lineItems = data.items.map((item) => {
      const product = productMap.get(String(item.productId))!;
      const lineSubtotal = product.price * item.quantity;
      subtotal += lineSubtotal;
      return {
        productId: product.id,
        productName: product.name,
        unitPrice: product.price,
        quantity: item.quantity,
        subtotal: lineSubtotal,
      };
    });

    const total = subtotal + shippingMethod.fee;

    // --- Handle payment proof upload ---
    let paymentProofFileId: string | null = null;
    const proofFile = formData.get("paymentProof") as File | null;

    if (proofFile && proofFile.size > 0) {
      // Validate file server-side
      const allowedTypes = ["image/jpeg", "image/png", "image/webp", "image/gif"];
      const maxSize = 10 * 1024 * 1024;

      if (!allowedTypes.includes(proofFile.type)) {
        return { success: false, error: "Payment proof must be an image file." };
      }
      if (proofFile.size > maxSize) {
        return { success: false, error: "Payment proof file is too large (max 10 MB)." };
      }

      const buffer = Buffer.from(await proofFile.arrayBuffer());
      const filename = `payment-proof-${Date.now()}-${proofFile.name.replace(/\s+/g, "_")}`;

      try {
        const uploadResult = await uploadPaymentProof(buffer, proofFile.type, filename);
        paymentProofFileId = uploadResult.fileId;
      } catch (driveError) {
        console.error("Google Drive upload failed:", driveError);
        return {
          success: false,
          error: "Payment proof upload failed. Please try again.",
        };
      }
    }

    // --- Generate order number ---
    const lastOrder = await db.query.orders.findFirst({
      orderBy: (orders, { desc }) => [desc(orders.id)],
      columns: { id: true },
    });
    const nextId = (lastOrder?.id ?? 0) + 1;

    const prefix = process.env.ORDER_NUMBER_PREFIX ?? "PB";
    const year = new Date().getFullYear();
    const padded = String(nextId).padStart(4, "0");
    const orderNumber = `${prefix}-${year}-${padded}`;

    // --- Insert order, items, and events sequentially ---
    const [newOrder] = await db
      .insert(orders)
      .values({
        orderNumber,
        customerName: data.customerName,
        customerPhone: data.customerPhone,
        customerEmail: data.customerEmail || null,
        deliveryAddress: data.deliveryAddress,
        city: data.city,
        province: data.province,
        postalCode: data.postalCode || null,
        shippingMethod: shippingMethod.name,
        shippingFee: shippingMethod.fee,
        paymentMethod: data.paymentMethod,
        paymentProofFileId,
        paymentStatus: proofFile && proofFile.size > 0 ? "under_verification" : "pending",
        orderStatus: proofFile && proofFile.size > 0 ? "payment_verification" : "pending_payment",
        subtotal,
        total,
      })
      .returning();

    // Insert line items (price snapshot)
    await db.insert(orderItems).values(
      lineItems.map((item) => ({
        ...item,
        orderId: newOrder.id,
      }))
    );



    // Create first timeline event
    await db.insert(orderEvents).values({
      orderId: newOrder.id,
      eventType: "order_submitted",
      description: "Order submitted by customer.",
    });

    if (proofFile && proofFile.size > 0) {
      await db.insert(orderEvents).values({
        orderId: newOrder.id,
        eventType: "payment_proof_uploaded",
        description: "Payment proof uploaded.",
      });
    }

    return { success: true, orderNumber: newOrder.orderNumber };
  } catch (error) {
    console.error("Order submission error:", error);
    return {
      success: false,
      error: "Something went wrong. Please try again.",
    };
  }
}

