        <time
          dateTime={new Date(order.createdAt).toISOString()}
          className="mt-2 block text-xs"
          style={{ color: "var(--color-text-muted)" }}
        >
          {formatDateTime(order.createdAt)}
        </time>
      </article>
    </Link>
  );
}
"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { confirmPayment, rejectPayment } from "@/lib/actions/admin-orders";
import { Check, X, Loader2 } from "lucide-react";

interface PaymentVerifierActionsProps {
  orderId: number;
  orderNumber: string;
}

export default function PaymentVerifierActions({
  orderId,
  orderNumber,
}: PaymentVerifierActionsProps) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [rejectionReason, setRejectionReason] = useState("");
  const [activeAction, setActiveAction] = useState<"confirm" | "reject" | null>(null);

  const handleConfirm = () => {
    setActiveAction("confirm");
    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.append("orderId", String(orderId));

        const res = await confirmPayment(formData);
        if (res.success) {
          toast.success(`Payment confirmed for Order #${orderNumber}! 🎉`);
          router.refresh();
        } else {
          toast.error(res.error || "Failed to confirm payment.");
        }
      } catch (err: any) {
        toast.error(err.message || "An unexpected error occurred.");
      } finally {
        setActiveAction(null);
      }
    });
  };

  const handleReject = () => {
    setActiveAction("reject");
    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.append("orderId", String(orderId));
        formData.append("reason", rejectionReason);

        const res = await rejectPayment(formData);
        if (res.success) {
          toast.info(`Payment rejected for Order #${orderNumber}.`);
          router.refresh();
        } else {
          toast.error(res.error || "Failed to reject payment.");
        }
      } catch (err: any) {
        toast.error(err.message || "An unexpected error occurred.");
      } finally {
        setActiveAction(null);
      }
    });
  };

  return (
    <div className="space-y-2 pt-2">
      <button
        type="button"
        onClick={handleConfirm}
        disabled={isPending}
        className="neu-button neu-button-accent w-full text-xs py-2.5 flex items-center justify-center gap-1.5 font-bold rounded-xl"
      >
        {isPending && activeAction === "confirm" ? (
          <>
            <Loader2 size={15} className="animate-spin" /> Confirming...
          </>
        ) : (
          <>
            <Check size={16} /> Confirm Payment
          </>
        )}
      </button>

      <div className="space-y-2">
        <input
          type="text"
          value={rejectionReason}
          onChange={(e) => setRejectionReason(e.target.value)}
          placeholder="Rejection reason (optional)..."
          disabled={isPending}
          className="neu-input text-xs py-1.5 rounded-xl"
        />
        <button
          type="button"
          onClick={handleReject}
          disabled={isPending}
          className="neu-button neu-button-danger w-full text-xs py-2 flex items-center justify-center gap-1 font-semibold rounded-xl"
        >
          {isPending && activeAction === "reject" ? (
            <>
              <Loader2 size={14} className="animate-spin" /> Rejecting...
            </>
          ) : (
            <>
              <X size={16} /> Reject Payment
            </>
          )}
        </button>
      </div>
    </div>
  );
}
