"use client";

import { useState } from "react";
import type { Order, OrderItem } from "@/lib/db/schema";
import Link from "next/link";
import { formatPrice, formatDateTime } from "@/lib/utils";
import {
  PaymentStatusBadge,
  OrderStatusBadge,
} from "@/components/ui/status-badge";
import { ChevronRight, Phone, MapPin, Package, Copy, Check } from "lucide-react";
import { getProductByName, getProductById } from "@/lib/products";

interface OrderCardProps {
  order: Order & { orderItems?: OrderItem[] };
}

export default function OrderCard({ order }: OrderCardProps) {
  const [copied, setCopied] = useState(false);
  const items = order.orderItems ?? [];

  const handleCopyDeliveryInfo = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const fullAddress = [order.deliveryAddress, order.city, order.province]
      .filter(Boolean)
      .join(", ");

    const textToCopy = `Recipient: ${order.customerName}\nPhone: ${order.customerPhone}\nAddress: ${fullAddress}\nNotes: ${order.notes || "None"}`;

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Link
      href={`/admin/orders/${order.id}`}
      className="block"
      aria-label={`View order ${order.orderNumber} for ${order.customerName}`}
    >
      <article className="neu-card group transition-all duration-200 hover:scale-[1.005]">
        {/* Header row */}
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p
              className="truncate text-sm font-bold"
              style={{ color: "var(--color-accent)" }}
            >
              {order.orderNumber}
            </p>
            <p
              className="mt-0.5 truncate text-base font-semibold"
              style={{ color: "var(--color-text-primary)" }}
            >
              {order.customerName}
            </p>
          </div>

          <div className="flex shrink-0 items-center gap-1.5">
            <p
              className="text-lg font-bold tabular-nums"
              style={{ color: "var(--color-text-primary)" }}
            >
              {formatPrice(order.total)}
            </p>
            <ChevronRight
              size={18}
              strokeWidth={2}
              style={{ color: "var(--color-text-muted)" }}
              className="transition-transform duration-150 group-hover:translate-x-0.5"
              aria-hidden="true"
            />
          </div>
        </div>

        {/* Customer contact & address info */}
        <div className="mt-2 space-y-1.5">
          <div className="flex items-center justify-between gap-2">
            <a
              href={`tel:${order.customerPhone}`}
              onClick={(e) => e.stopPropagation()}
              className="inline-flex items-center gap-1.5 text-xs text-[var(--color-text-secondary)] hover:text-[var(--color-accent)] transition-colors font-semibold"
            >
              <Phone
                size={12}
                strokeWidth={1.8}
                style={{ color: "var(--color-text-muted)" }}
                aria-hidden="true"
              />
              <span>{order.customerPhone}</span>
            </a>

            {/* One-Tap Copy Delivery Info Shortcut */}
            <button
              type="button"
              onClick={handleCopyDeliveryInfo}
              className={`neu-button text-[11px] px-2.5 py-1 flex items-center gap-1 font-semibold rounded-lg transition-all ${
                copied
                  ? "bg-emerald-500/10 text-emerald-600 border border-emerald-500/30"
                  : "neu-button-ghost text-[var(--color-accent)]"
              }`}
            >
              {copied ? (
                <>
                  <Check size={12} className="text-emerald-600" />
                  <span>Copied!</span>
                </>
              ) : (
                <>
                  <Copy size={12} />
                  <span>Copy Delivery Info</span>
                </>
              )}
            </button>
          </div>

          {order.deliveryAddress && (
            <div className="flex items-start gap-1.5">
              <MapPin
                size={12}
                strokeWidth={1.8}
                style={{ color: "var(--color-text-muted)" }}
                className="mt-0.5 shrink-0"
                aria-hidden="true"
              />
              <p
                className="text-xs line-clamp-1"
                style={{ color: "var(--color-text-secondary)" }}
              >
                {[order.deliveryAddress, order.city, order.province]
                  .filter(Boolean)
                  .join(", ")}
              </p>
            </div>
          )}
        </div>

        {/* Enriched Items Summary (if available) */}
        {items.length > 0 && (
          <div className="mt-3 pt-2.5 border-t border-[var(--color-neu-shadow-dark)]/20 space-y-1.5">
            <div className="flex items-center gap-1 text-[11px] font-bold text-[var(--color-text-secondary)] uppercase tracking-wider">
              <Package size={12} className="text-[var(--color-accent)]" />
              <span>Items ({items.reduce((acc, i) => acc + i.quantity, 0)})</span>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {items.map((item) => {
                const matched =
                  getProductByName(item.productName) ||
                  (item.productId ? getProductById(item.productId) : undefined);
                return (
                  <span
                    key={item.id}
                    className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md bg-[var(--color-neu-bg)] text-[var(--color-text-primary)] font-medium border border-[var(--color-neu-shadow-dark)]/30"
                  >
                    <span>{matched?.emoji || "📦"}</span>
                    <span>{matched?.name || item.productName}</span>
                    <span className="text-[10px] text-[var(--color-text-muted)]">
                      ×{item.quantity}
                    </span>
                  </span>
                );
              })}
            </div>
          </div>
        )}

        {/* Status badges */}
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <PaymentStatusBadge status={order.paymentStatus} />
          <OrderStatusBadge status={order.orderStatus} />
        </div>

        {/* Date */}
        <time
          dateTime={new Date(order.createdAt).toISOString()}
          className="mt-2 block text-xs"
          style={{ color: "var(--color-text-muted)" }}
        >
          {formatDateTime(order.createdAt)}
        </time>
      </article>
    </Link>
  );
}
"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { confirmPayment, rejectPayment } from "@/lib/actions/admin-orders";
import { Check, X, Loader2 } from "lucide-react";

interface PaymentVerifierActionsProps {
  orderId: number;
  orderNumber: string;
}

export default function PaymentVerifierActions({
  orderId,
  orderNumber,
}: PaymentVerifierActionsProps) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [rejectionReason, setRejectionReason] = useState("");
  const [activeAction, setActiveAction] = useState<"confirm" | "reject" | null>(null);

  const handleConfirm = () => {
    setActiveAction("confirm");
    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.append("orderId", String(orderId));

        const res = await confirmPayment(formData);
        if (res.success) {
          toast.success(`Payment confirmed for Order #${orderNumber}! 🎉`);
          router.refresh();
        } else {
          toast.error(res.error || "Failed to confirm payment.");
        }
      } catch (err: any) {
        toast.error(err.message || "An unexpected error occurred.");
      } finally {
        setActiveAction(null);
      }
    });
  };

  const handleReject = () => {
    setActiveAction("reject");
    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.append("orderId", String(orderId));
        formData.append("reason", rejectionReason);

        const res = await rejectPayment(formData);
        if (res.success) {
          toast.info(`Payment rejected for Order #${orderNumber}.`);
          router.refresh();
        } else {
          toast.error(res.error || "Failed to reject payment.");
        }
      } catch (err: any) {
        toast.error(err.message || "An unexpected error occurred.");
      } finally {
        setActiveAction(null);
      }
    });
  };

  return (
    <div className="space-y-2 pt-2">
      <button
        type="button"
        onClick={handleConfirm}
        disabled={isPending}
        className="neu-button neu-button-accent w-full text-xs py-2.5 flex items-center justify-center gap-1.5 font-bold rounded-xl"
      >
        {isPending && activeAction === "confirm" ? (
          <>
            <Loader2 size={15} className="animate-spin" /> Confirming...
          </>
        ) : (
          <>
            <Check size={16} /> Confirm Payment
          </>
        )}
      </button>

      <div className="space-y-2">
        <input
          type="text"
          value={rejectionReason}
          onChange={(e) => setRejectionReason(e.target.value)}
          placeholder="Rejection reason (optional)..."
          disabled={isPending}
          className="neu-input text-xs py-1.5 rounded-xl"
        />
        <button
          type="button"
          onClick={handleReject}
          disabled={isPending}
          className="neu-button neu-button-danger w-full text-xs py-2 flex items-center justify-center gap-1 font-semibold rounded-xl"
        >
          {isPending && activeAction === "reject" ? (
            <>
              <Loader2 size={14} className="animate-spin" /> Rejecting...
            </>
          ) : (
            <>
              <X size={16} /> Reject Payment
            </>
          )}
        </button>
      </div>
    </div>
  );
}
