"use client";

import React, { useState, useTransition } from "react";
import {
  Package,
  Layers,
  Tag,
  Plus,
  Edit3,
  Trash2,
  Search,
  Check,
  X,
  ChevronDown,
  ChevronUp,
  Loader2,
  Sparkles,
} from "lucide-react";
import { formatPrice } from "@/lib/utils";
import {
  createCategoryAction,
  createProductAction,
  updateProductAction,
  deleteProductAction,
  toggleProductAvailability,
} from "@/lib/actions/products";
import { toast } from "sonner";

interface Product {
  id: string;
  categoryId: string | null;
  name: string;
  fullName: string;
  price: number;
  emoji: string | null;
  isAvailable: boolean | null;
  sortOrder: number | null;
}

interface Category {
  id: string;
  name: string;
  icon: string | null;
  pill: string | null;
  sortOrder: number | null;
  isActive: boolean | null;
}

interface ProductCatalogManagerProps {
  categories: Category[];
  products: Product[];
}

export default function ProductCatalogManager({
  categories,
  products,
}: ProductCatalogManagerProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [collapsedCategories, setCollapsedCategories] = useState<Record<string, boolean>>({});

  // Modals state
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isAddProductOpen, setIsAddProductOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [deletingProduct, setDeletingProduct] = useState<Product | null>(null);

  // Form states
  const [categoryForm, setCategoryForm] = useState({
    name: "",
    icon: "💉",
    pill: "",
  });

  const [productForm, setProductForm] = useState({
    categoryId: categories[0]?.id || "",
    name: "",
    fullName: "",
    price: "",
    emoji: "💉",
  });

  const [isPending, startTransition] = useTransition();

  const toggleCategoryCollapse = (catId: string) => {
    setCollapsedCategories((prev) => ({
      ...prev,
      [catId]: !prev[catId],
    }));
  };

  // Filter items by search query
  const filteredProducts = products.filter((p) => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase().trim();
    return (
      p.name.toLowerCase().includes(q) ||
      p.fullName.toLowerCase().includes(q) ||
      p.id.toLowerCase().includes(q)
    );
  });

  // Group filtered products by category
  const productsByCat = new Map<string, Product[]>();
  for (const p of filteredProducts) {
    const catId = p.categoryId || "uncategorized";
    if (!productsByCat.has(catId)) {
      productsByCat.set(catId, []);
    }
    productsByCat.get(catId)!.push(p);
  }

  // Handle Add Category Submit
  const handleAddCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryForm.name.trim()) {
      toast.error("Category name is required");
      return;
    }

    startTransition(async () => {
      const res = await createCategoryAction(categoryForm);
      if (res.success) {
        toast.success(`Category "${categoryForm.name}" created!`);
        setIsAddCategoryOpen(false);
        setCategoryForm({ name: "", icon: "💉", pill: "" });
      } else {
        toast.error(res.error || "Failed to create category");
      }
    });
  };

  // Handle Add Product Submit
  const handleAddProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const priceNum = parseFloat(productForm.price);
    if (!productForm.name.trim() || !productForm.fullName.trim() || isNaN(priceNum)) {
      toast.error("Please fill in all product fields correctly");
      return;
    }

    startTransition(async () => {
      const res = await createProductAction({
        categoryId: productForm.categoryId,
        name: productForm.name,
        fullName: productForm.fullName,
        price: priceNum,
        emoji: productForm.emoji,
      });

      if (res.success) {
        toast.success(`Product "${productForm.name}" created!`);
        setIsAddProductOpen(false);
        setProductForm({
          categoryId: categories[0]?.id || "",
          name: "",
          fullName: "",
          price: "",
          emoji: "💉",
        });
      } else {
        toast.error(res.error || "Failed to create product");
      }
    });
  };

  // Handle Edit Product Submit
  const handleEditProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const priceNum = parseFloat(productForm.price);
    if (!productForm.name.trim() || !productForm.fullName.trim() || isNaN(priceNum)) {
      toast.error("Please provide valid product details");
      return;
    }

    startTransition(async () => {
      const res = await updateProductAction(editingProduct.id, {
        categoryId: productForm.categoryId,
        name: productForm.name,
        fullName: productForm.fullName,
        price: priceNum,
        emoji: productForm.emoji,
      });

      if (res.success) {
        toast.success(`Product "${productForm.name}" updated!`);
        setEditingProduct(null);
      } else {
        toast.error(res.error || "Failed to update product");
      }
    });
  };

  // Handle Delete Product Confirm
  const handleDeleteProductConfirm = async () => {
    if (!deletingProduct) return;
    startTransition(async () => {
      const res = await deleteProductAction(deletingProduct.id);
      if (res.success) {
        toast.success(`Product removed from catalog`);
        setDeletingProduct(null);
      } else {
        toast.error(res.error || "Failed to delete product");
      }
    });
  };

  // Handle Toggle Availability
  const handleToggleAvailability = async (product: Product) => {
    startTransition(async () => {
      const current = product.isAvailable ?? true;
      const res = await toggleProductAvailability(product.id, current);
      if (res.success) {
        toast.success(
          `${product.name} is now ${res.isAvailable ? "In Stock" : "Out of Stock"}`
        );
      } else {
        toast.error(res.error || "Failed to update availability");
      }
    });
  };

  // Open Edit Modal Helper
  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setProductForm({
      categoryId: product.categoryId || categories[0]?.id || "",
      name: product.name,
      fullName: product.fullName,
      price: String(product.price),
      emoji: product.emoji || "💉",
    });
  };

  return (
    <div className="px-4 py-6 md:px-8 space-y-6 max-w-7xl mx-auto">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[var(--color-text-primary)] flex items-center gap-2">
            <Package className="text-[var(--color-accent)]" size={26} /> Product Catalog &amp; CRUD
          </h1>
          <p className="text-xs text-[var(--color-text-secondary)] mt-0.5">
            Dynamic database-backed catalog synchronized with public APIs and checkout.
          </p>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-3 flex-wrap">
          <button
            onClick={() => setIsAddCategoryOpen(true)}
            className="neu-button text-xs font-semibold px-4 py-2.5 flex items-center gap-2 min-h-[44px]"
          >
            <Layers size={16} className="text-[var(--color-accent)]" />
            <span>+ Add Category</span>
          </button>
          <button
            onClick={() => {
              setProductForm({
                categoryId: categories[0]?.id || "",
                name: "",
                fullName: "",
                price: "",
                emoji: "💉",
              });
              setIsAddProductOpen(true);
            }}
            className="neu-button-accent text-xs font-semibold px-4 py-2.5 flex items-center gap-2 min-h-[44px]"
          >
            <Plus size={16} />
            <span>+ Add Product</span>
          </button>
        </div>
      </div>

      {/* Metrics & Search Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search
            size={16}
            className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--color-text-secondary)]"
          />
          <input
            type="text"
            placeholder="Search products by name, formula, or SKU..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="neu-input w-full pl-10 pr-9 py-2.5 text-xs text-[var(--color-text-primary)] rounded-xl"
          />
          {searchQuery && (
            <button
              onClick={() => setSearchQuery("")}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)]"
            >
              <X size={14} />
            </button>
          )}
        </div>

        <div className="flex items-center gap-2.5 self-end sm:self-auto">
          <div className="neu-card px-3 py-2 flex items-center gap-2 text-xs font-semibold">
            <Layers size={14} className="text-[var(--color-accent)]" />
            <span>{categories.length} Categories</span>
          </div>
          <div className="neu-card px-3 py-2 flex items-center gap-2 text-xs font-semibold">
            <Tag size={14} className="text-[var(--color-accent)]" />
            <span>{products.length} Products</span>
          </div>
        </div>
      </div>

      {/* Categories & Product Feed */}
      <div className="space-y-8">
        {categories.map((cat) => {
          const catProducts = productsByCat.get(cat.id) || [];
          if (searchQuery && catProducts.length === 0) return null;
          const isCollapsed = collapsedCategories[cat.id];

          return (
            <section key={cat.id} className="space-y-4">
              {/* Category Header */}
              <div
                onClick={() => toggleCategoryCollapse(cat.id)}
                className="neu-card px-4 py-3 flex items-center justify-between cursor-pointer select-none hover:scale-[1.002] transition-all"
              >
                <div className="flex items-center gap-3">
                  <span className="text-2xl" role="img" aria-label={cat.name}>
                    {cat.icon || "💉"}
                  </span>
                  <div>
                    <div className="flex items-center gap-2 flex-wrap">
                      <h2 className="text-sm md:text-base font-bold text-[var(--color-text-primary)]">
                        {cat.name}
                      </h2>
                      {cat.pill && (
                        <span className="text-[9px] uppercase font-bold tracking-wider px-2 py-0.5 rounded-full bg-[var(--color-accent-muted)] text-[var(--color-accent)] border border-[var(--color-accent)]/20">
                          {cat.pill}
                        </span>
                      )}
                    </div>
                    <span className="text-[11px] text-[var(--color-text-secondary)]">
                      {catProducts.length} items in category
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <span className="p-1 text-[var(--color-text-secondary)]">
                    {isCollapsed ? <ChevronDown size={18} /> : <ChevronUp size={18} />}
                  </span>
                </div>
              </div>

              {/* Items Grid */}
              {!isCollapsed && (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {catProducts.map((item) => {
                    const isAvailable = item.isAvailable ?? true;

                    return (
                      <div
                        key={item.id}
                        className={`neu-card p-4 flex flex-col justify-between gap-3 transition-all ${
                          !isAvailable ? "opacity-60 bg-[var(--color-neu-bg)]/60" : ""
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <div className="w-12 h-12 rounded-xl bg-[var(--color-neu-bg)] flex items-center justify-center text-2xl shrink-0 shadow-inner">
                            {item.emoji || "💉"}
                          </div>
                          <div className="min-w-0 flex-1">
                            <div className="flex items-center justify-between gap-1">
                              <h3 className="font-bold text-sm text-[var(--color-text-primary)] truncate">
                                {item.name}
                              </h3>
                            </div>
                            <p className="text-xs text-[var(--color-text-secondary)] truncate mt-0.5">
                              {item.fullName}
                            </p>
                            <p className="text-[10px] font-mono text-[var(--color-text-muted)] mt-1">
                              SKU: <span className="font-semibold text-[var(--color-text-secondary)]">{item.id}</span>
                            </p>
                          </div>
                        </div>

                        <div className="neu-divider my-0" />

                        {/* Price & Quick Controls */}
                        <div className="flex items-center justify-between gap-2 pt-1">
                          <div>
                            <span className="text-[10px] text-[var(--color-text-secondary)] block">Price</span>
                            <span className="text-base font-extrabold text-[var(--color-accent)] tabular-nums">
                              {formatPrice(item.price * 100)}
                            </span>
                          </div>

                          <div className="flex items-center gap-1.5">
                            {/* Stock Toggle */}
                            <button
                              onClick={() => handleToggleAvailability(item)}
                              title={isAvailable ? "Mark Out of Stock" : "Mark In Stock"}
                              className={`px-2.5 py-1.5 rounded-lg text-xs font-semibold flex items-center gap-1 transition-all ${
                                isAvailable
                                  ? "bg-emerald-500/10 text-emerald-600 border border-emerald-500/20"
                                  : "bg-rose-500/10 text-rose-500 border border-rose-500/20"
                              }`}
                            >
                              <span
                                className={`w-2 h-2 rounded-full ${
                                  isAvailable ? "bg-emerald-500" : "bg-rose-500"
                                }`}
                              />
                              <span className="text-[10px]">
                                {isAvailable ? "In Stock" : "Out of Stock"}
                              </span>
                            </button>

                            {/* Edit Button */}
                            <button
                              onClick={() => openEditModal(item)}
                              title="Edit product"
                              className="neu-button p-2 text-[var(--color-text-secondary)] hover:text-[var(--color-accent)] rounded-lg min-h-[36px] min-w-[36px] flex items-center justify-center"
                            >
                              <Edit3 size={14} />
                            </button>

                            {/* Delete Button */}
                            <button
                              onClick={() => setDeletingProduct(item)}
                              title="Delete product"
                              className="neu-button p-2 text-[var(--color-text-secondary)] hover:text-rose-500 rounded-lg min-h-[36px] min-w-[36px] flex items-center justify-center"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </section>
          );
        })}
      </div>

      {/* ========================================================= */}
      {/* ADD CATEGORY MODAL */}
      {/* ========================================================= */}
      {isAddCategoryOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="neu-card w-full max-w-md p-6 rounded-2xl space-y-5 bg-[var(--color-neu-surface)] border border-[var(--color-neu-shadow-dark)]/20 shadow-2xl">
            <div className="flex items-center justify-between pb-2 border-b border-[var(--color-neu-shadow-dark)]/20">
              <h3 className="text-lg font-bold text-[var(--color-text-primary)] flex items-center gap-2">
                <Layers className="text-[var(--color-accent)]" size={20} /> Add New Category
              </h3>
              <button
                onClick={() => setIsAddCategoryOpen(false)}
                className="text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] p-1"
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={handleAddCategorySubmit} className="space-y-4 text-xs">
              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Category Name *
                </label>
                <input
                  type="text"
                  required
                  placeholder="e.g. Tirzepatide Complete Set"
                  value={categoryForm.name}
                  onChange={(e) =>
                    setCategoryForm((prev) => ({ ...prev, name: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                    Icon / Emoji
                  </label>
                  <input
                    type="text"
                    placeholder="💉"
                    value={categoryForm.icon}
                    onChange={(e) =>
                      setCategoryForm((prev) => ({ ...prev, icon: e.target.value }))
                    }
                    className="neu-input w-full px-3 py-2.5 rounded-xl text-xs text-center text-lg"
                  />
                </div>
                <div>
                  <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                    Badge / Pill Text
                  </label>
                  <input
                    type="text"
                    placeholder="e.g. w/ supplies"
                    value={categoryForm.pill}
                    onChange={(e) =>
                      setCategoryForm((prev) => ({ ...prev, pill: e.target.value }))
                    }
                    className="neu-input w-full px-3 py-2.5 rounded-xl text-xs"
                  />
                </div>
              </div>

              <div className="flex items-center justify-end gap-3 pt-3 border-t border-[var(--color-neu-shadow-dark)]/20">
                <button
                  type="button"
                  onClick={() => setIsAddCategoryOpen(false)}
                  className="neu-button px-4 py-2 text-xs font-semibold rounded-xl"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isPending}
                  className="neu-button-accent px-5 py-2 text-xs font-semibold rounded-xl flex items-center gap-1.5"
                >
                  {isPending ? <Loader2 size={14} className="animate-spin" /> : <Check size={14} />}
                  <span>Create Category</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================================= */}
      {/* ADD PRODUCT MODAL */}
      {/* ========================================================= */}
      {isAddProductOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="neu-card w-full max-w-lg p-6 rounded-2xl space-y-5 bg-[var(--color-neu-surface)] border border-[var(--color-neu-shadow-dark)]/20 shadow-2xl">
            <div className="flex items-center justify-between pb-2 border-b border-[var(--color-neu-shadow-dark)]/20">
              <h3 className="text-lg font-bold text-[var(--color-text-primary)] flex items-center gap-2">
                <Plus className="text-[var(--color-accent)]" size={20} /> Add New Product
              </h3>
              <button
                onClick={() => setIsAddProductOpen(false)}
                className="text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] p-1"
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={handleAddProductSubmit} className="space-y-4 text-xs">
              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Category *
                </label>
                <select
                  required
                  value={productForm.categoryId}
                  onChange={(e) =>
                    setProductForm((prev) => ({ ...prev, categoryId: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs bg-[var(--color-neu-bg)] text-[var(--color-text-primary)]"
                >
                  {categories.map((cat) => (
                    <option key={cat.id} value={cat.id}>
                      {cat.icon} {cat.name}
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2">
                  <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                    Short Name *
                  </label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. TIR 10"
                    value={productForm.name}
                    onChange={(e) =>
                      setProductForm((prev) => ({ ...prev, name: e.target.value }))
                    }
                    className="neu-input w-full px-3 py-2.5 rounded-xl text-xs"
                  />
                </div>
                <div>
                  <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                    Emoji
                  </label>
                  <input
                    type="text"
                    placeholder="💉"
                    value={productForm.emoji}
                    onChange={(e) =>
                      setProductForm((prev) => ({ ...prev, emoji: e.target.value }))
                    }
                    className="neu-input w-full px-3 py-2.5 rounded-xl text-xs text-center text-lg"
                  />
                </div>
              </div>

              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Full Display Name *
                </label>
                <input
                  type="text"
                  required
                  placeholder="e.g. TIR 10 — Complete Set"
                  value={productForm.fullName}
                  onChange={(e) =>
                    setProductForm((prev) => ({ ...prev, fullName: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs"
                />
              </div>

              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Price (₱ PHP) *
                </label>
                <input
                  type="number"
                  required
                  min="0"
                  step="1"
                  placeholder="1100"
                  value={productForm.price}
                  onChange={(e) =>
                    setProductForm((prev) => ({ ...prev, price: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs font-mono font-semibold"
                />
              </div>

              <div className="flex items-center justify-end gap-3 pt-3 border-t border-[var(--color-neu-shadow-dark)]/20">
                <button
                  type="button"
                  onClick={() => setIsAddProductOpen(false)}
                  className="neu-button px-4 py-2 text-xs font-semibold rounded-xl"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isPending}
                  className="neu-button-accent px-5 py-2 text-xs font-semibold rounded-xl flex items-center gap-1.5"
                >
                  {isPending ? <Loader2 size={14} className="animate-spin" /> : <Check size={14} />}
                  <span>Save Product</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================================= */}
      {/* EDIT PRODUCT MODAL */}
      {/* ========================================================= */}
      {editingProduct && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="neu-card w-full max-w-lg p-6 rounded-2xl space-y-5 bg-[var(--color-neu-surface)] border border-[var(--color-neu-shadow-dark)]/20 shadow-2xl">
            <div className="flex items-center justify-between pb-2 border-b border-[var(--color-neu-shadow-dark)]/20">
              <h3 className="text-lg font-bold text-[var(--color-text-primary)] flex items-center gap-2">
                <Edit3 className="text-[var(--color-accent)]" size={20} /> Edit Product ({editingProduct.id})
              </h3>
              <button
                onClick={() => setEditingProduct(null)}
                className="text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] p-1"
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={handleEditProductSubmit} className="space-y-4 text-xs">
              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Category *
                </label>
                <select
                  required
                  value={productForm.categoryId}
                  onChange={(e) =>
                    setProductForm((prev) => ({ ...prev, categoryId: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs bg-[var(--color-neu-bg)] text-[var(--color-text-primary)]"
                >
                  {categories.map((cat) => (
                    <option key={cat.id} value={cat.id}>
                      {cat.icon} {cat.name}
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2">
                  <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                    Short Name *
                  </label>
                  <input
                    type="text"
                    required
                    value={productForm.name}
                    onChange={(e) =>
                      setProductForm((prev) => ({ ...prev, name: e.target.value }))
                    }
                    className="neu-input w-full px-3 py-2.5 rounded-xl text-xs"
                  />
                </div>
                <div>
                  <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                    Emoji
                  </label>
                  <input
                    type="text"
                    value={productForm.emoji}
                    onChange={(e) =>
                      setProductForm((prev) => ({ ...prev, emoji: e.target.value }))
                    }
                    className="neu-input w-full px-3 py-2.5 rounded-xl text-xs text-center text-lg"
                  />
                </div>
              </div>

              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Full Display Name *
                </label>
                <input
                  type="text"
                  required
                  value={productForm.fullName}
                  onChange={(e) =>
                    setProductForm((prev) => ({ ...prev, fullName: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs"
                />
              </div>

              <div>
                <label className="font-semibold text-[var(--color-text-primary)] block mb-1">
                  Price (₱ PHP) *
                </label>
                <input
                  type="number"
                  required
                  min="0"
                  step="1"
                  value={productForm.price}
                  onChange={(e) =>
                    setProductForm((prev) => ({ ...prev, price: e.target.value }))
                  }
                  className="neu-input w-full px-3 py-2.5 rounded-xl text-xs font-mono font-semibold"
                />
              </div>

              <div className="flex items-center justify-end gap-3 pt-3 border-t border-[var(--color-neu-shadow-dark)]/20">
                <button
                  type="button"
                  onClick={() => setEditingProduct(null)}
                  className="neu-button px-4 py-2 text-xs font-semibold rounded-xl"
                >
                  Cancel
                </button>
                <button
                  type="submit"
