"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  ShoppingBag,
  Package,
  BarChart2,
  Settings,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface NavItem {
  href: string;
  label: string;
  icon: React.ComponentType<{ size?: number; strokeWidth?: number; className?: string }>;
}

const NAV_ITEMS: NavItem[] = [
  { href: "/admin", label: "Dashboard", icon: LayoutDashboard },
  { href: "/admin/orders", label: "Orders", icon: ShoppingBag },
  { href: "/admin/products", label: "Products", icon: Package },
  { href: "/admin/analytics", label: "Analytics", icon: BarChart2 },
  { href: "/admin/settings", label: "Settings", icon: Settings },
];

export default function BottomNav() {
  const pathname = usePathname();

  function isActive(href: string): boolean {
    if (href === "/admin") return pathname === "/admin";
    return pathname.startsWith(href);
  }

  return (
    <nav
      className="bottom-nav md:hidden border-t border-[var(--color-neu-shadow-dark)]"
      aria-label="Mobile navigation"
    >
      <ul className="flex items-center justify-around px-2 py-1" role="list">
        {NAV_ITEMS.map(({ href, label, icon: Icon }) => {
          const active = isActive(href);
          return (
            <li key={href} className="flex-1">
              <Link
                href={href}
                aria-label={label}
                aria-current={active ? "page" : undefined}
                className={cn(
                  "flex flex-col items-center justify-center gap-1 py-1.5 min-h-[52px] w-full rounded-xl",
                  "transition-all duration-200 select-none",
                  active
                    ? "text-[var(--color-accent)] font-bold shadow-[var(--shadow-neu-inset)] bg-[var(--color-accent-muted)]"
                    : "text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)]"
                )}
              >
                <div className="relative flex items-center justify-center">
                  <Icon
                    size={20}
                    strokeWidth={active ? 2.4 : 1.8}
                  />
                  {active && (
                    <span className="absolute -bottom-1 w-1 h-1 rounded-full bg-[var(--color-accent)]" />
                  )}
                </div>
                <span
                  className={cn(
                    "text-[10px] tracking-tight leading-tight",
                    active ? "font-bold text-[var(--color-accent-dark)]" : "font-medium"
                  )}
                >
                  {label}
                </span>
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
