export function buildShipmentGroups(items, preference) {
  if (preference === "together") {
    return [{ key: "combined", kind: "combined", batchId: null, lines: items, quantity: items.reduce((sum, item) => sum + item.quantity, 0) }];
  }

  const groups = new Map();
  for (const item of items) {
    const kind = item.kind === "on_hand" ? "on_hand" : "group_buy";
    const batchId = kind === "group_buy" ? String(item.batchId) : null;
    const key = kind === "on_hand" ? "on_hand" : `batch:${batchId}`;
    const group = groups.get(key) ?? { key, kind, batchId, lines: [], quantity: 0 };
    group.lines.push(item);
    group.quantity += item.quantity;
    groups.set(key, group);
  }
  return [...groups.values()];
}

export function calculateOrderTotal(items, preference, shippingRate) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const shipments = buildShipmentGroups(items, preference).map((group) => ({
    ...group,
    shipping: shippingRate(group.quantity),
  }));
  const shipping = shipments.reduce((sum, shipment) => sum + shipment.shipping, 0);
  return { subtotal, shipping, total: subtotal + shipping, shipments };
}

export function calculateShippingRate(config, region, quantity) {
  const normalized = String(region || "other").trim().toLowerCase();
  let rates = config?.[normalized];
  if (!rates) {
    if (normalized.includes("luzon")) rates = config?.luzon;
    else if (normalized.includes("visaya")) rates = config?.visayas;
    else if (normalized.includes("mindanao")) rates = config?.mindanao;
    else rates = config?.other;
  }
  if (!rates) return 0;
  if (quantity <= 1) return Number(rates["1"] ?? 0);
  if (quantity === 2) return Number(rates["2"] ?? 0);
  return Number(rates.max ?? 0);
}

export function isBatchOrderable(batch, now = new Date()) {
  return batch.status === "open" && new Date(batch.deadline).getTime() > now.getTime();
}
import test from "node:test";
import assert from "node:assert/strict";
import { buildShipmentGroups, calculateOrderTotal, isBatchOrderable } from "../src/commerce.mjs";

const items = [
  { productId: "label-1", name: "Label", kind: "on_hand", quantity: 2, price: 300, stock: 8 },
  { productId: "printer-1", name: "Printer", kind: "on_hand", quantity: 1, price: 1700, stock: 1 },
  { productId: "gb-1", name: "Group item A", kind: "group_buy", batchId: "batch-a", quantity: 1, price: 500 },
  { productId: "gb-2", name: "Group item B", kind: "group_buy", batchId: "batch-a", quantity: 3, price: 250 },
  { productId: "gb-3", name: "Group item C", kind: "group_buy", batchId: "batch-b", quantity: 2, price: 900 },
];

test("combined shipping creates one shipment for all cart lines", () => {
  const groups = buildShipmentGroups(items, "together");
  assert.equal(groups.length, 1);
  assert.equal(groups[0].quantity, 9);
  assert.equal(groups[0].lines.length, 5);
});

test("separate shipping groups on-hand lines and each buy batch", () => {
  const groups = buildShipmentGroups(items, "separate");
  assert.deepEqual(groups.map((group) => [group.kind, group.batchId, group.quantity]), [
    ["on_hand", null, 3],
    ["group_buy", "batch-a", 4],
    ["group_buy", "batch-b", 2],
  ]);
});

test("order totals use one shipping rate per shipment group", () => {
  const total = calculateOrderTotal(items, "separate", (quantity) => quantity === 3 ? 100 : 150);
  assert.equal(total.subtotal, 5350);
  assert.equal(total.shipping, 400);
  assert.equal(total.total, 5750);
});

test("batch closes at deadline and closed status", () => {
  const now = new Date("2026-10-28T12:00:00.000Z");
  assert.equal(isBatchOrderable({ status: "open", deadline: "2026-10-28T12:01:00.000Z" }, now), true);
  assert.equal(isBatchOrderable({ status: "open", deadline: "2026-10-28T11:59:00.000Z" }, now), false);
  assert.equal(isBatchOrderable({ status: "closed", deadline: "2026-10-29T12:00:00.000Z" }, now), false);
});
export type GroupBuyItemInput = { productId: string; quantity: number };

type CommerceProduct = {
  id: string;
  name: string;
  fullName: string;
  storefrontKey: string;
  kind: "standard" | "on_hand" | "group_buy";
  price: number;
  stock: number;
  isAvailable: boolean | null;
  batchId: number | null;
};

type CommerceBatch = {
  id: number;
  status: string;
  deadline: string | Date;
};

type ShippingRates = Record<string, Record<string, number>>;

function isOrderable(batch: CommerceBatch | undefined, now: Date) {
  return Boolean(
    batch &&
      batch.status === "open" &&
      new Date(batch.deadline).getTime() > now.getTime()
  );
}

function getShippingRate(config: ShippingRates, region: string, quantity: number) {
  const normalized = region.trim().toLowerCase();
  let rates = config[normalized];
  if (!rates) {
    if (normalized.includes("luzon")) rates = config.luzon;
    else if (normalized.includes("visaya")) rates = config.visayas;
    else if (normalized.includes("mindanao")) rates = config.mindanao;
    else rates = config.other;
  }
  if (!rates) throw new Error("Shipping is unavailable for this region.");
  return quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
}

export function prepareGroupBuyOrder(input: {
  items: Array<GroupBuyItemInput & { price?: number }>;
  shipmentPreference: "together" | "separate";
  region: string;
  shippingConfig: ShippingRates;
  products: Map<string, CommerceProduct>;
  batches: Map<number, CommerceBatch>;
  now?: Date;
}) {
  if (!input.items.length) throw new Error("Cart is empty.");

  const quantities = new Map<string, number>();
  for (const item of input.items) {
    const quantity = Number(item.quantity);
    if (!item.productId || !Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
      throw new Error("Invalid cart item.");
    }
    quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + quantity);
  }

  const now = input.now ?? new Date();
  const orderItems = [...quantities].map(([productId, quantity]) => {
    const product = input.products.get(productId);
    if (
      !product ||
      product.storefrontKey !== "tindahan" ||
      product.kind === "standard" ||
      !product.isAvailable
    ) {
      throw new Error("A product is no longer available. Refresh the catalog and try again.");
    }
    if (product.kind === "on_hand" && product.stock < quantity) {
      throw new Error(`Not enough stock for ${product.name}.`);
    }
    if (product.kind === "group_buy" && !isOrderable(product.batchId ? input.batches.get(product.batchId) : undefined, now)) {
      throw new Error(`The group-buy batch for ${product.name} is closed.`);
    }
    const unitPrice = Math.round(product.price * 100);
    return {
      productId: product.id,
      productName: product.fullName,
      productKind: product.kind,
      batchId: product.batchId,
      unitPrice,
      quantity,
      subtotal: unitPrice * quantity,
    };
  });

  const groups: Array<{ kind: "combined" | "on_hand" | "group_buy"; batchId: number | null; itemIndexes: number[]; quantity: number }> = [];
  if (input.shipmentPreference === "together") {
    groups.push({
      kind: "combined",
      batchId: null,
      itemIndexes: orderItems.map((_, index) => index),
      quantity: orderItems.reduce((sum, item) => sum + item.quantity, 0),
    });
  } else {
    const groupMap = new Map<string, (typeof groups)[number]>();
    orderItems.forEach((item, index) => {
      const kind = item.productKind === "on_hand" ? "on_hand" : "group_buy";
      const key = kind === "on_hand" ? "on_hand" : `batch:${item.batchId}`;
      const group = groupMap.get(key) ?? {
        kind,
        batchId: kind === "group_buy" ? item.batchId : null,
        itemIndexes: [],
        quantity: 0,
      };
      group.itemIndexes.push(index);
      group.quantity += item.quantity;
      groupMap.set(key, group);
    });
    groups.push(...groupMap.values());
  }

  const shipments = groups.map((group) => ({
    ...group,
    shippingFee: Math.round(getShippingRate(input.shippingConfig, input.region, group.quantity) * 100),
  }));
  const subtotal = orderItems.reduce((sum, item) => sum + item.subtotal, 0);
  const shippingFee = shipments.reduce((sum, shipment) => sum + shipment.shippingFee, 0);
  return {
    items: orderItems.map((item, itemIndex) => ({
      ...item,
      shipmentIndex: shipments.findIndex((shipment) => shipment.itemIndexes.includes(itemIndex)),
    })),
    shipments,
    subtotal,
    shippingFee,
    total: subtotal + shippingFee,
  };
}
import test from "node:test";
import assert from "node:assert/strict";
import { prepareGroupBuyOrder } from "./commerce";

const products = new Map([
  ["label", { id: "label", name: "Label", fullName: "Laser Label", storefrontKey: "tindahan", kind: "on_hand", price: 300, stock: 3, isAvailable: true, batchId: null }],
  ["gb-a", { id: "gb-a", name: "Tea A", fullName: "Tea A", storefrontKey: "tindahan", kind: "group_buy", price: 500, stock: 0, isAvailable: true, batchId: 10 }],
]);
const batches = new Map([[10, { id: 10, status: "open", deadline: "2026-10-29T12:00:00.000Z" }]]);
const shippingConfig = {
  luzon: { "1": 80, "2": 100, max: 120 },
  visayas: { "1": 90, "2": 120, max: 150 },
};
const now = new Date("2026-10-28T12:00:00.000Z");

test("uses database prices and calculates one area rate per shipment", () => {
  const order = prepareGroupBuyOrder({
    items: [{ productId: "label", quantity: 2, price: 1 }],
    shipmentPreference: "separate",
    region: "luzon",
    shippingConfig,
    products,
    batches,
    now,
  });
  assert.equal(order.subtotal, 60000);
  assert.equal(order.shippingFee, 10000);
  assert.equal(order.total, 70000);
  assert.equal(order.items[0].unitPrice, 30000);
});

test("separate shipping produces an on-hand shipment and a shipment per batch", () => {
  const order = prepareGroupBuyOrder({
    items: [
      { productId: "label", quantity: 1 },
      { productId: "gb-a", quantity: 2 },
    ],
    shipmentPreference: "separate",
    region: "luzon",
    shippingConfig,
    products,
    batches,
    now,
  });
  assert.deepEqual(order.shipments.map((shipment) => [shipment.kind, shipment.batchId, shipment.shippingFee]), [
    ["on_hand", null, 8000],
    ["group_buy", 10, 10000],
  ]);
});

test("rejects unavailable stock and expired batches", () => {
  assert.throws(() => prepareGroupBuyOrder({
    items: [{ productId: "label", quantity: 4 }],
    shipmentPreference: "together", region: "luzon", shippingConfig, products, batches, now,
  }), /not enough stock/i);
  assert.throws(() => prepareGroupBuyOrder({
    items: [{ productId: "gb-a", quantity: 1 }],
    shipmentPreference: "together", region: "luzon", shippingConfig, products,
    batches: new Map([[10, { id: 10, status: "open", deadline: "2026-10-28T11:00:00.000Z" }]]), now,
  }), /batch.*closed/i);
});
