const patch = "*** Begin Patch
*** Add File: C:\Users\ckzz2\OneDrive\Documents\GitHub\admin-pbc\drizzle\0001_tindahan_group_buy.sql
+DO $$ BEGIN
+  CREATE TYPE storefront_key AS ENUM ('main', 'tindahan');
+EXCEPTION WHEN duplicate_object THEN NULL;
+END $$;
+
+DO $$ BEGIN
+  CREATE TYPE product_kind AS ENUM ('standard', 'on_hand', 'group_buy');
+EXCEPTION WHEN duplicate_object THEN NULL;
+END $$;
+
+DO $$ BEGIN
+  CREATE TYPE group_buy_batch_status AS ENUM ('open', 'closed', 'ordered', 'arrived');
+EXCEPTION WHEN duplicate_object THEN NULL;
+END $$;
+
+DO $$ BEGIN
+  CREATE TYPE shipment_kind AS ENUM ('combined', 'on_hand', 'group_buy');
+EXCEPTION WHEN duplicate_object THEN NULL;
+END $$;
+
+DO $$ BEGIN
+  CREATE TYPE shipment_status AS ENUM ('processing', 'ready_to_ship', 'shipped', 'completed');
+EXCEPTION WHEN duplicate_object THEN NULL;
+END $$;
+
+CREATE TABLE IF NOT EXISTS group_buy_batches (
+  id serial PRIMARY KEY,
+  name text NOT NULL,
+  status group_buy_batch_status NOT NULL DEFAULT 'open',
+  deadline timestamptz NOT NULL,
+  eta timestamptz,
+  created_at timestamptz NOT NULL DEFAULT now(),
+  updated_at timestamptz NOT NULL DEFAULT now()
+);
+CREATE INDEX IF NOT EXISTS group_buy_batches_status_deadline_idx ON group_buy_batches(status, deadline);
+
+ALTER TABLE categories ADD COLUMN IF NOT EXISTS storefront_key storefront_key NOT NULL DEFAULT 'main';
+ALTER TABLE products ADD COLUMN IF NOT EXISTS storefront_key storefront_key NOT NULL DEFAULT 'main';
+ALTER TABLE products ADD COLUMN IF NOT EXISTS kind product_kind NOT NULL DEFAULT 'standard';
+ALTER TABLE products ADD COLUMN IF NOT EXISTS batch_id integer REFERENCES group_buy_batches(id) ON DELETE SET NULL;
+ALTER TABLE products ADD COLUMN IF NOT EXISTS compare_at_price integer;
+ALTER TABLE products ADD COLUMN IF NOT EXISTS description text;
+ALTER TABLE products ADD COLUMN IF NOT EXISTS image_url text;
+ALTER TABLE products ADD COLUMN IF NOT EXISTS stock integer NOT NULL DEFAULT 0;
+
+ALTER TABLE orders ADD COLUMN IF NOT EXISTS storefront_key storefront_key NOT NULL DEFAULT 'main';
+ALTER TABLE orders ADD COLUMN IF NOT EXISTS shipment_preference text;
+
+CREATE TABLE IF NOT EXISTS order_shipments (
+  id serial PRIMARY KEY,
+  order_id integer NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
+  kind shipment_kind NOT NULL,
+  batch_id integer REFERENCES group_buy_batches(id) ON DELETE SET NULL,
+  shipping_fee integer NOT NULL DEFAULT 0,
+  status shipment_status NOT NULL DEFAULT 'processing',
+  created_at timestamptz NOT NULL DEFAULT now(),
+  updated_at timestamptz NOT NULL DEFAULT now()
+);
+CREATE INDEX IF NOT EXISTS order_shipments_order_id_idx ON order_shipments(order_id);
+
+ALTER TABLE order_items ADD COLUMN IF NOT EXISTS product_kind product_kind NOT NULL DEFAULT 'standard';
+ALTER TABLE order_items ADD COLUMN IF NOT EXISTS batch_id integer REFERENCES group_buy_batches(id) ON DELETE SET NULL;
+ALTER TABLE order_items ADD COLUMN IF NOT EXISTS shipment_id integer REFERENCES order_shipments(id) ON DELETE SET NULL;
+
+CREATE INDEX IF NOT EXISTS products_storefront_kind_idx ON products(storefront_key, kind);
+CREATE INDEX IF NOT EXISTS products_batch_id_idx ON products(batch_id);
+
+CREATE OR REPLACE FUNCTION create_tindahan_order(p_order jsonb, p_shipments jsonb, p_items jsonb)
+RETURNS jsonb LANGUAGE plpgsql AS $$
+DECLARE
+  v_order_id integer;
+  v_shipment record;
+  v_shipment_id integer;
+  v_item record;
+BEGIN
+  INSERT INTO orders (
+    order_number, storefront_key, shipment_preference, customer_name, customer_phone,
+    customer_email, delivery_address, city, province, postal_code, shipping_method,
+    shipping_fee, payment_method, payment_proof_file_id, payment_status, order_status,
+    subtotal, total, notes, created_at, updated_at
+  ) VALUES (
+    p_order->>'orderNumber', 'tindahan', p_order->>'shipmentPreference',
+    p_order->>'customerName', p_order->>'customerPhone', NULLIF(p_order->>'customerEmail', ''),
+    p_order->>'deliveryAddress', p_order->>'city', p_order->>'province',
+    NULLIF(p_order->>'postalCode', ''), p_order->>'shippingMethod',
+    (p_order->>'shippingFee')::integer, p_order->>'paymentMethod', p_order->>'paymentProofFileId',
+    'under_verification', 'payment_verification', (p_order->>'subtotal')::integer,
+    (p_order->>'total')::integer, NULLIF(p_order->>'notes', ''), now(), now()
+  ) RETURNING id INTO v_order_id;
+
+  FOR v_shipment IN
+    SELECT value, (ordinality - 1)::integer AS idx
+    FROM jsonb_array_elements(p_shipments) WITH ORDINALITY
+  LOOP
+    INSERT INTO order_shipments(order_id, kind, batch_id, shipping_fee)
+    VALUES (
+      v_order_id,
+      (v_shipment.value->>'kind')::shipment_kind,
+      NULLIF(v_shipment.value->>'batchId', '')::integer,
+      (v_shipment.value->>'shippingFee')::integer
+    ) RETURNING id INTO v_shipment_id;
+
+    UPDATE order_items
+    SET shipment_id = v_shipment_id
+    WHERE order_id = v_order_id AND id = -1;
+  END LOOP;
+
+  FOR v_item IN
+    SELECT value FROM jsonb_array_elements(p_items)
+  LOOP
+    INSERT INTO order_items (
+      order_id, product_id, product_kind, batch_id, shipment_id,
+      product_name, unit_price, quantity, subtotal
+    ) VALUES (
+      v_order_id, v_item.value->>'productId', (v_item.value->>'productKind')::product_kind,
+      NULLIF(v_item.value->>'batchId', '')::integer,
+      (SELECT id FROM order_shipments WHERE order_id = v_order_id
+       ORDER BY id OFFSET (v_item.value->>'shipmentIndex')::integer LIMIT 1),
+      v_item.value->>'productName', (v_item.value->>'unitPrice')::integer,
+      (v_item.value->>'quantity')::integer, (v_item.value->>'subtotal')::integer
+    );
+  END LOOP;
+
+  INSERT INTO order_events(order_id, event_type, description) VALUES
+    (v_order_id, 'order_submitted', 'Tindahan ni Tinapa group-buy order submitted.'),
+    (v_order_id, 'payment_proof_uploaded', 'Payment proof attached with order.');
+
+  RETURN jsonb_build_object('id', v_order_id, 'orderNumber', p_order->>'orderNumber');
+END;
+$$;
+
+CREATE OR REPLACE FUNCTION confirm_tindahan_payment(p_order_id integer)
+RETURNS text LANGUAGE plpgsql AS $$
+DECLARE
+  v_storefront storefront_key;
+  v_payment_status payment_status;
+BEGIN
+  SELECT storefront_key, payment_status INTO v_storefront, v_payment_status
+  FROM orders WHERE id = p_order_id FOR UPDATE;
+
+  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
+  IF v_storefront <> 'tindahan' THEN RAISE EXCEPTION 'NOT_TINDAHAN_ORDER'; END IF;
+  IF v_payment_status = 'paid' THEN RETURN 'already_paid'; END IF;
+  IF v_payment_status <> 'under_verification' THEN RAISE EXCEPTION 'PAYMENT_NOT_UNDER_VERIFICATION'; END IF;
+
+  PERFORM p.id
+  FROM products p
+  JOIN (
+    SELECT product_id, sum(quantity)::integer AS quantity
+    FROM order_items
+    WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
+    GROUP BY product_id
+  ) requested ON requested.product_id = p.id
+  ORDER BY p.id
+  FOR UPDATE OF p;
+
+  IF EXISTS (
+    SELECT 1
+    FROM products p
+    JOIN (
+      SELECT product_id, sum(quantity)::integer AS quantity
+      FROM order_items
+      WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
+      GROUP BY product_id
+    ) requested ON requested.product_id = p.id
+    WHERE p.stock < requested.quantity
+  ) THEN RAISE EXCEPTION 'ON_HAND_STOCK_INSUFFICIENT'; END IF;
+
+  UPDATE products p
+  SET stock = p.stock - requested.quantity
+  FROM (
+    SELECT product_id, sum(quantity)::integer AS quantity
+    FROM order_items
+    WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
+    GROUP BY product_id
+  ) requested
+  WHERE requested.product_id = p.id;
+
+  UPDATE orders
+  SET payment_status = 'paid', order_status = 'processing', updated_at = now()
+  WHERE id = p_order_id;
+
+  INSERT INTO order_events(order_id, event_type, description) VALUES
+    (p_order_id, 'payment_confirmed', 'Payment confirmed by seller.'),
+    (p_order_id, 'order_processing', 'Order is now being processed.');
+
+  RETURN 'confirmed';
+END;
+$$;
*** End Patch";
text(await tools.apply_patch(patch));

