              </div>
              <div className="flex justify-between">
                <span>Shipping ({order.shippingMethod})</span>
                <span className="font-semibold">{formatPrice(order.shippingFee)}</span>
              </div>
              <div className="flex justify-between text-base font-bold text-[var(--color-text-primary)] pt-2 border-t border-[var(--color-neu-shadow-dark)]/30">
