"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";

const API = (process.env.NEXT_PUBLIC_ADMIN_API_URL || "https://admin-pbc.vercel.app").replace(/\/$/, "");

export default function TrackOrderPage() {
  const [result, setResult] = useState<Record<string, unknown> | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  async function track(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError(""); setResult(null);
    const form = new FormData(event.currentTarget);
    try {
      const response = await fetch(`${API}/api/group-buy/track`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ orderNumber: form.get("orderNumber"), phone: form.get("phone") }) });
      const data = await response.json();
      if (!response.ok || !data.success) throw new Error(data.error || "We couldn't find that order. Check your details and try again.");
      setResult(data.order ?? data);
    } catch (err) { setError(err instanceof Error ? err.message : "Tracking is unavailable right now."); }
    finally { setBusy(false); }
  }
  const order = result && ("order" in result ? result.order as Record<string, unknown> : result);
  const items = Array.isArray(order?.items) ? order.items as Array<Record<string, unknown>> : Array.isArray(order?.orderItems) ? order.orderItems as Array<Record<string, unknown>> : [];
  const shipments = Array.isArray(order?.shipments) ? order.shipments as Array<Record<string, unknown>> : [];
  return <main className="track-page"><div className="notice-strip"><span>GOOD THINGS, GATHERED TOGETHER</span><span>GROUP BUY • ON-HAND FINDS • SMALL HAPPY MAIL</span></div><header className="topbar wrap"><Link href="/" className="brand"><span className="brand-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link><Link className="back-link" href="/">← Back to shop</Link></header><section className="track-card"><span className="eyebrow">YOUR HAPPY MAIL</span><h1>Track your order<span>.</span></h1><p>Enter your order number and the phone number used at checkout.</p><form onSubmit={track} className="track-form"><label>Order number<input name="orderNumber" className="field" placeholder="TN-2026-0001" required/></label><label>Mobile number<input name="phone" className="field" inputMode="tel" required/></label><button className="button primary" type="submit" disabled={busy}>{busy ? "Looking it up…" : "Find my order →"}</button></form>{error && <p className="form-error" role="alert">{error}</p>}{order && <div className="tracking-result"><div className="tracking-top"><div><span className="eyebrow">ORDER {String(order.orderNumber ?? "")}</span><h2>{String(order.orderStatus ?? order.status ?? "Order received").replaceAll("_", " ")}</h2></div><span className="status-dot"/></div><p>Payment: <b>{String(order.paymentStatus ?? "under verification").replaceAll("_", " ")}</b></p>{items.length > 0 && <div className="track-list">{items.map((item, i) => <div key={i}><span>{String(item.productName ?? item.name ?? "Item")} × {String(item.quantity ?? 1)}</span><small>{String(item.batchName ?? "")}</small></div>)}</div>}{shipments.length > 0 && <div className="track-list shipment-list"><b>Shipments</b>{shipments.map((shipment, i) => <div key={i}><span>{String(shipment.label ?? shipment.kind ?? "Shipment").replaceAll("_", " ")}</span><small>{String(shipment.status ?? "processing").replaceAll("_", " ")}</small></div>)}</div>}{order.total != null && <div className="track-total"><span>Order total</span><b>₱{(Number(order.total) / 100).toLocaleString("en-PH")}</b></div>}</div>}</section><footer className="footer wrap"><Link href="/" className="brand"><span className="brand-mark small-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link><p>Made with care for your next favorite thing.</p><span className="copyright">© {new Date().getFullYear()} Tindahan ni Tinapa</span></footer></main>;
}
