;text-transform:capitalize}.shipment-list>b{font-size:10px}.track-total{display:flex;justify-content:space-between;border-top:1px solid var(--line);margin-top:10px;padding-top:13px;font-size:11px}.track-total b{font-size:14px}.track-page .footer{margin-top:auto}@keyframes slide-in{from{transform:translateX(18px);opacity:.7}to{transform:translateX(0);opacity:1}}@keyframes pop-in{from{transform:translateY(8px);opacity:0}to{transform:translateY(0);opacity:1}}

