export type GroupBuyItemInput = { productId: string; quantity: number };

export type CommerceProduct = {
  id: string;
  name: string;
  fullName: string;
  storefrontKey: string;
  kind: "standard" | "on_hand" | "group_buy";
  price: number;
  stock: number;
  isAvailable: boolean | null;
  batchId: number | null;
};

export type CommerceBatch = {
  id: number;
  status: string;
  deadline: string | Date;
};

type ShippingRates = Record<string, Record<string, number>>;

function isOrderable(batch: CommerceBatch | undefined, now: Date) {
  return Boolean(
    batch &&
      batch.status === "open" &&
      new Date(batch.deadline).getTime() > now.getTime()
  );
}

function getShippingRate(config: ShippingRates, region: string, quantity: number) {
  const normalized = region.trim().toLowerCase();
  if (!["luzon", "visayas", "mindanao", "other"].includes(normalized)) {
    throw new Error("Choose a valid shipping region.");
  }
  let rates = config[normalized];
  if (!rates) throw new Error("Shipping is unavailable for this region.");
  const fee = quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
  if (!Number.isSafeInteger(fee) || fee < 0) throw new Error("Shipping is unavailable for this region.");
  return fee;
}

const MAX_DB_INTEGER = 2_147_483_647;

export function prepareGroupBuyOrder(input: {
  items: Array<GroupBuyItemInput & { price?: number }>;
  shipmentPreference: "together" | "separate";
  region: string;
  shippingConfig: ShippingRates;
  products: Map<string, CommerceProduct>;
  batches: Map<number, CommerceBatch>;
  now?: Date;
}) {
  if (!input.items.length) throw new Error("Cart is empty.");
  if (!["luzon", "visayas", "mindanao", "other"].includes(input.region.trim().toLowerCase())) {
    throw new Error("Choose a valid shipping region.");
  }

  const quantities = new Map<string, number>();
  for (const item of input.items) {
    const quantity = Number(item.quantity);
    if (!item.productId || !Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
      throw new Error("Invalid cart item.");
    }
    const totalQuantity = (quantities.get(item.productId) ?? 0) + quantity;
    if (totalQuantity > 100) throw new Error("Maximum quantity per product is 100.");
    quantities.set(item.productId, totalQuantity);
  }

  const now = input.now ?? new Date();
  const orderItems = [...quantities].map(([productId, quantity]) => {
    const product = input.products.get(productId);
    if (
      !product ||
      product.storefrontKey !== "tindahan" ||
      product.kind === "standard" ||
      !product.isAvailable
    ) {
      throw new Error("A product is no longer available. Refresh the catalog and try again.");
    }
    if (product.kind === "on_hand" && product.stock < quantity) {
      throw new Error(`Not enough stock for ${product.name}.`);
    }
    if (product.kind === "group_buy" && !isOrderable(product.batchId ? input.batches.get(product.batchId) : undefined, now)) {
      throw new Error(`The group-buy batch for ${product.name} is closed.`);
    }
    if (!Number.isSafeInteger(product.price) || product.price < 0) throw new Error(`Invalid price for ${product.name}.`);
    const unitPrice = Math.round(product.price * 100);
    if (unitPrice > MAX_DB_INTEGER) throw new Error(`Price for ${product.name} is too high.`);
    const subtotal = unitPrice * quantity;
    if (subtotal > MAX_DB_INTEGER) throw new Error("Order total exceeds the supported payment limit.");
    return {
      productId: product.id,
      productName: product.fullName,
      productKind: product.kind,
      batchId: product.batchId,
      unitPrice,
      quantity,
      subtotal,
    };
  });

  const groups: Array<{ kind: "combined" | "on_hand" | "group_buy"; batchId: number | null; itemIndexes: number[]; quantity: number }> = [];
  if (input.shipmentPreference === "together") {
    groups.push({
      kind: "combined",
      batchId: null,
      itemIndexes: orderItems.map((_, index) => index),
      quantity: orderItems.reduce((sum, item) => sum + item.quantity, 0),
    });
  } else {
    const groupMap = new Map<string, (typeof groups)[number]>();
    orderItems.forEach((item, index) => {
      const kind = item.productKind === "on_hand" ? "on_hand" : "group_buy";
      const key = kind === "on_hand" ? "on_hand" : `batch:${item.batchId}`;
      const group = groupMap.get(key) ?? {
        kind,
        batchId: kind === "group_buy" ? item.batchId : null,
        itemIndexes: [],
        quantity: 0,
      };
      group.itemIndexes.push(index);
      group.quantity += item.quantity;
      groupMap.set(key, group);
    });
    groups.push(...groupMap.values());
  }

  const shipments = groups.map((group) => ({
    ...group,
    shippingFee: Math.round(getShippingRate(input.shippingConfig, input.region, group.quantity) * 100),
  }));
  const subtotal = orderItems.reduce((sum, item) => sum + item.subtotal, 0);
  const shippingFee = shipments.reduce((sum, shipment) => sum + shipment.shippingFee, 0);
  if (subtotal > MAX_DB_INTEGER || shippingFee > MAX_DB_INTEGER || subtotal + shippingFee > MAX_DB_INTEGER) {
    throw new Error("Order total exceeds the supported payment limit.");
  }
  return {
    items: orderItems.map((item, itemIndex) => ({
      ...item,
      shipmentIndex: shipments.findIndex((shipment) => shipment.itemIndexes.includes(itemIndex)),
    })),
    shipments,
    subtotal,
    shippingFee,
    total: subtotal + shippingFee,
  };
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/db";
import { categories, groupBuyBatches, products, orderShipments, orderEvents } from "@/lib/db/schema";
import { eq, desc, and } from "drizzle-orm";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) throw new Error("Unauthorized");
}

function slug(value: string) {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "item";
}

function refresh() {
  revalidatePath("/admin/group-buy");
  revalidatePath("/api/products");
}

export async function createTindahanCategory(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  if (!name || name.length > 60) throw new Error("Category name must be 1 to 60 characters.");
  const base = `tindahan-${slug(name)}`;
  const found = await db.query.categories.findFirst({ where: eq(categories.id, base) });
  const id = found ? `${base}-${Date.now().toString(36)}` : base;
  const last = await db.query.categories.findFirst({ orderBy: [desc(categories.sortOrder)] });
  await db.insert(categories).values({
    id,
    storefrontKey: "tindahan",
    name,
    icon: String(formData.get("icon") || "📦").slice(0, 8),
    pill: String(formData.get("pill") || "").slice(0, 30),
    sortOrder: (last?.sortOrder ?? 0) + 1,
    isActive: true,
  });
  refresh();
}

export async function saveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "").trim();
  const categoryId = String(formData.get("categoryId") || "").trim();
  const name = String(formData.get("name") || "").trim();
  const fullName = String(formData.get("fullName") || "").trim();
  const kind = String(formData.get("kind") || "");
  const price = Number(formData.get("price"));
  const compareAt = String(formData.get("compareAtPrice") || "").trim();
  const stock = Number(formData.get("stock"));
  const category = await db.query.categories.findFirst({ where: eq(categories.id, categoryId) });
  if (!category || category.storefrontKey !== "tindahan") throw new Error("Choose a Tindahan ni Tinapa category.");
  if (!name || name.length > 100 || !fullName || fullName.length > 160) throw new Error("Product names are required and must fit their limits.");
  if (kind !== "on_hand" && kind !== "group_buy") throw new Error("Choose on-hand or group-buy stock.");
  if (!Number.isSafeInteger(price) || price < 0 || price > 2_000_000) throw new Error("Enter a valid price in pesos.");
  if (!Number.isSafeInteger(stock) || stock < 0 || stock > 1_000_000) throw new Error("Enter a valid stock count.");
  const compareAtPrice = compareAt ? Number(compareAt) : null;
  if (compareAtPrice !== null && (!Number.isSafeInteger(compareAtPrice) || compareAtPrice < price)) throw new Error("Original price must be a whole number at or above the sale price.");
  const batchRaw = String(formData.get("batchId") || "");
  const batchId = kind === "group_buy" ? Number(batchRaw) : null;
  if (kind === "group_buy") {
    const batch = Number.isInteger(batchId) ? await db.query.groupBuyBatches.findFirst({ where: eq(groupBuyBatches.id, batchId!) }) : null;
    if (!batch) throw new Error("Choose a group-buy batch.");
  }

  if (id) {
    const existing = await db.query.products.findFirst({ where: eq(products.id, id) });
    if (!existing || existing.storefrontKey !== "tindahan") throw new Error("Tindahan product not found.");
    await db.update(products).set({
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl: String(formData.get("imageUrl") || "").trim().slice(0, 1000) || null,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: formData.get("isAvailable") === "on",
    }).where(eq(products.id, id));
  } else {
    const base = `tt_${slug(name).replace(/-/g, "_")}`;
    const found = await db.query.products.findFirst({ where: eq(products.id, base) });
    const productId = found ? `${base}_${Date.now().toString(36)}` : base;
    const last = await db.query.products.findFirst({ where: eq(products.categoryId, categoryId), orderBy: [desc(products.sortOrder)] });
    await db.insert(products).values({
      id: productId,
      storefrontKey: "tindahan",
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl: String(formData.get("imageUrl") || "").trim().slice(0, 1000) || null,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: true,
      sortOrder: (last?.sortOrder ?? 0) + 1,
    });
  }
  refresh();
}

export async function archiveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "");
  await db.update(products).set({ isAvailable: false }).where(and(eq(products.id, id), eq(products.storefrontKey, "tindahan")));
  refresh();
}

export async function createTindahanBatch(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!name || name.length > 100 || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Enter a batch name and valid deadline and ETA.");
  }
  await db.insert(groupBuyBatches).values({ name, deadline, eta, status: deadline.getTime() > Date.now() ? "open" : "closed" });
  refresh();
}

export async function updateTindahanBatch(formData: FormData) {
  await requireAdmin();
  const id = Number(formData.get("id"));
  const name = String(formData.get("name") || "").trim();
  const status = String(formData.get("status") || "");
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!Number.isInteger(id) || !name || name.length > 100 || !["open", "closed", "ordered", "arrived"].includes(status) || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Invalid batch update.");
  }
  await db.update(groupBuyBatches).set({ name, status: status as "open" | "closed" | "ordered" | "arrived", deadline, eta, updatedAt: new Date() }).where(eq(groupBuyBatches.id, id));
  refresh();
}

export async function updateTindahanShipment(formData: FormData) {
  await requireAdmin();
  const id = Number(formData.get("id"));
  const status = String(formData.get("status") || "");
  if (!Number.isInteger(id) || !["processing", "ready_to_ship", "shipped", "completed"].includes(status)) {
    throw new Error("Invalid shipment update.");
  }
  const shipment = await db.query.orderShipments.findFirst({
    where: eq(orderShipments.id, id),
    with: { order: true },
  });
  if (!shipment || shipment.order.storefrontKey !== "tindahan") throw new Error("Tindahan shipment not found.");
  await db.update(orderShipments).set({ status: status as "processing" | "ready_to_ship" | "shipped" | "completed", updatedAt: new Date() }).where(eq(orderShipments.id, id));
  await db.insert(orderEvents).values({
    orderId: shipment.orderId,
    eventType: `shipment_${status}`,
    description: `Shipment ${id} updated to ${status.replaceAll("_", " ")}.`,
  });
  revalidatePath("/admin/group-buy/orders");
  revalidatePath(`/admin/orders/${shipment.orderId}`);
}

