const repo = "AK-Lmn/admin-pbc";
const root = "C:\\Users\\ckzz2\\OneDrive\\Documents\\GitHub\\admin-pbc";
const files = [".gitignore","app/admin/analytics/page.tsx","app/admin/orders/[id]/page.tsx","app/admin/orders/page.tsx","app/admin/page.tsx","app/admin/products/page.tsx","app/admin/group-buy/orders/page.tsx","app/admin/group-buy/page.tsx","app/api/orders/route.ts","app/api/products/route.ts","app/api/group-buy/track/route.ts","app/order/[orderNumber]/page.tsx","components/navigation/bottom-nav.tsx","components/navigation/sidebar.tsx","lib/actions/admin-orders.ts","lib/actions/group-buy.ts","lib/actions/products.ts","lib/db/schema.ts","lib/group-buy/commerce.test.ts","lib/group-buy/commerce.ts","drizzle/0001_tindahan_group_buy.sql","drizzle/meta/_journal.json","package.json","package-lock.json"];
let reads = await Promise.all(files.map(path => tools.exec_command({
  cmd:`[Console]::Out.Write((Get-Content -Raw -LiteralPath '${root}\\${path.replaceAll("/","\\")}'))`,
  shell:"powershell",workdir:root,yield_time_ms:30000,max_output_tokens:path==="package-lock.json"?200000:30000
})));
reads = await Promise.all(reads.map((r,i)=>r.session_id?tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:30000,max_output_tokens:files[i]==="package-lock.json"?200000:30000}):r));
const bad = reads.map((r,i)=>({path:files[i],exit:r.exit_code,session:r.session_id,tokens:r.original_token_count})).filter(x=>x.exit!==0 || x.session || x.tokens===undefined);
if (bad.length) { text({bad}); exit(); }
const blobs = [];
for (let start=0; start<files.length; start+=5) {
  const batch = await Promise.all(files.slice(start,start+5).map((path,j)=>tools.mcp__codex_apps__github_create_blob({
    repository_full_name:repo,content:reads[start+j].output,encoding:"utf-8"
  })));
  blobs.push(...batch.map((result,index)=>({path:files[start+index],sha:result?.structuredContent?.sha,isError:result?.isError})));
}
store("admin_groupbuy_blobs",blobs);
text(JSON.stringify(blobs));

