import type { Metadata } from "next";
import { db } from "@/lib/db";
import { categories, products } from "@/lib/db/schema";
import { asc, eq } from "drizzle-orm";
import ProductCatalogManager from "@/components/products/product-catalog-manager";

export const metadata: Metadata = {
  title: "Product Catalog Management — SellerHub",
};

export const dynamic = "force-dynamic";

export default async function AdminProductsPage() {
  // Fetch active categories sorted by sortOrder
  const dbCategories = await db.query.categories.findMany({
    where: eq(categories.storefrontKey, "main"),
    orderBy: [asc(categories.sortOrder), asc(categories.createdAt)],
  });

  // Fetch all products sorted by sortOrder
  const dbProducts = await db.query.products.findMany({
    where: eq(products.storefrontKey, "main"),
    orderBy: [asc(products.sortOrder), asc(products.createdAt)],
  });

  return (
    <ProductCatalogManager
      categories={dbCategories}
      products={dbProducts}
    />
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { orders } from "@/lib/db/schema";
import { desc, eq } from "drizzle-orm";
import { formatDateTime, formatPrice } from "@/lib/utils";
import { OrderStatusBadge, PaymentStatusBadge } from "@/components/ui/status-badge";

export const metadata: Metadata = { title: "Group Buy Orders — SellerHub" };
export const dynamic = "force-dynamic";

