"use server";

import { db } from "@/lib/db";
import { orders, orderEvents } from "@/lib/db/schema";
import { eq, sql } from "drizzle-orm";
import { auth } from "@/auth";
import {
  confirmPaymentSchema,
  rejectPaymentSchema,
  updateOrderStatusSchema,
  addOrderNoteSchema,
} from "@/lib/validation/schemas";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) {
    throw new Error("Unauthorized");
  }
  return session;
}

const STATUS_LABELS: Record<string, string> = {
  pending_payment: "Pending Payment",
  payment_verification: "Payment Verification",
  paid: "Paid",
  processing: "Processing",
  ready_to_ship: "Ready to Ship",
  shipped: "Shipped",
  completed: "Completed",
  cancelled: "Cancelled",
};

// ============================================================
// CONFIRM PAYMENT
// ============================================================

export async function confirmPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = confirmPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId } = parsed.data;

  const order = await db.query.orders.findFirst({
    where: (o, { eq }) => eq(o.id, orderId),
  });

  if (!order) return { success: false, error: "Order not found." };

  if (order.storefrontKey === "tindahan") {
    try {
      await db.execute(sql`SELECT confirm_tindahan_payment(${orderId})`);
    } catch (error: any) {
      const message = String(error?.message || "");
      if (message.includes("ON_HAND_STOCK_INSUFFICIENT")) {
        return { success: false, error: "Payment not confirmed. On-hand stock is no longer sufficient." };
      }
      console.error("Tindahan payment confirmation failed:", error);
      return { success: false, error: "Payment could not be confirmed. Check the group-buy migration and try again." };
    }

    revalidatePath("/");
    revalidatePath("/admin");
    revalidatePath("/admin/orders");
    revalidatePath("/admin/group-buy");
    revalidatePath("/admin/group-buy/orders");
    revalidatePath(`/admin/orders/${orderId}`);
    return { success: true };
  }

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "paid",
      orderStatus: "processing",
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline events
  await db.insert(orderEvents).values([
    {
      orderId,
      eventType: "payment_confirmed",
      description: "Payment confirmed by seller.",
    },
    {
      orderId,
      eventType: "order_processing",
      description: "Order is now being processed.",
    },
  ]);

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// REJECT PAYMENT
// ============================================================

export async function rejectPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = rejectPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    reason: formData.get("reason") as string | undefined,
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId, reason } = parsed.data;

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "rejected",
      orderStatus: "pending_payment",
      rejectionReason: reason || null,
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline event
  await db.insert(orderEvents).values({
    orderId,
    eventType: "payment_rejected",
    description: reason
      ? `Payment rejected. Reason: ${reason}`
      : "Payment rejected by seller.",
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// UPDATE ORDER STATUS (Form & Direct)
// ============================================================

export async function updateOrderStatus(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const rawNotes = formData.get("notes");
  const notes =
    rawNotes && typeof rawNotes === "string" && rawNotes.trim() !== ""
      ? rawNotes.trim()
      : undefined;

  const parsed = updateOrderStatusSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    orderStatus: formData.get("orderStatus"),
    notes,
  });
  if (!parsed.success) {
    console.error("updateOrderStatus validation failure:", parsed.error.format());
    return { success: false, error: "Invalid status or parameters." };
  }

  const { orderId, orderStatus } = parsed.data;

  return quickChangeOrderStatus(orderId, orderStatus, notes);
}

export async function quickChangeOrderStatus(
  orderId: number,
  orderStatus: string,
  notes?: string
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const currentOrder = await db.query.orders.findFirst({ where: eq(orders.id, orderId) });
  if (!currentOrder) return { success: false, error: "Order not found." };
  if (
    currentOrder.storefrontKey === "tindahan" &&
    currentOrder.paymentStatus !== "paid" &&
    (orderStatus === "paid" || orderStatus === "processing")
  ) {
    return { success: false, error: "Verify the receipt before marking this order paid." };
  }

  const updateData: Record<string, any> = {
    orderStatus,
    updatedAt: new Date(),
  };

  if (notes !== undefined) {
    updateData.notes = notes;
  }

  if (orderStatus === "paid" || orderStatus === "processing") {
    updateData.paymentStatus = "paid";
  }

  await db.update(orders).set(updateData).where(eq(orders.id, orderId));

  await db.insert(orderEvents).values({
    orderId,
    eventType: `status_updated_${orderStatus}`,
    description: `Order status updated to: ${STATUS_LABELS[orderStatus] ?? orderStatus}.`,
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// ADD INTERNAL NOTE
// ============================================================

export async function addOrderNote(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = addOrderNoteSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    note: formData.get("note"),
  });
  if (!parsed.success) return { success: false, error: "Invalid note." };

  const { orderId, note } = parsed.data;

  await db
    .update(orders)
    .set({ notes: note, updatedAt: new Date() })
    .where(eq(orders.id, orderId));

  revalidatePath("/");
  revalidatePath(`/admin/orders/${orderId}`);
  return { success: true };
}

// ============================================================
// DELETE ORDER
// ============================================================

export async function deleteOrder(
  orderId: number
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const order = await db.query.orders.findFirst({
    where: eq(orders.id, orderId),
  });

  if (!order) {
    return { success: false, error: "Order not found." };
  }

  await db.delete(orders).where(eq(orders.id, orderId));

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");

  return { success: true };
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/db";
import { categories, groupBuyBatches, products, orderShipments, orderEvents } from "@/lib/db/schema";
import { eq, desc, and } from "drizzle-orm";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) throw new Error("Unauthorized");
}

function slug(value: string) {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "item";
}

function refresh() {
  revalidatePath("/admin/group-buy");
  revalidatePath("/api/products");
}

export async function createTindahanCategory(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  if (!name || name.length > 60) throw new Error("Category name must be 1 to 60 characters.");
  const base = `tindahan-${slug(name)}`;
  const found = await db.query.categories.findFirst({ where: eq(categories.id, base) });
  const id = found ? `${base}-${Date.now().toString(36)}` : base;
  const last = await db.query.categories.findFirst({ orderBy: [desc(categories.sortOrder)] });
  await db.insert(categories).values({
    id,
    storefrontKey: "tindahan",
    name,
    icon: String(formData.get("icon") || "📦").slice(0, 8),
    pill: String(formData.get("pill") || "").slice(0, 30),
    sortOrder: (last?.sortOrder ?? 0) + 1,
    isActive: true,
  });
  refresh();
}

export async function saveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "").trim();
  const categoryId = String(formData.get("categoryId") || "").trim();
  const name = String(formData.get("name") || "").trim();
  const fullName = String(formData.get("fullName") || "").trim();
  const kind = String(formData.get("kind") || "");
  const price = Number(formData.get("price"));
  const compareAt = String(formData.get("compareAtPrice") || "").trim();
  const stock = Number(formData.get("stock"));
  const category = await db.query.categories.findFirst({ where: eq(categories.id, categoryId) });
  if (!category || category.storefrontKey !== "tindahan") throw new Error("Choose a Tindahan ni Tinapa category.");
  if (!name || name.length > 100 || !fullName || fullName.length > 160) throw new Error("Product names are required and must fit their limits.");
  if (kind !== "on_hand" && kind !== "group_buy") throw new Error("Choose on-hand or group-buy stock.");
  if (!Number.isSafeInteger(price) || price < 0 || price > 2_000_000) throw new Error("Enter a valid price in pesos.");
  if (!Number.isSafeInteger(stock) || stock < 0 || stock > 1_000_000) throw new Error("Enter a valid stock count.");
  const compareAtPrice = compareAt ? Number(compareAt) : null;
  if (compareAtPrice !== null && (!Number.isSafeInteger(compareAtPrice) || compareAtPrice < price)) throw new Error("Original price must be a whole number at or above the sale price.");
  const batchRaw = String(formData.get("batchId") || "");
  const batchId = kind === "group_buy" ? Number(batchRaw) : null;
  if (kind === "group_buy") {
    const batch = Number.isInteger(batchId) ? await db.query.groupBuyBatches.findFirst({ where: eq(groupBuyBatches.id, batchId!) }) : null;
    if (!batch) throw new Error("Choose a group-buy batch.");
  }

  if (id) {
    const existing = await db.query.products.findFirst({ where: eq(products.id, id) });
    if (!existing || existing.storefrontKey !== "tindahan") throw new Error("Tindahan product not found.");
    await db.update(products).set({
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl: String(formData.get("imageUrl") || "").trim().slice(0, 1000) || null,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: formData.get("isAvailable") === "on",
    }).where(eq(products.id, id));
  } else {
    const base = `tt_${slug(name).replace(/-/g, "_")}`;
    const found = await db.query.products.findFirst({ where: eq(products.id, base) });
    const productId = found ? `${base}_${Date.now().toString(36)}` : base;
    const last = await db.query.products.findFirst({ where: eq(products.categoryId, categoryId), orderBy: [desc(products.sortOrder)] });
    await db.insert(products).values({
      id: productId,
      storefrontKey: "tindahan",
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl: String(formData.get("imageUrl") || "").trim().slice(0, 1000) || null,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: true,
      sortOrder: (last?.sortOrder ?? 0) + 1,
    });
  }
  refresh();
}

export async function archiveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "");
  await db.update(products).set({ isAvailable: false }).where(and(eq(products.id, id), eq(products.storefrontKey, "tindahan")));
  refresh();
}

export async function createTindahanBatch(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!name || name.length > 100 || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Enter a batch name and valid deadline and ETA.");
  }
  await db.insert(groupBuyBatches).values({ name, deadline, eta, status: deadline.getTime() > Date.now() ? "open" : "closed" });
  refresh();
}

export async function updateTindahanBatch(formData: FormData) {
  await requireAdmin();
  const id = Number(formData.get("id"));
  const name = String(formData.get("name") || "").trim();
  const status = String(formData.get("status") || "");
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!Number.isInteger(id) || !name || name.length > 100 || !["open", "closed", "ordered", "arrived"].includes(status) || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Invalid batch update.");
  }
  await db.update(groupBuyBatches).set({ name, status: status as "open" | "closed" | "ordered" | "arrived", deadline, eta, updatedAt: new Date() }).where(eq(groupBuyBatches.id, id));
  refresh();
}

export async function updateTindahanShipment(formData: FormData) {
  await requireAdmin();
  const id = Number(formData.get("id"));
  const status = String(formData.get("status") || "");
  if (!Number.isInteger(id) || !["processing", "ready_to_ship", "shipped", "completed"].includes(status)) {
    throw new Error("Invalid shipment update.");
  }
  const shipment = await db.query.orderShipments.findFirst({
    where: eq(orderShipments.id, id),
    with: { order: true },
  });
  if (!shipment || shipment.order.storefrontKey !== "tindahan") throw new Error("Tindahan shipment not found.");
  await db.update(orderShipments).set({ status: status as "processing" | "ready_to_ship" | "shipped" | "completed", updatedAt: new Date() }).where(eq(orderShipments.id, id));
  await db.insert(orderEvents).values({
    orderId: shipment.orderId,
    eventType: `shipment_${status}`,
    description: `Shipment ${id} updated to ${status.replaceAll("_", " ")}.`,
  });
  revalidatePath("/admin/group-buy/orders");
  revalidatePath(`/admin/orders/${shipment.orderId}`);
}

"use server";

import { db } from "@/lib/db";
import { categories, products } from "@/lib/db/schema";
import { eq, desc, and } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { auth } from "@/auth";

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/**
 * Creates a new category in the catalog
 */
export async function createCategoryAction(data: {
  name: string;
  icon: string;
  pill?: string;
}) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    if (!data.name || data.name.trim() === "") {
      return { success: false, error: "Category name is required" };
    }

    const baseSlug = slugify(data.name);
    let categoryId = baseSlug;

    // Check if category ID already exists
    const existing = await db.query.categories.findFirst({
      where: eq(categories.id, categoryId),
    });

    if (existing) {
      categoryId = `${baseSlug}-${Date.now().toString(36)}`;
    }

    // Get current max sortOrder
    const latestCat = await db.query.categories.findFirst({
      orderBy: [desc(categories.sortOrder)],
    });
    const sortOrder = (latestCat?.sortOrder ?? 0) + 1;

    await db.insert(categories).values({
      id: categoryId,
      name: data.name.trim(),
      icon: data.icon?.trim() || "💉",
      pill: data.pill?.trim() || "",
      sortOrder,
      isActive: true,
    });

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, categoryId };
  } catch (error: any) {
    console.error("createCategoryAction error:", error);
    return { success: false, error: error?.message || "Failed to create category" };
  }
}

/**
 * Creates a new product under a category
 */
export async function createProductAction(data: {
  categoryId: string;
  name: string;
  fullName: string;
  price: number;
  emoji?: string;
}) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    if (!data.name || !data.fullName || !data.categoryId) {
      return { success: false, error: "Name, full name, and category are required" };
    }

    const category = await db.query.categories.findFirst({ where: eq(categories.id, data.categoryId) });
    if (!category || category.storefrontKey !== "main") {
      return { success: false, error: "Choose a PBC catalog category." };
    }

    const baseSlug = slugify(data.name).replace(/-/g, "_");
    let productId = baseSlug;

    // Check if product ID exists
    const existing = await db.query.products.findFirst({
      where: eq(products.id, productId),
    });

    if (existing) {
      productId = `${baseSlug}_${Date.now().toString(36)}`;
    }

    // Get current max sort order for this category
    const latestProd = await db.query.products.findFirst({
      where: eq(products.categoryId, data.categoryId),
      orderBy: [desc(products.sortOrder)],
    });
    const sortOrder = (latestProd?.sortOrder ?? 0) + 1;

    await db.insert(products).values({
      id: productId,
      categoryId: data.categoryId,
      name: data.name.trim(),
      fullName: data.fullName.trim(),
      price: Math.round(data.price),
      emoji: data.emoji?.trim() || "💉",
      isAvailable: true,
      sortOrder,
    });

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, productId };
  } catch (error: any) {
    console.error("createProductAction error:", error);
    return { success: false, error: error?.message || "Failed to create product" };
  }
}

/**
 * Updates an existing product's details
 */
export async function updateProductAction(
  id: string,
  data: {
    categoryId: string;
    name: string;
    fullName: string;
    price: number;
    emoji?: string;
  }
) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    const [existing, category] = await Promise.all([
      db.query.products.findFirst({ where: eq(products.id, id) }),
      db.query.categories.findFirst({ where: eq(categories.id, data.categoryId) }),
    ]);
    if (existing?.storefrontKey !== "main" || category?.storefrontKey !== "main") {
      return { success: false, error: "Choose a PBC catalog product and category." };
    }

    await db
      .update(products)
      .set({
        categoryId: data.categoryId,
        name: data.name.trim(),
        fullName: data.fullName.trim(),
        price: Math.round(data.price),
        emoji: data.emoji?.trim() || "💉",
      })
      .where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true };
  } catch (error: any) {
    console.error("updateProductAction error:", error);
    return { success: false, error: error?.message || "Failed to update product" };
  }
}

/**
 * Deletes a product permanently
 */
export async function deleteProductAction(id: string) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    await db.delete(products).where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true };
  } catch (error: any) {
    console.error("deleteProductAction error:", error);
    return { success: false, error: error?.message || "Failed to delete product" };
  }
}

/**
 * Toggles product availability between in-stock and out-of-stock
 */
export async function toggleProductAvailability(
  id: string,
  currentStatus: boolean
) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    const newStatus = !currentStatus;

    await db
      .update(products)
      .set({ isAvailable: newStatus })
      .where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, isAvailable: newStatus };
  } catch (error: any) {
    console.error("toggleProductAvailability error:", error);
    return {
      success: false,
      error: error?.message || "Failed to toggle product availability",
    };
  }
}

import {
  pgTable,
  serial,
  text,
  integer,
  boolean,
  timestamp,
  pgEnum,
  index,
  unique,
  jsonb,
} from "drizzle-orm/pg-core";
import { relations } from "drizzle-orm";

// ============================================================
// ENUMS
// ============================================================

export const paymentStatusEnum = pgEnum("payment_status", [
  "pending",
  "under_verification",
  "paid",
  "rejected",
]);

export const orderStatusEnum = pgEnum("order_status", [
  "pending_payment",
  "payment_verification",
  "paid",
  "processing",
  "ready_to_ship",
  "shipped",
  "completed",
  "cancelled",
]);

export const userRoleEnum = pgEnum("user_role", ["admin", "staff"]);
export const storefrontKeyEnum = pgEnum("storefront_key", ["main", "tindahan"]);
export const productKindEnum = pgEnum("product_kind", ["standard", "on_hand", "group_buy"]);
export const groupBuyBatchStatusEnum = pgEnum("group_buy_batch_status", [
  "open",
  "closed",
  "ordered",
  "arrived",
]);
export const shipmentKindEnum = pgEnum("shipment_kind", ["combined", "on_hand", "group_buy"]);
export const shipmentStatusEnum = pgEnum("shipment_status", [
  "processing",
  "ready_to_ship",
  "shipped",
  "completed",
]);

// ============================================================
// CATEGORIES
// ============================================================

export const categories = pgTable(
  "categories",
  {
    id: text("id").primaryKey(), // slugified name, e.g. "tirzepatide-complete-set"
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    name: text("name").notNull(),
    icon: text("icon").default("💉"),
    pill: text("pill").default(""),
    sortOrder: integer("sort_order").default(0),
    isActive: boolean("is_active").default(true),
    createdAt: timestamp("created_at").defaultNow(),
  },
  (t) => [
    index("categories_sort_order_idx").on(t.sortOrder),
    index("categories_is_active_idx").on(t.isActive),
  ]
);

// ============================================================
// GROUP BUY BATCHES
// ============================================================

export const groupBuyBatches = pgTable(
  "group_buy_batches",
  {
    id: serial("id").primaryKey(),
    name: text("name").notNull(),
    status: groupBuyBatchStatusEnum("status").notNull().default("open"),
    deadline: timestamp("deadline", { withTimezone: true }).notNull(),
    eta: timestamp("eta", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("group_buy_batches_status_deadline_idx").on(t.status, t.deadline)]
);

// ============================================================
// PRODUCTS
// ============================================================

export const products = pgTable(
  "products",
  {
    id: text("id").primaryKey(), // e.g., "tir10_set"
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    kind: productKindEnum("kind").notNull().default("standard"),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    categoryId: text("category_id").references(() => categories.id, {
      onDelete: "cascade",
    }),
    name: text("name").notNull(),
    fullName: text("full_name").notNull(),
    price: integer("price").notNull(),
    compareAtPrice: integer("compare_at_price"),
    description: text("description"),
    imageUrl: text("image_url"),
    stock: integer("stock").notNull().default(0),
    emoji: text("emoji").default("💉"),
    isAvailable: boolean("is_available").default(true),
    sortOrder: integer("sort_order").default(0),
    createdAt: timestamp("created_at").defaultNow(),
  },
  (t) => [
    index("products_category_id_idx").on(t.categoryId),
    index("products_storefront_kind_idx").on(t.storefrontKey, t.kind),
    index("products_batch_id_idx").on(t.batchId),
    index("products_is_available_idx").on(t.isAvailable),
    index("products_sort_order_idx").on(t.sortOrder),
  ]
);

// ============================================================
// APP SETTINGS
// ============================================================

export const appSettings = pgTable("app_settings", {
  key: text("key").primaryKey(), // e.g., "shipping_config"
  value: jsonb("value").notNull(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// ============================================================
// SHIPPING METHODS (Legacy support)
// ============================================================

export const shippingMethods = pgTable("shipping_methods", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  fee: integer("fee").notNull(), // cents
  isActive: boolean("is_active").notNull().default(true),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// ============================================================
// ORDERS
// ============================================================

export const orders = pgTable(
  "orders",
  {
    id: serial("id").primaryKey(),
    orderNumber: text("order_number").notNull(),
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    shipmentPreference: text("shipment_preference"),
    // Customer info (snapshot at time of order)
    customerName: text("customer_name").notNull(),
    customerPhone: text("customer_phone").notNull(),
    customerEmail: text("customer_email"),
    // Delivery
    deliveryAddress: text("delivery_address").notNull(),
    city: text("city").notNull(),
    province: text("province").notNull(),
    postalCode: text("postal_code"),
    shippingMethod: text("shipping_method").notNull(),
    shippingFee: integer("shipping_fee").notNull().default(0), // cents
    // Payment
    paymentMethod: text("payment_method").notNull(),
    paymentProofFileId: text("payment_proof_file_id"), // Google Drive file ID
    paymentStatus: paymentStatusEnum("payment_status").notNull().default("pending"),
    // Order
    orderStatus: orderStatusEnum("order_status").notNull().default("pending_payment"),
    // Financials (all in cents)
    subtotal: integer("subtotal").notNull(),
    total: integer("total").notNull(),
    // Internal
    notes: text("notes"),
    rejectionReason: text("rejection_reason"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("orders_order_number_unique").on(t.orderNumber),
    index("orders_order_number_idx").on(t.orderNumber),
    index("orders_customer_phone_idx").on(t.customerPhone),
    index("orders_customer_name_idx").on(t.customerName),
    index("orders_payment_status_idx").on(t.paymentStatus),
    index("orders_order_status_idx").on(t.orderStatus),
    index("orders_created_at_idx").on(t.createdAt),
  ]
);

// ============================================================
// ORDER SHIPMENTS
// ============================================================

export const orderShipments = pgTable(
  "order_shipments",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id").notNull().references(() => orders.id, { onDelete: "cascade" }),
    kind: shipmentKindEnum("kind").notNull(),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    shippingFee: integer("shipping_fee").notNull().default(0),
    status: shipmentStatusEnum("status").notNull().default("processing"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("order_shipments_order_id_idx").on(t.orderId)]
);

// ============================================================
// ORDER ITEMS (price snapshot)
// ============================================================

export const orderItems = pgTable(
  "order_items",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    productId: text("product_id"),
    productKind: productKindEnum("product_kind").notNull().default("standard"),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    shipmentId: integer("shipment_id").references(() => orderShipments.id, { onDelete: "set null" }),
    // Price snapshot — historical prices preserved even if product changes
    productName: text("product_name").notNull(),
    unitPrice: integer("unit_price").notNull(), // cents
    quantity: integer("quantity").notNull(),
    subtotal: integer("subtotal").notNull(), // unit_price * quantity in cents
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("order_items_order_id_idx").on(t.orderId),
    index("order_items_product_id_idx").on(t.productId),
  ]
);

// ============================================================
// ORDER EVENTS (timeline)
// ============================================================

export const orderEvents = pgTable(
  "order_events",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    eventType: text("event_type").notNull(), // e.g. "order_submitted", "payment_confirmed"
    description: text("description"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("order_events_order_id_idx").on(t.orderId)]
);

// ============================================================
// USERS (admin/staff)
// ============================================================

export const users = pgTable(
  "users",
  {
    id: serial("id").primaryKey(),
    email: text("email").notNull(),
    passwordHash: text("password_hash").notNull(),
    name: text("name").notNull(),
    role: userRoleEnum("role").notNull().default("admin"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("users_email_unique").on(t.email),
    index("users_email_idx").on(t.email),
  ]
);

// ============================================================
// PUSH SUBSCRIPTIONS
// ============================================================

export const pushSubscriptions = pgTable(
  "push_subscriptions",
  {
    id: serial("id").primaryKey(),
    endpoint: text("endpoint").notNull(),
    p256dh: text("p256dh").notNull(),
    auth: text("auth").notNull(),
    userAgent: text("user_agent"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [unique("push_subscriptions_endpoint_key").on(t.endpoint)]
);

// ============================================================
// DRIZZLE RELATIONS
// ============================================================

export const categoriesRelations = relations(categories, ({ many }) => ({
  products: many(products),
}));

export const groupBuyBatchesRelations = relations(groupBuyBatches, ({ many }) => ({
  products: many(products),
  orderItems: many(orderItems),
  shipments: many(orderShipments),
}));

export const productsRelations = relations(products, ({ one }) => ({
  category: one(categories, {
    fields: [products.categoryId],
    references: [categories.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [products.batchId],
    references: [groupBuyBatches.id],
  }),
}));

export const ordersRelations = relations(orders, ({ many }) => ({
  orderItems: many(orderItems),
  orderEvents: many(orderEvents),
  shipments: many(orderShipments),
}));

export const orderShipmentsRelations = relations(orderShipments, ({ one, many }) => ({
  order: one(orders, {
    fields: [orderShipments.orderId],
    references: [orders.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [orderShipments.batchId],
    references: [groupBuyBatches.id],
  }),
  items: many(orderItems),
}));

export const orderItemsRelations = relations(orderItems, ({ one }) => ({
  order: one(orders, {
    fields: [orderItems.orderId],
    references: [orders.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [orderItems.batchId],
    references: [groupBuyBatches.id],
  }),
  shipment: one(orderShipments, {
    fields: [orderItems.shipmentId],
    references: [orderShipments.id],
