});
text(JSON.stringify(r));

const pr = await tools.mcp__codex_apps__github_create_pull_request({
  repository_full_name:"AK-Lmn/admin-pbc",
  head:"codex/group-buy-workflow",
  base:"main",
  title:"Add Tindahan ni Tinapa group-buy workflow",
  body:"## What changed
- Add an isolated Tindahan catalog, batch management, group-buy orders, and shipment status controls.
- Add server-priced order intake, area shipping calculation, Drive receipt upload, phone-verified tracking, and atomic on-hand stock reduction after payment confirmation.
- Keep PBC catalog, order dashboard, analytics, and existing public order tracking scoped to the main storefront.
- Upgrade Next.js to 16.4.3 and apply compatible production dependency fixes.

## Verification
- Admin `npx tsc --noEmit` passes.
- Group-buy commerce tests pass (4/4).
- Admin production build passes on Next.js 16.4.3.
- Production dependency audit reports 0 vulnerabilities.
- Additive migration applied successfully to the admin database.

The Tindahan site is deployed separately. Its catalog and ordering activate after this PR is merged and admin-pbc redeploys."
});
const url = pr?.structuredContent?.html_url || pr?.structuredContent?.url;
if (url) {
  const attached = await tools.mcp__codex_app__attach_artifact({artifact_type:"pull_request",url});
  text(JSON.stringify({pr,attached}));
} else text(JSON.stringify(pr));

