/* Match PBC's pink and lavender order-site theme. */
.notice-strip,.hero-art,.hero-counter,.hero-trust,.how-strip{display:none}
.topbar{background:rgba(255,255,255,.88);border-color:rgba(216,180,254,.45);box-shadow:0 4px 20px rgba(168,85,247,.08)}
.brand-mark{background:var(--gradient-accent);border-radius:50%;box-shadow:0 4px 14px rgba(217,70,239,.28);transform:none}
.brand strong{background:linear-gradient(135deg,#db2777 0%,#8b5cf6 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.brand small,.toplinks{color:var(--muted)}
.toplinks a:hover,.footer>a:last-of-type:hover{color:var(--coral)}
.cart-button{border-color:var(--line);background:var(--gradient-soft,linear-gradient(135deg,#fdf2f8,#f5f3ff));color:#6b21a8;box-shadow:var(--neu-shadow-card)}
.cart-button b{background:var(--gradient-accent)}
.hero{display:block;min-height:0;padding:58px 0 28px}
.hero-copy{max-width:720px;padding:0}
.eyebrow{color:var(--muted)}
.hero .eyebrow i{background:var(--coral)}
.hero h1,.section-heading h2,.product-info h3,.drawer-head h2,.cart-details b,.empty-bag>b,.success-card h2,.track-card h1,.tracking-top h2{font-family:'Playfair Display',Georgia,serif}
.hero h1{font-size:clamp(38px,5vw,56px);line-height:1.08;letter-spacing:-.04em;color:#3b0764;margin:12px 0}
.hero h1 em{color:var(--coral);font-style:normal}
.hero-copy>p{max-width:570px;color:var(--muted);margin-bottom:18px}
.button{border-radius:999px}
.primary{background:var(--gradient-accent);box-shadow:0 4px 14px rgba(217,70,239,.2)}
.primary:hover:not(:disabled){background:var(--gradient-accent-hover)}
.shop-section{padding:28px 0 80px}
.section-heading h2{color:#3b0764;font-size:clamp(30px,4vw,38px)}
.section-heading h2 span{color:var(--coral)}
.search{border-color:var(--line);border-radius:999px;background:#fff;box-shadow:var(--neu-shadow-inset)}
.search:focus-within{border-color:#c084fc;box-shadow:var(--neu-shadow-inset),0 0 0 3px rgba(192,132,252,.2)}
.search span{color:var(--coral)}
.search input{color:var(--ink)}
.catalog-controls{border-color:var(--line)}
.category{border-radius:999px;color:var(--muted)}
.category.active{background:#f5f3ff;color:#6b21a8;font-weight:700}
.category span{color:var(--muted)}
.product-card{background:#fff;border-color:var(--line);border-radius:16px;box-shadow:var(--neu-shadow-card)}
.product-card:hover{border-color:rgba(217,70,239,.45);box-shadow:0 8px 22px rgba(168,85,247,.14)}
.product-visual,.visual-0{background:#fdf2f8}
.visual-1{background:#f5f3ff}.visual-2{background:#fce7f3}.visual-3{background:#ede9fe}.visual-4{background:#f8f6fa}
.type-pill{border-radius:999px}
.stock-pill{background:#fdf2f8;color:#c026d3}
.group-pill{background:#f5f3ff;color:#6b21a8}
.sale-pill{background:var(--gradient-accent)}
.product-info h3{color:#3b0764}
.product-bottom{border-color:rgba(216,180,254,.3)}
.price{color:#db2777}
.add-button{border-color:rgba(216,180,254,.55);border-radius:999px;color:#6b21a8;background:#fff}
.add-button:hover:not(:disabled){background:#f5f3ff}
.state-card{border-color:var(--line);border-radius:14px;background:rgba(255,255,255,.72);color:var(--muted)}
.error-card b{color:var(--ink)}
.text-button{color:#6b21a8}
.footer{border-color:var(--line)}
.footer>p,.copyright,.footer>a:last-of-type{color:var(--muted)}
.overlay{background:rgba(44,30,61,.38)}
.drawer,.checkout-modal,.success-card,.track-card{background:#fff;border-color:var(--line);box-shadow:0 18px 45px rgba(44,30,61,.12)}
.drawer-head{border-color:var(--line)}
.drawer-head h2,.empty-bag>b,.success-card h2,.track-card h1,.tracking-top h2{color:#3b0764}
.close-button{border-color:var(--line);background:#fff;border-radius:50%}
.cart-line,.drawer-foot,.tracking-result,.track-list{border-color:var(--line)}
.cart-thumb{background:#f5f3ff;color:#6b21a8}
.quantity-control,.shipment-choice{border-color:var(--line);border-radius:12px}
.quantity-control button{color:#6b21a8}
.field{border-color:var(--line);background:#fff;border-radius:10px;color:var(--ink)}
.field:focus{border-color:#c084fc;box-shadow:0 0 0 3px rgba(192,132,252,.2)}
.shipment-choice input{accent-color:#8b5cf6}
.payment-note{background:#f5f3ff;color:#6b21a8;border-radius:12px}
.payment-note>span,.upload-icon,.empty-bag>span,.success-heart{color:var(--coral)}
.upload-box{border-color:rgba(192,132,252,.6);background:#fdf8fc;border-radius:12px}
