.form-error{color:#9f1239;background:#fdf2f8;border-radius:10px}
.success-heart{background:#fdf2f8;border-radius:50%}
.status-dot{background:#c084fc;box-shadow:0 0 0 5px #f5f3ff}
.track-card{border-radius:20px}
.track-card h1 span{color:var(--coral)}
.track-page .back-link{color:var(--muted)}
@media(max-width:680px){.hero{padding:38px 0 20px}.hero h1{font-size:40px}.shop-section{padding:22px 0 60px}}

"use client";

import { ChangeEvent, FormEvent, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { calculateOrderTotal, calculateShippingRate, isBatchOrderable } from "../src/commerce.mjs";

type Batch = { id: number; name: string; status: string; deadline: string; eta?: string | null };
type Product = {
  id: string; categoryId: string; name: string; fullName: string; price: number;
  compareAtPrice?: number | null; description?: string | null; imageUrl?: string | null;
  emoji?: string | null; stock: number; kind: "on_hand" | "group_buy" | "standard";
  batchId?: number | null; batch?: Batch | null;
};
type Catalog = {
  categories: Array<{ id: string; name: string; icon?: string | null; pill?: string | null }>;
  products: Product[];
  batches: Batch[];
  shippingConfig: Record<string, Record<string, number>>;
};
type CartLine = { product: Product; quantity: number };

const API = (process.env.NEXT_PUBLIC_ADMIN_API_URL || "https://admin-pbc.vercel.app").replace(/\/$/, "");
const money = (value: number) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(value);
const date = (value?: string | null) => value ? new Intl.DateTimeFormat("en-PH", { dateStyle: "medium" }).format(new Date(value)) : "To be announced";

export default function HomePage() {
  const [catalog, setCatalog] = useState<Catalog | null>(null);
  const [loadError, setLoadError] = useState("");
  const [category, setCategory] = useState("all");
  const [query, setQuery] = useState("");
  const [cart, setCart] = useState<Record<string, CartLine>>({});
  const [cartOpen, setCartOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [checkoutError, setCheckoutError] = useState("");
  const [successOrder, setSuccessOrder] = useState("");
  const [region, setRegion] = useState("luzon");
  const [shipmentPreference, setShipmentPreference] = useState<"together" | "separate">("separate");
  const [proof, setProof] = useState<{ data: string; name: string } | null>(null);
  const lines = Object.values(cart);

  useEffect(() => {
    let alive = true;
    fetch(`${API}/api/products?storefront=tindahan`, { cache: "no-store" })
      .then(async (response) => {
        if (!response.ok) throw new Error("Catalog could not load. Please try again later.");
        const data = await response.json();
        if (!data || !Array.isArray(data.products) || !Array.isArray(data.categories) || !data.shippingConfig) {
          throw new Error("Group-buy ordering is not live yet. Please check back soon.");
        }
        return data;
      })
      .then((data: Catalog) => { if (alive) setCatalog(data); })
      .catch((error: Error) => { if (alive) setLoadError(error.message); });
    return () => { alive = false; };
  }, []);

  const visibleProducts = useMemo(() => (catalog?.products ?? []).filter((product) =>
    (category === "all" || product.categoryId === category) &&
    `${product.name} ${product.fullName} ${product.description ?? ""}`.toLowerCase().includes(query.toLowerCase().trim())
  ), [catalog, category, query]);
  const total = useMemo(() => calculateOrderTotal(
    lines.map(({ product, quantity }) => ({ productId: product.id, kind: product.kind, batchId: product.batchId, quantity, price: product.price })),
    shipmentPreference,
    (quantity: number) => calculateShippingRate(catalog?.shippingConfig, region, quantity),
  ), [catalog, lines, region, shipmentPreference]);

  function add(product: Product) {
    setCart((current) => {
      const quantity = (current[product.id]?.quantity ?? 0) + 1;
      if (quantity > 100) return current;
      if (product.kind === "on_hand" && quantity > product.stock) return current;
      return { ...current, [product.id]: { product, quantity } };
    });
  }
  function changeQuantity(product: Product, quantity: number) {
    setCart((current) => {
      if (quantity < 1) { const next = { ...current }; delete next[product.id]; return next; }
      if (quantity > 100) return current;
      if (product.kind === "on_hand" && quantity > product.stock) return current;
      return { ...current, [product.id]: { product, quantity } };
    });
  }
  async function onProofChange(event: ChangeEvent<HTMLInputElement>) {
    setCheckoutError("");
    const file = event.target.files?.[0];
    if (!file) { setProof(null); return; }
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 3 * 1024 * 1024) {
      setCheckoutError("Choose an image under 3 MB."); event.target.value = ""; setProof(null); return;
    }
    const data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Could not read receipt.")); reader.readAsDataURL(file);
    });
    setProof({ data, name: file.name });
  }
  async function placeOrder(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setCheckoutError("");
    if (!proof) { setCheckoutError("Upload your payment receipt to submit your order."); return; }
    const form = new FormData(event.currentTarget);
    setSubmitting(true);
    try {
      const response = await fetch(`${API}/api/orders`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          storefrontKey: "tindahan",
          items: lines.map(({ product, quantity }) => ({ productId: product.id, quantity })),
          customerName: form.get("customerName"), customerPhone: form.get("customerPhone"), customerEmail: form.get("customerEmail"),
          deliveryAddress: form.get("deliveryAddress"), city: form.get("city"), province: form.get("province"), postalCode: form.get("postalCode"),
          region, shipmentPreference, paymentMethod: form.get("paymentMethod"), imageData: proof.data, imageName: proof.name,
        }),
      });
      const result = await response.json();
      if (!response.ok || !result.success) throw new Error(result.error || "Order could not be placed.");
      setSuccessOrder(result.orderNumber); setCart({}); setProof(null); setCheckoutOpen(false); setCartOpen(false);
    } catch (error) { setCheckoutError(error instanceof Error ? error.message : "Order could not be placed."); }
    finally { setSubmitting(false); }
  }

  const cartCount = lines.reduce((sum, line) => sum + line.quantity, 0);

  return <main>
    <header className="topbar wrap">
      <Link href="/" className="brand" aria-label="Tindahan ni Tinapa home"><span className="brand-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link>
      <nav className="toplinks"><a href="#shop">Shop</a><Link href="/track-order">Track order</Link></nav>
      <button className="cart-button" onClick={() => setCartOpen(true)} aria-label={`Open bag, ${cartCount} items`}>Your bag <b>{cartCount}</b></button>
    </header>

    <section className="hero wrap">
      <div className="hero-copy"><span className="eyebrow"><i /> A LITTLE BIT OF EVERYTHING</span><h1>Budol finds.<br/><em>Better together.</em></h1><p>Shop ready-to-go favorites or join a group buy for something special. We’ll keep every batch and update in one cozy place.</p><a className="button primary" href="#shop">Find your next budol <span>↘</span></a></div>
    </section>


    <section className="shop-section wrap" id="shop">
      <div className="section-heading"><div><span className="eyebrow">THE TINAPA FINDS</span><h2>Shop the good stuff<span>.</span></h2></div><label className="search"><span>⌕</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search finds..." aria-label="Search products"/></label></div>
      <div className="catalog-controls"><div className="category-list"><button className={category === "all" ? "category active" : "category"} onClick={() => setCategory("all")}>Everything <span>{catalog?.products.length ?? 0}</span></button>{catalog?.categories.map((item) => <button key={item.id} className={category === item.id ? "category active" : "category"} onClick={() => setCategory(item.id)}>{item.icon} {item.name}</button>)}</div><span className="catalog-count">{visibleProducts.length} lovely {visibleProducts.length === 1 ? "find" : "finds"}</span></div>
      {loadError && <div className="state-card error-card"><b>Catalog is taking a little break.</b><span>{loadError}</span><button className="text-button" onClick={() => location.reload()}>Try again</button></div>}
      {!catalog && !loadError && <div className="state-card">Gathering the good stuff…</div>}
      {catalog && visibleProducts.length === 0 && <div className="state-card">No finds here yet. Try another category.</div>}
      {catalog && visibleProducts.length > 0 && <div className="product-grid">{visibleProducts.map((product, index) => {
        const orderable = product.kind !== "group_buy" || isBatchOrderable(product.batch ?? { status: "closed", deadline: "" });
        const canAdd = product.kind === "on_hand" ? product.stock > (cart[product.id]?.quantity ?? 0) : orderable;
        return <article className="product-card" key={product.id}>
          <div className={`product-visual visual-${index % 5}`}>{product.imageUrl ? <img src={product.imageUrl} alt={product.fullName} loading="lazy"/> : <span className="product-emoji">{product.emoji || (product.kind === "group_buy" ? "🎁" : "🛍️")}</span>}<span className={product.kind === "group_buy" ? "type-pill group-pill" : "type-pill stock-pill"}>{product.kind === "group_buy" ? `GROUP BUY · ${(product.batch?.status || (orderable ? "open" : "closed")).replaceAll("_", " ").toUpperCase()}` : "ON HAND"}</span>{product.compareAtPrice && product.compareAtPrice > product.price ? <span className="sale-pill">A little less</span> : null}</div>
          <div className="product-info"><div className="product-kicker">{product.kind === "group_buy" ? product.batch?.name ?? "New group buy" : product.stock > 0 ? `${product.stock} ready to go` : "Sold out"}</div><h3>{product.fullName || product.name}</h3>{product.description && <p>{product.description}</p>}
            {product.kind === "group_buy" && product.batch && <div className="batch-meta"><span>Order by <b>{date(product.batch.deadline)}</b></span>{product.batch.eta && <span>Est. arrival <b>{date(product.batch.eta)}</b></span>}</div>}
            <div className="product-bottom"><div><b className="price">{money(product.price)}</b>{product.compareAtPrice && product.compareAtPrice > product.price && <del>{money(product.compareAtPrice)}</del>}</div><button className="add-button" onClick={() => add(product)} disabled={!canAdd} aria-label={`Add ${product.fullName} to bag`}>{canAdd ? "Add to bag +" : product.kind === "group_buy" ? "Batch closed" : "Sold out"}</button></div>
          </div>
        </article>;
      })}</div>}
    </section>

    <footer className="footer wrap"><Link href="/" className="brand"><span className="brand-mark small-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link><p>Made with care for your next favorite thing.</p><Link href="/track-order">Track an order ↗</Link><span className="copyright">© {new Date().getFullYear()} Tindahan ni Tinapa</span></footer>

    {cartOpen && <div className="overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) setCartOpen(false); }}><aside className="drawer" aria-label="Your shopping bag"><div className="drawer-head"><div><span className="eyebrow">YOUR GOOD FINDS</span><h2>Your bag <span>({cartCount})</span></h2></div><button className="close-button" onClick={() => setCartOpen(false)} aria-label="Close bag">×</button></div>{lines.length === 0 ? <div className="empty-bag"><span>♡</span><b>Your bag is waiting.</b><p>Pick something lovely to get started.</p><button className="button primary" onClick={() => setCartOpen(false)}>Browse finds</button></div> : <>
      <div className="drawer-lines">{lines.map(({ product, quantity }) => <div className="cart-line" key={product.id}><div className="cart-thumb">{product.imageUrl ? <img src={product.imageUrl} alt=""/> : product.emoji || "🛍️"}</div><div className="cart-details"><b>{product.fullName}</b><small>{product.kind === "group_buy" ? product.batch?.name ?? "Group buy" : "On hand"}</small><span>{money(product.price)}</span></div><div className="quantity-control"><button onClick={() => changeQuantity(product, quantity - 1)} aria-label="Decrease quantity">−</button><span>{quantity}</span><button onClick={() => changeQuantity(product, quantity + 1)} disabled={product.kind === "on_hand" && quantity >= product.stock || quantity >= 100} aria-label="Increase quantity">+</button></div></div>)}</div>
      <div className="drawer-foot"><label className="field-label">Where are we sending this?</label><select className="field" value={region} onChange={(e) => setRegion(e.target.value)}><option value="luzon">Luzon</option><option value="visayas">Visayas</option><option value="mindanao">Mindanao</option><option value="other">Other area</option></select><label className="shipment-choice"><input type="radio" name="shipping" checked={shipmentPreference === "separate"} onChange={() => setShipmentPreference("separate")}/><span><b>Ship separately</b><small>On-hand items + each group-buy batch</small></span></label><label className="shipment-choice"><input type="radio" name="shipping" checked={shipmentPreference === "together"} onChange={() => setShipmentPreference("together")}/><span><b>Ship together</b><small>One shipment when every item is ready</small></span></label><div className="total-line"><span>Items</span><b>{money(total.subtotal)}</b></div>{total.shipments.map((shipment, index) => <div className="total-line muted" key={`${shipment.kind}-${shipment.batchId}-${index}`}><span>Shipping · {shipment.kind === "combined" ? "one parcel" : shipment.kind === "on_hand" ? "on-hand" : catalog?.batches.find((batch) => String(batch.id) === String(shipment.batchId))?.name || "group buy"}</span><b>{money(shipment.shipping)}</b></div>)}<div className="total-line grand-total"><span>Total to pay</span><b>{money(total.total)}</b></div><button className="button primary checkout-button" onClick={() => { setCartOpen(false); setCheckoutOpen(true); }}>Continue to checkout <span>→</span></button><p className="total-note">Your total is calculated from the current catalog and shipping area.</p></div>
    </>}</aside></div>}

    {checkoutOpen && <div className="overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) setCheckoutOpen(false); }}><section className="checkout-modal"><div className="drawer-head"><div><span className="eyebrow">ALMOST YOURS</span><h2>Checkout</h2></div><button className="close-button" onClick={() => setCheckoutOpen(false)} aria-label="Close checkout">×</button></div><form onSubmit={placeOrder} className="checkout-form"><div className="form-grid"><label>Your name<input className="field" name="customerName" required autoComplete="name"/></label><label>Mobile number<input className="field" name="customerPhone" required autoComplete="tel" inputMode="tel"/></label><label className="full-field">Email (optional)<input className="field" name="customerEmail" type="email" autoComplete="email"/></label><label className="full-field">Street address<input className="field" name="deliveryAddress" required autoComplete="street-address"/></label><label>City / town<input className="field" name="city" required autoComplete="address-level2"/></label><label>Province<input className="field" name="province" required autoComplete="address-level1"/></label><label>Postal code<input className="field" name="postalCode" autoComplete="postal-code" inputMode="numeric"/></label><label>Payment method<select className="field" name="paymentMethod"><option>GCash</option><option>Maya</option><option>Bank transfer</option></select></label></div><div className="payment-note"><span>♡</span><p>Send payment using the details shared by the seller. Upload your receipt below so Tin can verify it.</p></div><label className="upload-box"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={onProofChange}/><span className="upload-icon">↑</span><b>{proof ? proof.name : "Upload payment receipt"}</b><small>JPG, PNG or WebP · up to 3 MB</small></label><div className="checkout-summary"><span>Full total ({total.shipments.length} {total.shipments.length === 1 ? "shipment" : "shipments"})</span><b>{money(total.total)}</b></div>{checkoutError && <p className="form-error" role="alert">{checkoutError}</p>}<button className="button primary checkout-button" type="submit" disabled={submitting}>{submitting ? "Sending order…" : "Place order · " + money(total.total)}</button><p className="secure-note">Your order, price, stock and shipping are checked again before it’s saved.</p></form></section></div>}

    {successOrder && <div className="overlay success-overlay"><section className="success-card"><span className="success-heart">♡</span><span className="eyebrow">ORDER SENT</span><h2>You’re on the list!</h2><p>Your order number is <b>{successOrder}</b>. Keep it handy while Tin checks your receipt.</p><Link className="button primary" href={`/track-order?order=${encodeURIComponent(successOrder)}`}>Track your order →</Link><button className="text-button" onClick={() => setSuccessOrder("")}>Back to shopping</button></section></div>}
  </main>;
}

