@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap');

:root{--ink:#2c1e3d;--muted:#725d88;--paper:#f8f6fa;--paper-deep:#fdf8fc;--green:#8b5cf6;--green-deep:#6b21a8;--coral:#ec4899;--yellow:#c084fc;--line:rgba(216,180,254,.4);--white:#fff;--shadow:0 8px 24px rgba(168,85,247,.12);--gradient-accent:linear-gradient(135deg,#ec4899 0%,#c084fc 50%,#8b5cf6 100%);--gradient-accent-hover:linear-gradient(135deg,#db2777 0%,#a855f7 50%,#7c3aed 100%);--neu-shadow-card:-4px -4px 10px rgba(255,255,255,.95),4px 4px 12px rgba(175,150,195,.18);--neu-shadow-inset:inset 0 1px 3px rgba(59,7,100,.08);font-family:'DM Sans',sans-serif;color:var(--ink);background:var(--paper);font-synthesis:none;text-rendering:optimizeLegibility}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 10% 6%,rgba(244,114,182,.12),transparent 36rem),radial-gradient(circle at 90% 85%,rgba(192,132,252,.14),transparent 40rem),linear-gradient(150deg,#fbf9fc 0%,#f7f3f9 45%,#f4eff8 100%);color:var(--ink)}button,input,select{font:inherit}button,a{ -webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button{color:inherit}.wrap{width:min(1180px,calc(100% - 64px));margin:0 auto}.notice-strip{height:31px;background:var(--green);color:#f5e8c9;display:flex;justify-content:center;align-items:center;gap:42px;font-size:9px;letter-spacing:.17em;font-weight:700}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px}.brand-mark{display:grid;place-items:center;background:var(--coral);color:white;width:40px;height:40px;border-radius:14px 14px 14px 4px;font-family:Fraunces,serif;font-size:19px;font-weight:600;transform:rotate(-4deg)}.brand strong,.brand small{display:block}.brand strong{font-size:14px;letter-spacing:-.03em}.brand small{font-size:9px;color:var(--muted);margin-top:3px;letter-spacing:.04em}.toplinks{display:flex;gap:34px;font-size:12px;color:#66756e}.toplinks a:hover,.footer>a:last-of-type:hover{color:var(--coral)}.cart-button{border:1px solid var(--line);background:transparent;padding:10px 14px;border-radius:999px;font-size:11px;font-weight:700;cursor:pointer}.cart-button b{display:inline-grid;place-items:center;background:var(--coral);color:white;width:19px;height:19px;margin-left:8px;border-radius:50%;font-size:10px}.hero{min-height:496px;display:grid;grid-template-columns:1fr 1fr;align-items:center;position:relative;padding-top:10px}.hero-copy{padding:32px 0 44px;max-width:490px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:.18em;color:#87938a;display:inline-flex;align-items:center;gap:8px}.hero .eyebrow i{width:7px;height:7px;border-radius:50%;background:var(--coral);display:inline-block}.hero h1{font-family:Fraunces,serif;font-weight:500;font-size:clamp(52px,6.2vw,78px);line-height:.99;letter-spacing:-.06em;margin:23px 0 19px}.hero h1 em{font-weight:500;font-style:italic;color:var(--coral)}.hero-copy>p{font-size:14px;line-height:1.8;color:var(--muted);max-width:395px;margin:0 0 26px}.button{border:0;display:inline-flex;align-items:center;justify-content:center;gap:15px;cursor:pointer;font-weight:700;transition:transform .18s,background .18s}.button:hover:not(:disabled){transform:translateY(-2px)}.button:disabled{opacity:.6;cursor:wait}.primary{background:var(--green);color:white;padding:14px 19px;border-radius:7px;font-size:12px}.primary:hover:not(:disabled){background:var(--green-deep)}.primary span{font-size:17px;line-height:.7}.hero-trust{display:flex;gap:18px;margin-top:28px;font-size:9px;color:#87938a}.hero-art{height:364px;position:relative;display:grid;place-items:center}.sun-shape{position:absolute;width:280px;height:280px;border-radius:50%;background:#fae8b7;right:18%;top:8%;opacity:.72}.bag-art{width:180px;height:210px;position:relative;z-index:2;transform:rotate(5deg);filter:drop-shadow(0 25px 15px rgba(59,76,63,.12))}.bag-handle{width:86px;height:58px;border:11px solid var(--green);border-bottom:0;border-radius:50px 50px 0 0;position:absolute;top:0;left:47px}.bag-face{position:absolute;left:0;right:0;top:42px;bottom:0;border-radius:19px 19px 35px 35px;background:var(--coral);display:flex;align-items:center;justify-content:center;color:#fff9eb;font-family:Fraunces,serif;font-size:26px;line-height:.9;text-align:center;box-shadow:inset 0 -15px rgba(142,67,55,.08)}.bag-face b{position:absolute;bottom:17px;right:20px;font-family:'DM Sans',sans-serif;font-size:13px;color:#f7cf88}.bag-leaf{position:absolute;width:25px;height:45px;background:#79967a;border-radius:80% 0 80% 0;top:27px;z-index:-1}.leaf-a{left:40px;transform:rotate(-30deg)}.leaf-b{right:39px;transform:rotate(30deg) sc