CREATE OR REPLACE FUNCTION confirm_tindahan_payment(p_order_id integer)
RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  v_storefront storefront_key;
  v_payment_status payment_status;
BEGIN
  SELECT storefront_key, payment_status INTO v_storefront, v_payment_status
  FROM orders WHERE id = p_order_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
  IF v_storefront <> 'tindahan' THEN RAISE EXCEPTION 'NOT_TINDAHAN_ORDER'; END IF;
  IF v_payment_status = 'paid' THEN RETURN 'already_paid'; END IF;
  IF v_payment_status <> 'under_verification' THEN RAISE EXCEPTION 'PAYMENT_NOT_UNDER_VERIFICATION'; END IF;

  PERFORM p.id
  FROM products p
  JOIN (
    SELECT product_id, sum(quantity)::integer AS quantity
    FROM order_items
    WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
    GROUP BY product_id
  ) requested ON requested.product_id = p.id
  ORDER BY p.id
  FOR UPDATE OF p;

  IF EXISTS (
    SELECT 1
    FROM products p
    JOIN (
      SELECT product_id, sum(quantity)::integer AS quantity
      FROM order_items
      WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
      GROUP BY product_id
    ) requested ON requested.product_id = p.id
    WHERE p.stock < requested.quantity
  ) THEN RAISE EXCEPTION 'ON_HAND_STOCK_INSUFFICIENT'; END IF;

  UPDATE products p
  SET stock = p.stock - requested.quantity
  FROM (
    SELECT product_id, sum(quantity)::integer AS quantity
    FROM order_items
    WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
    GROUP BY product_id
  ) requested
  WHERE requested.product_id = p.id;

  UPDATE orders
  SET payment_status = 'paid', order_status = 'processing', updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO order_events(order_id, event_type, description) VALUES
    (p_order_id, 'payment_confirmed', 'Payment confirmed by seller.'),
    (p_order_id, 'order_processing', 'Order is now being processed.');

  RETURN 'confirmed';
END;
$$;

"use client";

import { ChangeEvent, FormEvent, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { calculateOrderTotal, calculateShippingRate, isBatchOrderable } from "../src/commerce.mjs";

type Batch = { id: number; name: string; status: string; deadline: string; eta?: string | null };
type Product = {
  id: string; categoryId: string; name: string; fullName: string; price: number;
  compareAtPrice?: number | null; description?: string | null; imageUrl?: string | null;
  emoji?: string | null; stock: number; kind: "on_hand" | "group_buy" | "standard";
  batchId?: number | null; batch?: Batch | null;
};
type Catalog = {
  categories: Array<{ id: string; name: string; icon?: string | null; pill?: string | null }>;
  products: Product[];
  batches: Batch[];
  shippingConfig: Record<string, Record<string, number>>;
};
type CartLine = { product: Product; quantity: number };

const API = (process.env.NEXT_PUBLIC_ADMIN_API_URL || "https://admin-pbc.vercel.app").replace(/\/$/, "");
const money = (value: number) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(value);
const date = (value?: string | null) => value ? new Intl.DateTimeFormat("en-PH", { dateStyle: "medium" }).format(new Date(value)) : "To be announced";

export default function HomePage() {
  const [catalog, setCatalog] = useState<Catalog | null>(null);
  const [loadError, setLoadError] = useState("");
  const [category, setCategory] = useState("all");
  const [query, setQuery] = useState("");
  const [cart, setCart] = useState<Record<string, CartLine>>({});
  const [cartOpen, setCartOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [checkoutError, setCheckoutError] = useState("");
  const [successOrder, setSuccessOrder] = useState("");
  const [region, setRegion] = useState("luzon");
  const [shipmentPreference, setShipmentPreference] = useState<"together" | "separate">("separate");
  const [proof, setProof] = useState<{ data: string; name: string } | null>(null);
  const lines = Object.values(cart);

  useEffect(() => {
    let alive = true;
    fetch(`${API}/api/products?storefront=tindahan`, { cache: "no-store" })
      .then(async (response) => {
        if (!response.ok) throw new Error("Catalog could not load. Please try again later.");
        const data = await response.json();
        if (!data || !Array.isArray(data.products) || !Array.isArray(data.categories) || !data.shippingConfig) {
          throw new Error("Group-buy ordering is not live yet. Please check back soon.");
        }
        return data;
      })
      .then((data: Catalog) => { if (alive) setCatalog(data); })
      .catch((error: Error) => { if (alive) setLoadError(error.message); });
    return () => { alive = false; };
  }, []);

  const visibleProducts = useMemo(() => (catalog?.products ?? []).filter((product) =>
    (category === "all" || product.categoryId === category) &&
    `${product.name} ${product.fullName} ${product.description ?? ""}`.toLowerCase().includes(query.toLowerCase().trim())
  ), [catalog, category, query]);
  const total = useMemo(() => calculateOrderTotal(
    lines.map(({ product, quantity }) => ({ productId: product.id, kind: product.kind, batchId: product.batchId, quantity, price: product.price })),
    shipmentPreference,
    (quantity: number) => calculateShippingRate(catalog?.shippingConfig, region, quantity),
  ), [catalog, lines, region, shipmentPreference]);

  function add(product: Product) {
    setCart((current) => {
      const quantity = (current[product.id]?.quantity ?? 0) + 1;
      if (quantity > 100) return current;
      if (product.kind === "on_hand" && quantity > product.stock) return current;
      return { ...current, [product.id]: { product, quantity } };
    });
  }
  function changeQuantity(product: Product, quantity: number) {
    setCart((current) => {
      if (quantity < 1) { const next = { ...current }; delete next[product.id]; return next; }
      if (quantity > 100) return current;
      if (product.kind === "on_hand" && quantity > product.stock) return current;
      return { ...current, [product.id]: { product, quantity } };
    });
  }
  async function onProofChange(event: ChangeEvent<HTMLInputElement>) {
    setCheckoutError("");
    const file = event.target.files?.[0];
    if (!file) { setProof(null); return; }
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 3 * 1024 * 1024) {
      setCheckoutError("Choose an image under 3 MB."); event.target.value = ""; setProof(null); return;
    }
    const data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Could not read receipt.")); reader.readAsDataURL(file);
    });
    setProof({ data, name: file.name });
  }
  async function placeOrder(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setCheckoutError("");
    if (!proof) { setCheckoutError("Upload your payment receipt to submit your order."); return; }
    const form = new FormData(event.currentTarget);
    setSubmitting(true);
    try {
      const response = await fetch(`${API}/api/orders`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          storefrontKey: "tindahan",
          items: lines.map(({ product, quantity }) => ({ productId: product.id, quantity })),
          customerName: form.get("customerName"), customerPhone: form.get("customerPhone"), customerEmail: form.get("customerEmail"),
          deliveryAddress: form.get("deliveryAddress"), city: form.get("city"), province: form.get("province"), postalCode: form.get("postalCode"),
          region, shipmentPreference, paymentMethod: form.get("paymentMethod"), imageData: proof.data, imageName: proof.name,
        }),
      });
      const result = await response.json();
      if (!response.ok || !result.success) throw new Error(result.error || "Order could not be placed.");
      setSuccessOrder(result.orderNumber); setCart({}); setProof(null); setCheckoutOpen(false); setCartOpen(false);
    } catch (error) { setCheckoutError(error instanceof Error ? error.message : "Order could not be placed."); }
    finally { setSubmitting(false); }
  }

  const cartCount = lines.reduce((sum, line) => sum + line.quantity, 0);

  return <main>
    <header className="topbar wrap">
      <Link href="/" className="brand" aria-label="Tindahan ni Tinapa home"><span className="brand-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link>
      <nav className="toplinks"><a href="#shop">Shop</a><Link href="/track-order">Track order</Link></nav>
      <button className="cart-button" onClick={() => setCartOpen(true)} aria-label={`Open bag, ${cartCount} items`}>Your bag <b>{cartCount}</b></button>
    </header>

    <section className="hero wrap">
      <div className="hero-copy"><span className="eyebrow"><i /> A LITTLE BIT OF EVERYTHING</span><h1>Budol finds.<br/><em>Better together.</em></h1><p>Shop ready-to-go favorites or join a group buy for something special. We’ll keep every batch and update in one cozy place.</p><a className="button primary" href="#shop">Find your next budol <span>↘</span></a></div>
    </section>


    <section className="shop-section wrap" id="shop">
      <div className="section-heading"><div><span className="eyebrow">THE TINAPA FINDS</span><h2>Shop the good stuff<span>.</span></h2></div><label className="search"><span>⌕</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search finds..." aria-label="Search products"/></label></div>
      <div className="catalog-controls"><div className="category-list"><button className={category === "all" ? "category active" : "category"} onClick={() => setCategory("all")}>Everything <span>{catalog?.products.length ?? 0}</span></button>{catalog?.categories.map((item) => <button key={item.id} className={category === item.id ? "category active" : "category"} onClick={() => setCategory(item.id)}>{item.icon} {item.name}</button>)}</div><span className="catalog-count">{visibleProducts.length} lovely {visibleProducts.length === 1 ? "find" : "finds"}</span></div>
      {loadError && <div className="state-card error-card"><b>Catalog is taking a little break.</b><span>{loadError}</span><button className="text-button" onClick={() => location.reload()}>Try again</button></div>}
      {!catalog && !loadError && <div className="state-card">Gathering the good stuff…</div>}
      {catalog && visibleProducts.length === 0 && <div className="state-card">No finds here yet. Try another category.</div>}
      {catalog && visibleProducts.length > 0 && <div className="product-grid">{visibleProducts.map((product, index) => {
        const orderable = product.kind !== "group_buy" || isBatchOrderable(product.batch ?? { status: "closed", deadline: "" });
        const canAdd = product.kind === "on_hand" ? product.stock > (cart[product.id]?.quantity ?? 0) : orderable;
        return <article className="product-card" key={product.id}>
          <div className={`product-visual visual-${index % 5}`}>{product.imageUrl ? <img src={product.imageUrl} alt={product.fullName} loading="lazy"/> : <span className="product-emoji">{product.emoji || (product.kind === "group_buy" ? "🎁" : "🛍️")}</span>}<span className={product.kind === "group_buy" ? "type-pill group-pill" : "type-pill stock-pill"}>{product.kind === "group_buy" ? `GROUP BUY · ${(product.batch?.status || (orderable ? "open" : "closed")).replaceAll("_", " ").toUpperCase()}` : "ON HAND"}</span>{product.compareAtPrice && product.compareAtPrice > product.price ? <span className="sale-pill">A little less</span> : null}</div>
          <div className="product-info"><div className="product-kicker">{product.kind === "group_buy" ? product.batch?.name ?? "New group buy" : product.stock > 0 ? `${product.stock} ready to go` : "Sold out"}</div><h3>{product.fullName || product.name}</h3>{product.description && <p>{product.description}</p>}
            {product.kind === "group_buy" && product.batch && <div className="batch-meta"><span>Order by <b>{date(product.batch.deadline)}</b></span>{product.batch.eta && <span>Est. arrival <b>{date(product.batch.eta)}</b></span>}</div>}
            <div className="product-bottom"><div><b className="price">{money(product.price)}</b>{product.compareAtPrice && product.compareAtPrice > product.price && <del>{money(product.compareAtPrice)}</del>}</div><button className="add-button" onClick={() => add(product)} disabled={!canAdd} aria-label={`Add ${product.fullName} to bag`}>{canAdd ? "Add to bag +" : product.kind === "group_buy" ? "Batch closed" : "Sold out"}</button></div>
          </div>
        </article>;
      })}</div>}
    </section>

    <footer className="footer wrap"><Link href="/" className="brand"><span className="brand-mark small-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link><p>Made with care for your next favorite thing.</p><Link href="/track-order">Track an order ↗</Link><span className="copyright">© {new Date().getFullYear()} Tindahan ni Tinapa</span></footer>

    {cartOpen && <div className="overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) setCartOpen(false); }}><aside className="drawer" aria-label="Your shopping bag"><div className="drawer-head"><div><span className="eyebrow">YOUR GOOD FINDS</span><h2>Your bag <span>({cartCount})</span></h2></div><button className="close-button" onClick={() => setCartOpen(false)} aria-label="Close bag">×</button></div>{lines.length === 0 ? <div className="empty-bag"><span>♡</span><b>Your bag is waiting.</b><p>Pick something lovely to get started.</p><button className="button primary" onClick={() => setCartOpen(false)}>Browse finds</button></div> : <>
      <div className="drawer-lines">{lines.map(({ product, quantity }) => <div className="cart-line" key={product.id}><div className="cart-thumb">{product.imageUrl ? <img src={product.imageUrl} alt=""/> : product.emoji || "🛍️"}</div><div className="cart-details"><b>{product.fullName}</b><small>{product.kind === "group_buy" ? product.batch?.name ?? "Group buy" : "On hand"}</small><span>{money(product.price)}</span></div><div className="quantity-control"><button onClick={() => changeQuantity(product, quantity - 1)} aria-label="Decrease quantity">−</button><span>{quantity}</span><button onClick={() => changeQuantity(product, quantity + 1)} disabled={product.kind === "on_hand" && quantity >= product.stock || quantity >= 100} aria-label="Increase quantity">+</button></div></div>)}</div>
      <div className="drawer-foot"><label className="field-label">Where are we sending this?</label><select className="field" value={region} onChange={(e) => setRegion(e.target.value)}><option value="luzon">Luzon</option><option value="visayas">Visayas</option><option value="mindanao">Mindanao</option><option value="other">Other area</option></select><label className="shipment-choice"><input type="radio" name="shipping" checked={shipmentPreference === "separate"} onChange={() => setShipmentPreference("separate")}/><span><b>Ship separately</b><small>On-hand items + each group-buy batch</small></span></label><label className="shipment-choice"><input type="radio" name="shipping" checked={shipmentPreference === "together"} onChange={() => setShipmentPreference("together")}/><span><b>Ship together</b><small>One shipment when every item is ready</small></span></label><div className="total-line"><span>Items</span><b>{money(total.subtotal)}</b></div>{total.shipments.map((shipment, index) => <div className="total-line muted" key={`${shipment.kind}-${shipment.batchId}-${index}`}><span>Shipping · {shipment.kind === "combined" ? "one parcel" : shipment.kind === "on_hand" ? "on-hand" : catalog?.batches.find((batch) => String(batch.id) === String(shipment.batchId))?.name || "group buy"}</span><b>{money(shipment.shipping)}</b></div>)}<div className="total-line grand-total"><span>Total to pay</span><b>{money(total.total)}</b></div><button className="button primary checkout-button" onClick={() => { setCartOpen(false); setCheckoutOpen(true); }}>Continue to checkout <span>→</span></button><p className="total-note">Your total is calculated from the current catalog and shipping area.</p></div>
    </>}</aside></div>}

    {checkoutOpen && <div className="overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) setCheckoutOpen(false); }}><section className="checkout-modal"><div className="drawer-head"><div><span className="eyebrow">ALMOST YOURS</span><h2>Checkout</h2></div><button className="close-button" onClick={() => setCheckoutOpen(false)} aria-label="Close checkout">×</button></div><form onSubmit={placeOrder} className="checkout-form"><div className="form-grid"><label>Your name<input className="field" name="customerName" required autoComplete="name"/></label><label>Mobile number<input className="field" name="customerPhone" required autoComplete="tel" inputMode="tel"/></label><label className="full-field">Email (optional)<input className="field" name="customerEmail" type="email" autoComplete="email"/></label><label className="full-field">Street address<input className="field" name="deliveryAddress" required autoComplete="street-address"/></label><label>City / town<input className="field" name="city" required autoComplete="address-level2"/></label><label>Province<input className="field" name="province" required autoComplete="address-level1"/></label><label>Postal code<input className="field" name="postalCode" autoComplete="postal-code" inputMode="numeric"/></label><label>Payment method<select className="field" name="paymentMethod"><option>GCash</option><option>Maya</option><option>Bank transfer</option></select></label></div><div className="payment-note"><span>♡</span><p>Send payment using the details shared by the seller. Upload your receipt below so Tin can verify it.</p></div><label className="upload-box"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={onProofChange}/><span className="upload-icon">↑</span><b>{proof ? proof.name : "Upload payment receipt"}</b><small>JPG, PNG or WebP · up to 3 MB</small></label><div className="checkout-summary"><span>Full total ({total.shipments.length} {total.shipments.length === 1 ? "shipment" : "shipments"})</span><b>{money(total.total)}</b></div>{checkoutError && <p className="form-error" role="alert">{checkoutError}</p>}<button className="button primary checkout-button" type="submit" disabled={submitting}>{submitting ? "Sending order…" : "Place order · " + money(total.total)}</button><p className="secure-note">Your order, price, stock and shipping are checked again before it’s saved.</p></form></section></div>}

    {successOrder && <div className="overlay success-overlay"><section className="success-card"><span className="success-heart">♡</span><span className="eyebrow">ORDER SENT</span><h2>You’re on the list!</h2><p>Your order number is <b>{successOrder}</b>. Keep it handy while Tin checks your receipt.</p><Link className="button primary" href={`/track-order?order=${encodeURIComponent(successOrder)}`}>Track your order →</Link><button className="text-button" onClick={() => setSuccessOrder("")}>Back to shopping</button></section></div>}
  </main>;
}

import { NextRequest, NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import { orders, orderItems, orderEvents } from "@/lib/db/schema";
import { appSettings, groupBuyBatches, products } from "@/lib/db/schema";
import { desc, eq, inArray, sql } from "drizzle-orm";
import {
  getProductByName,
  getProductById,
  calculateShippingFee,
} from "@/lib/products";
import { uploadPaymentProof } from "@/lib/google-drive/client";
import { prepareGroupBuyOrder } from "@/lib/group-buy/commerce";

async function createTindahanOrder(body: any) {
  const customerName = String(body.customerName || "").trim();
  const customerPhone = String(body.customerPhone || "").trim();
  const deliveryAddress = String(body.deliveryAddress || "").trim();
  const city = String(body.city || "").trim();
  const province = String(body.province || "").trim();
  const region = String(body.region || province).trim();
  const items = Array.isArray(body.items) ? body.items : [];
  if (!customerName || !customerPhone || !deliveryAddress || !city || !province) {
    return NextResponse.json({ success: false, error: "Name, phone, address, city, and province are required." }, { status: 400, headers: corsHeaders() });
  }
  if (!items.length || items.length > 100) {
    return NextResponse.json({ success: false, error: "Add between 1 and 100 cart lines." }, { status: 400, headers: corsHeaders() });
  }
  if (body.shipmentPreference !== "together" && body.shipmentPreference !== "separate") {
    return NextResponse.json({ success: false, error: "Choose a shipment option." }, { status: 400, headers: corsHeaders() });
  }

  const proof = typeof body.imageData === "string"
    ? body.imageData.match(/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/)
    : null;
  if (!proof || proof[2].length > 4_200_000) {
    return NextResponse.json({ success: false, error: "Upload a PNG, JPG, or WebP receipt under 3 MB." }, { status: 400, headers: corsHeaders() });
  }

  try {
    const buffer = Buffer.from(proof[2], "base64");
    if (!buffer.length || buffer.length > 3 * 1024 * 1024) {
      return NextResponse.json({ success: false, error: "Receipt must be under 3 MB." }, { status: 400, headers: corsHeaders() });
    }
    const mimeType = proof[1];
    const extension = mimeType === "image/jpeg" ? "jpg" : mimeType.split("/")[1];
    const originalName = typeof body.imageName === "string" ? body.imageName.replace(/\.[^.]+$/, "") : "receipt";
    const safeName = originalName.replace(/[^a-zA-Z0-9_-]/g, "_").slice(-80) || "receipt";

    const productIds: string[] = [...new Set<string>(items.map((item: any) => String(item?.productId || "")).filter((id: string) => id.length > 0))];
    const [dbProducts, shippingRecord] = await Promise.all([
      productIds.length ? db.query.products.findMany({ where: inArray(products.id, productIds) }) : Promise.resolve([]),
      db.query.appSettings.findFirst({ where: eq(appSettings.key, "shipping_config") }),
    ]);
    const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
    const dbBatches = batchIds.length
      ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
      : [];
    const prepared = prepareGroupBuyOrder({
      items,
      shipmentPreference: body.shipmentPreference,
      region,
      shippingConfig: (shippingRecord?.value ?? {}) as Record<string, Record<string, number>>,
      products: new Map(dbProducts.map((product) => [product.id, product])),
      batches: new Map(dbBatches.map((batch) => [batch.id, batch])),
    });

    const uploadedProof = await uploadPaymentProof(buffer, mimeType, `${Date.now()}_${safeName}.${extension}`);

    const latestOrder = await db.query.orders.findFirst({ orderBy: [desc(orders.id)], columns: { id: true } });
    const orderNumber = `TT-${new Date().getFullYear()}-${String((latestOrder?.id ?? 0) + 1).padStart(5, "0")}-${randomUUID().slice(0, 4).toUpperCase()}`;
    const orderData = {
      orderNumber,
      shipmentPreference: body.shipmentPreference,
      customerName,
      customerPhone,
      customerEmail: String(body.customerEmail || "").trim().slice(0, 254),
      deliveryAddress,
      city,
      province,
      postalCode: String(body.postalCode || "").trim(),
      shippingMethod: `Tindahan ni Tinapa · ${province}`,
      shippingFee: prepared.shippingFee,
      paymentMethod: String(body.paymentMethod || "GCash").trim().slice(0, 80),
      paymentProofFileId: uploadedProof.fileId,
      subtotal: prepared.subtotal,
      total: prepared.total,
      notes: String(body.notes || "").trim().slice(0, 500),
    };
    const result = await db.execute(sql`
      SELECT create_tindahan_order(
        ${JSON.stringify(orderData)}::jsonb,
        ${JSON.stringify(prepared.shipments)}::jsonb,
        ${JSON.stringify(prepared.items)}::jsonb
      ) AS order_result
    `);
    const created = result.rows[0]?.order_result as { id: number; orderNumber: string } | undefined;
    if (!created) throw new Error("Order could not be saved.");

    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "New Tindahan ni Tinapa order",
        body: `Order #${created.orderNumber} from ${customerName}`,
        url: "/admin/group-buy/orders",
        tag: `order-${created.id}`,
      }).catch((error) => console.warn("Group-buy notification failed:", error));
    } catch (error) {
      console.warn("Could not load push service:", error);
    }

    return NextResponse.json({ success: true, orderId: created.id, orderNumber: created.orderNumber }, { status: 201, headers: corsHeaders() });
  } catch (error: any) {
    const message = error?.message || "Could not place order.";
    const clientError = /cart is empty|invalid cart item|not enough stock|no longer available|batch.*closed|shipping is unavailable|valid shipping region|maximum quantity|supported payment limit|invalid price|price .* too high/i.test(message);
    return NextResponse.json({ success: false, error: message }, { status: clientError ? 400 : 500, headers: corsHeaders() });
  }
}

// CORS Headers helper
function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

export async function GET(request: NextRequest) {
  try {
    const latest = await db.query.orders.findFirst({
      where: eq(orders.storefrontKey, "main"),
      orderBy: [desc(orders.id)],
      columns: {
        id: true,
        orderNumber: true,
        customerName: true,
        total: true,
        orderStatus: true,
        paymentStatus: true,
        createdAt: true,
      },
    });

    return NextResponse.json(
      {
        success: true,
        latestOrder: latest || null,
        timestamp: Date.now(),
      },
      { headers: corsHeaders() }
    );
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500, headers: corsHeaders() }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    if (!body) {
      return NextResponse.json(
        { success: false, error: "Invalid JSON payload." },
        { status: 400, headers: corsHeaders() }
      );
    }

    if (body.storefrontKey === "tindahan") return await createTindahanOrder(body);

    // Extract fields with alias fallback support
    const customerName = String(
      body.customerName || body.name || body.recipient || ""
    ).trim();
    const customerPhone = String(
      body.customerPhone || body.phone || body.contactNumber || ""
    ).trim();
    const deliveryAddress = String(
      body.deliveryAddress || body.address || body.street || ""
    ).trim();
    const city = String(body.city || "Metro Manila").trim();
    const province = String(body.province || "Metro Manila").trim();
    const customerEmail = body.customerEmail || body.email || null;
    const postalCode = body.postalCode || null;

    const shippingMethodName = String(
      body.shippingMethod || body.shipping || "Standard Shipping"
    ).trim();
    const rawShippingFee = Number(body.shippingFee ?? 0);

    const paymentMethod = String(body.paymentMethod || "GCash").trim();
    const notes = body.notes || body.specialInstructions || body.remarks || null;

    // Validate required customer info
    if (!customerName) {
      return NextResponse.json(
        { success: false, error: "customerName is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!customerPhone) {
      return NextResponse.json(
        { success: false, error: "customerPhone is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!deliveryAddress) {
      return NextResponse.json(
        { success: false, error: "deliveryAddress is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Validate items array
    const rawItems = Array.isArray(body.items) ? body.items : [];
    if (rawItems.length === 0) {
      return NextResponse.json(
        { success: false, error: "At least one item is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Process & calculate items
    const parsedLineItems: Array<{
      productId: string | null;
      productName: string;
      unitPrice: number;
      quantity: number;
      subtotal: number;
    }> = [];

    let calculatedSubtotalInCents = 0;
    let totalItemCount = 0;

    for (const rawItem of rawItems) {
      const quantity = Math.max(1, Number(rawItem.quantity || 1));
      totalItemCount += quantity;

      const rawItemName = String(
        rawItem.name || rawItem.productName || rawItem.id || "Product Item"
      ).trim();

      // Lookup product reference if available
      const matched =
        (rawItem.id ? getProductById(rawItem.id) : undefined) ||
        getProductByName(rawItem.name || rawItem.productName || "");

      const officialName = matched?.fullName || matched?.name || rawItemName;
      const rawPrice = Number(
        rawItem.price ?? rawItem.unitPrice ?? matched?.price ?? 0
      );

      // Convert unit price to cents if < 100000
      const unitPriceInCents =
        rawPrice > 0 && rawPrice < 100000
          ? Math.round(rawPrice * 100)
          : Math.round(rawPrice);

      const itemSubtotal = unitPriceInCents * quantity;
      calculatedSubtotalInCents += itemSubtotal;

      parsedLineItems.push({
        productId: matched?.id ? String(matched.id) : null,
        productName: officialName,
        unitPrice: unitPriceInCents,
        quantity,
        subtotal: itemSubtotal,
      });
    }

    // Validate & compute tiered shipping fee from products.json shipping_config
    const calculatedTieredShippingFeePesos = calculateShippingFee(
      shippingMethodName || province || city,
      totalItemCount
    );

    // Determine final shipping fee in cents
    const shippingFeeInCents =
      rawShippingFee > 0
        ? rawShippingFee < 10000
          ? Math.round(rawShippingFee * 100)
          : Math.round(rawShippingFee)
        : Math.round(calculatedTieredShippingFeePesos * 100);

    const totalInCents = calculatedSubtotalInCents + shippingFeeInCents;

    // Parse & resolve payment proof Google Drive file ID
    let resolvedProofFileId: string | null = null;

    const base64DataStr =
      typeof body.imageData === "string" && body.imageData.startsWith("data:image/")
        ? body.imageData
        : typeof body.paymentProofUrl === "string" && body.paymentProofUrl.startsWith("data:image/")
        ? body.paymentProofUrl
        : null;

    const urlOrIdCandidate = String(body.driveUrl || body.paymentProofUrl || body.paymentProofFileId || "").trim();
    const driveUrlMatch = urlOrIdCandidate.match(/\/d\/([a-zA-Z0-9_-]+)/);

    if (driveUrlMatch) {
      resolvedProofFileId = driveUrlMatch[1];
    } else if (/^[a-zA-Z0-9_-]{25,50}$/.test(urlOrIdCandidate) && !urlOrIdCandidate.includes(".")) {
      resolvedProofFileId = urlOrIdCandidate;
    } else if (base64DataStr) {
      // Direct base64 image data URL uploaded from client: upload to Google Drive via Service Account
      try {
        const match = base64DataStr.match(/^data:(image\/\w+);base64,(.+)$/);
        if (match) {
          const mimeType = match[1];
          const base64Data = match[2];
          const buffer = Buffer.from(base64Data, "base64");
          const ext = mimeType.split("/")[1] || "png";
          const clientName = typeof body.imageName === "string" && body.imageName.trim() ? body.imageName.trim() : null;
          const filename = clientName || `proof_${Date.now()}.${ext}`;
          const uploadRes = await uploadPaymentProof(buffer, mimeType, filename);
          resolvedProofFileId = uploadRes.fileId;
        }
      } catch (uploadErr) {
        console.warn("Direct base64 Google Drive upload fallback notice:", uploadErr);
      }
    } else if (urlOrIdCandidate && urlOrIdCandidate !== "uploaded_receipt") {
      // Fallback: search Drive by filename if provided
      try {
        const { google } = await import("googleapis");
        const email = process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
        const privateKey = process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;
        if (email && privateKey) {
          const auth = new google.auth.GoogleAuth({
            credentials: {
              client_email: email,
              private_key: privateKey.replace(/\\n/g, "\n"),
            },
            scopes: ["https://www.googleapis.com/auth/drive"],
          });
          const drive = google.drive({ version: "v3", auth });
          const list = await drive.files.list({
            q: `name = '${urlOrIdCandidate.replace(/'/g, "\\'")}' and trashed = false`,
            fields: "files(id, name)",
            pageSize: 1,
          });
          if (list.data.files && list.data.files.length > 0 && list.data.files[0].id) {
            resolvedProofFileId = list.data.files[0].id;
          } else {
            resolvedProofFileId = urlOrIdCandidate;
          }
        } else {
          resolvedProofFileId = urlOrIdCandidate;
        }
      } catch {
        resolvedProofFileId = urlOrIdCandidate;
      }
    }

    const hasProof = Boolean(resolvedProofFileId && resolvedProofFileId.trim() !== "");

    // Generate next Order Number sequence using Drizzle query
    const lastOrder = await db.query.orders.findFirst({
      orderBy: [desc(orders.id)],
      columns: { id: true },
    });
    const nextSeq = (lastOrder?.id ?? 0) + 1;
    const prefix = process.env.ORDER_NUMBER_PREFIX ?? "PB";
    const year = new Date().getFullYear();
    const padded = String(nextSeq).padStart(4, "0");
    const orderNumber = `${prefix}-${year}-${padded}`;

    // 1. Insert main order
    const [newOrder] = await db
      .insert(orders)
      .values({
        orderNumber,
        customerName,
        customerPhone,
        customerEmail,
        deliveryAddress,
        city,
        province,
        postalCode,
        shippingMethod: shippingMethodName,
        shippingFee: shippingFeeInCents,
        paymentMethod,
        paymentProofFileId: hasProof ? resolvedProofFileId : null,
        paymentStatus: hasProof ? "under_verification" : "pending",
        orderStatus: hasProof ? "payment_verification" : "pending_payment",
        subtotal: calculatedSubtotalInCents,
        total: totalInCents,
        notes,
      })
      .returning();

    // 2. Insert line items
    await db.insert(orderItems).values(
      parsedLineItems.map((item) => ({
        ...item,
        orderId: newOrder.id,
      }))
    );

    // 3. Record initial events
    await db.insert(orderEvents).values({
      orderId: newOrder.id,
      eventType: "order_submitted",
      description: "Order submitted by customer.",
    });

    if (hasProof) {
      await db.insert(orderEvents).values({
        orderId: newOrder.id,
        eventType: "payment_proof_uploaded",
        description: "Payment proof attached with order.",
      });
    }

    // 4. Trigger background Web Push notification to all registered phones and devices
    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "🌸 New Order Received!",
        body: `Order #${newOrder.orderNumber} from ${newOrder.customerName} (₱${(newOrder.total / 100).toLocaleString()})`,
        url: `/admin/orders/${newOrder.id}`,
        tag: `order-${newOrder.id}`,
      }).catch((pushErr) => {
        console.warn("Background Web Push trigger error:", pushErr);
      });
    } catch (e) {
      console.warn("Could not load push service:", e);
    }

    return NextResponse.json(
      {
        success: true,
        orderId: newOrder.id,
        orderNumber: newOrder.orderNumber,
        message: "Order placed successfully",
      },
      { status: 201, headers: corsHeaders() }
    );
  } catch (error: any) {
    console.error("Public customer intake order API error:", error);
    return NextResponse.json(
      {
        success: false,
        error: error.message || "Failed to process customer order intake.",
      },
      { status: 500, headers: corsHeaders() }
    );
  }
}

