import { google } from "googleapis";

let _drive: ReturnType<typeof google.drive> | null = null;

function getDriveClient() {
  if (_drive) return _drive;

  const email =
    process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
  const privateKey =
    process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;

  if (!email || !privateKey) {
    throw new Error(
      "Google Drive credentials not configured. Set GOOGLE_CLIENT_EMAIL and GOOGLE_PRIVATE_KEY in .env.local."
    );
  }

  const auth = new google.auth.GoogleAuth({
    credentials: {
      client_email: email,
      // Replace escaped \n with actual newlines
      private_key: privateKey.replace(/\\n/g, "\n"),
    },
    scopes: ["https://www.googleapis.com/auth/drive"],
  });

  _drive = google.drive({ version: "v3", auth });
  return _drive;
}

export interface UploadResult {
  fileId: string;
  webViewLink: string;
}

/**
 * Upload a payment proof image to Google Drive.
 * Returns the file ID stored in Neon.
 * The caller (server action) must have already validated file type + size.
 */
export async function uploadPaymentProof(
  buffer: Buffer,
  mimeType: string,
  filename: string
): Promise<UploadResult> {
  const drive = getDriveClient();
  const folderId = process.env.GOOGLE_DRIVE_FOLDER_ID;

  if (!folderId) {
    throw new Error("GOOGLE_DRIVE_FOLDER_ID environment variable is not set.");
  }

  const { Readable } = await import("stream");
  const stream = Readable.from(buffer);

  const response = await drive.files.create({
    requestBody: {
      name: filename,
      parents: [folderId],
      mimeType,
    },
    media: {
      mimeType,
      body: stream,
    },
    fields: "id,webViewLink",
  });

  const fileId = response.data.id;
  const webViewLink = response.data.webViewLink;

  if (!fileId) {
    throw new Error("Google Drive did not return a file ID.");
  }

  return { fileId, webViewLink: webViewLink ?? "" };
}

/**
 * Stream a file from Google Drive back to an admin-only API route.
 * Never called from client-side code.
 */
export async function streamFileFromDrive(
  fileId: string
): Promise<{ data: NodeJS.ReadableStream; mimeType: string }> {
  const drive = getDriveClient();

  let targetId = fileId.trim();

  // If input looks like a filename (contains dot or extension or hyphenated UUID), query Drive by name
  if (targetId.includes(".") || targetId.includes("-")) {
    try {
      const sanitized = targetId.replace(/'/g, "\\'");
      const searchRes = await drive.files.list({
        q: `name = '${sanitized}' and trashed = false`,
        fields: "files(id, name, mimeType)",
        pageSize: 1,
      });
      if (searchRes.data.files && searchRes.data.files.length > 0 && searchRes.data.files[0].id) {
        targetId = searchRes.data.files[0].id;
      }
    } catch (searchErr) {
      console.warn("Drive filename search notice:", searchErr);
    }
  }

  try {
    // Get metadata first
    const meta = await drive.files.get({
      fileId: targetId,
      fields: "mimeType",
    });

    const mimeType = meta.data.mimeType ?? "application/octet-stream";

    const response = await drive.files.get(
      { fileId: targetId, alt: "media" },
      { responseType: "stream" }
    );

    return { data: response.data as NodeJS.ReadableStream, mimeType };
  } catch (err: any) {
    // If direct lookup by targetId failed and we hadn't searched by name yet, attempt name search fallback
    if (targetId === fileId) {
      try {
        const sanitized = fileId.replace(/'/g, "\\'");
        const fallbackRes = await drive.files.list({
          q: `name = '${sanitized}' and trashed = false`,
          fields: "files(id, name, mimeType)",
          pageSize: 1,
        });
        if (fallbackRes.data.files && fallbackRes.data.files.length > 0 && fallbackRes.data.files[0].id) {
          const resolvedId = fallbackRes.data.files[0].id;
          const meta = await drive.files.get({
            fileId: resolvedId,
            fields: "mimeType",
          });
          const mimeType = meta.data.mimeType ?? "application/octet-stream";
          const response = await drive.files.get(
            { fileId: resolvedId, alt: "media" },
            { responseType: "stream" }
          );
          return { data: response.data as NodeJS.ReadableStream, mimeType };
        }
      } catch (fallbackErr) {
        // ignore
      }
    }
    throw err;
  }
}

/**
 * Delete a file from Google Drive (e.g. on order deletion or re-upload).
 */
export async function deleteFileFromDrive(fileId: string): Promise<void> {
  const drive = getDriveClient();
  await drive.files.delete({ fileId });
}

export type GroupBuyItemInput = { productId: string; quantity: number };

export type CommerceProduct = {
  id: string;
  name: string;
  fullName: string;
  storefrontKey: string;
  kind: "standard" | "on_hand" | "group_buy";
  price: number;
  stock: number;
  isAvailable: boolean | null;
  batchId: number | null;
};

export type CommerceBatch = {
  id: number;
  status: string;
  deadline: string | Date;
};

type ShippingRates = Record<string, Record<string, number>>;

function isOrderable(batch: CommerceBatch | undefined, now: Date) {
  return Boolean(
    batch &&
      batch.status === "open" &&
      new Date(batch.deadline).getTime() > now.getTime()
  );
}

function getShippingRate(config: ShippingRates, region: string, quantity: number) {
  const normalized = region.trim().toLowerCase();
  if (!["luzon", "visayas", "mindanao", "other"].includes(normalized)) {
    throw new Error("Choose a valid shipping region.");
  }
  let rates = config[normalized];
  if (!rates) throw new Error("Shipping is unavailable for this region.");
  const fee = quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
  if (!Number.isSafeInteger(fee) || fee < 0) throw new Error("Shipping is unavailable for this region.");
  return fee;
}

const MAX_DB_INTEGER = 2_147_483_647;

export function prepareGroupBuyOrder(input: {
  items: Array<GroupBuyItemInput & { price?: number }>;
  shipmentPreference: "together" | "separate";
  region: string;
  shippingConfig: ShippingRates;
  products: Map<string, CommerceProduct>;
  batches: Map<number, CommerceBatch>;
  now?: Date;
}) {
  if (!input.items.length) throw new Error("Cart is empty.");
  if (!["luzon", "visayas", "mindanao", "other"].includes(input.region.trim().toLowerCase())) {
    throw new Error("Choose a valid shipping region.");
  }

  const quantities = new Map<string, number>();
  for (const item of input.items) {
    const quantity = Number(item.quantity);
    if (!item.productId || !Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
      throw new Error("Invalid cart item.");
    }
    const totalQuantity = (quantities.get(item.productId) ?? 0) + quantity;
    if (totalQuantity > 100) throw new Error("Maximum quantity per product is 100.");
    quantities.set(item.productId, totalQuantity);
  }

  const now = input.now ?? new Date();
  const orderItems = [...quantities].map(([productId, quantity]) => {
    const product = input.products.get(productId);
    if (
      !product ||
      product.storefrontKey !== "tindahan" ||
      product.kind === "standard" ||
      !product.isAvailable
    ) {
      throw new Error("A product is no longer available. Refresh the catalog and try again.");
    }
    if (product.kind === "on_hand" && product.stock < quantity) {
      throw new Error(`Not enough stock for ${product.name}.`);
    }
    if (product.kind === "group_buy" && !isOrderable(product.batchId ? input.batches.get(product.batchId) : undefined, now)) {
      throw new Error(`The group-buy batch for ${product.name} is closed.`);
    }
    if (!Number.isSafeInteger(product.price) || product.price < 0) throw new Error(`Invalid price for ${product.name}.`);
    const unitPrice = Math.round(product.price * 100);
    if (unitPrice > MAX_DB_INTEGER) throw new Error(`Price for ${product.name} is too high.`);
    const subtotal = unitPrice * quantity;
    if (subtotal > MAX_DB_INTEGER) throw new Error("Order total exceeds the supported payment limit.");
    return {
      productId: product.id,
      productName: product.fullName,
      productKind: product.kind,
      batchId: product.batchId,
      unitPrice,
      quantity,
      subtotal,
    };
  });

  const groups: Array<{ kind: "combined" | "on_hand" | "group_buy"; batchId: number | null; itemIndexes: number[]; quantity: number }> = [];
  if (input.shipmentPreference === "together") {
    groups.push({
      kind: "combined",
      batchId: null,
      itemIndexes: orderItems.map((_, index) => index),
      quantity: orderItems.reduce((sum, item) => sum + item.quantity, 0),
    });
  } else {
    const groupMap = new Map<string, (typeof groups)[number]>();
    orderItems.forEach((item, index) => {
      const kind = item.productKind === "on_hand" ? "on_hand" : "group_buy";
      const key = kind === "on_hand" ? "on_hand" : `batch:${item.batchId}`;
      const group = groupMap.get(key) ?? {
        kind,
        batchId: kind === "group_buy" ? item.batchId : null,
        itemIndexes: [],
        quantity: 0,
      };
      group.itemIndexes.push(index);
      group.quantity += item.quantity;
      groupMap.set(key, group);
    });
    groups.push(...groupMap.values());
  }

  const shipments = groups.map((group) => ({
    ...group,
    shippingFee: Math.round(getShippingRate(input.shippingConfig, input.region, group.quantity) * 100),
  }));
  const subtotal = orderItems.reduce((sum, item) => sum + item.subtotal, 0);
  const shippingFee = shipments.reduce((sum, shipment) => sum + shipment.shippingFee, 0);
  if (subtotal > MAX_DB_INTEGER || shippingFee > MAX_DB_INTEGER || subtotal + shippingFee > MAX_DB_INTEGER) {
    throw new Error("Order total exceeds the supported payment limit.");
  }
  return {
    items: orderItems.map((item, itemIndex) => ({
      ...item,
      shipmentIndex: shipments.findIndex((shipment) => shipment.itemIndexes.includes(itemIndex)),
    })),
    shipments,
    subtotal,
    shippingFee,
    total: subtotal + shippingFee,
  };
}

import { NextRequest, NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import { orders, orderItems, orderEvents } from "@/lib/db/schema";
import { appSettings, groupBuyBatches, products } from "@/lib/db/schema";
import { desc, eq, inArray, sql } from "drizzle-orm";
import {
  getProductByName,
  getProductById,
  calculateShippingFee,
} from "@/lib/products";
import { uploadPaymentProof } from "@/lib/google-drive/client";
import { prepareGroupBuyOrder } from "@/lib/group-buy/commerce";

async function createTindahanOrder(body: any) {
  const customerName = String(body.customerName || "").trim();
  const customerPhone = String(body.customerPhone || "").trim();
  const deliveryAddress = String(body.deliveryAddress || "").trim();
  const city = String(body.city || "").trim();
  const province = String(body.province || "").trim();
  const region = String(body.region || province).trim();
  const items = Array.isArray(body.items) ? body.items : [];
  if (!customerName || !customerPhone || !deliveryAddress || !city || !province) {
    return NextResponse.json({ success: false, error: "Name, phone, address, city, and province are required." }, { status: 400, headers: corsHeaders() });
  }
  if (!items.length || items.length > 100) {
    return NextResponse.json({ success: false, error: "Add between 1 and 100 cart lines." }, { status: 400, headers: corsHeaders() });
  }
  if (body.shipmentPreference !== "together" && body.shipmentPreference !== "separate") {
    return NextResponse.json({ success: false, error: "Choose a shipment option." }, { status: 400, headers: corsHeaders() });
  }

  const proof = typeof body.imageData === "string"
    ? body.imageData.match(/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/)
    : null;
  if (!proof || proof[2].length > 4_200_000) {
    return NextResponse.json({ success: false, error: "Upload a PNG, JPG, or WebP receipt under 3 MB." }, { status: 400, headers: corsHeaders() });
  }

  try {
    const buffer = Buffer.from(proof[2], "base64");
    if (!buffer.length || buffer.length > 3 * 1024 * 1024) {
      return NextResponse.json({ success: false, error: "Receipt must be under 3 MB." }, { status: 400, headers: corsHeaders() });
    }
    const mimeType = proof[1];
    const extension = mimeType === "image/jpeg" ? "jpg" : mimeType.split("/")[1];
    const originalName = typeof body.imageName === "string" ? body.imageName.replace(/\.[^.]+$/, "") : "receipt";
    const safeName = originalName.replace(/[^a-zA-Z0-9_-]/g, "_").slice(-80) || "receipt";

    const productIds: string[] = [...new Set<string>(items.map((item: any) => String(item?.productId || "")).filter((id: string) => id.length > 0))];
    const [dbProducts, shippingRecord] = await Promise.all([
      productIds.length ? db.query.products.findMany({ where: inArray(products.id, productIds) }) : Promise.resolve([]),
      db.query.appSettings.findFirst({ where: eq(appSettings.key, "shipping_config") }),
    ]);
    const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
    const dbBatches = batchIds.length
      ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
      : [];
    const prepared = prepareGroupBuyOrder({
      items,
      shipmentPreference: body.shipmentPreference,
      region,
      shippingConfig: (shippingRecord?.value ?? {}) as Record<string, Record<string, number>>,
      products: new Map(dbProducts.map((product) => [product.id, product])),
      batches: new Map(dbBatches.map((batch) => [batch.id, batch])),
    });

    const uploadedProof = await uploadPaymentProof(buffer, mimeType, `${Date.now()}_${safeName}.${extension}`);

    const latestOrder = await db.query.orders.findFirst({ orderBy: [desc(orders.id)], columns: { id: true } });
    const orderNumber = `TT-${new Date().getFullYear()}-${String((latestOrder?.id ?? 0) + 1).padStart(5, "0")}-${randomUUID().slice(0, 4).toUpperCase()}`;
    const orderData = {
      orderNumber,
      shipmentPreference: body.shipmentPreference,
      customerName,
      customerPhone,
      customerEmail: String(body.customerEmail || "").trim().slice(0, 254),
      deliveryAddress,
      city,
      province,
      postalCode: String(body.postalCode || "").trim(),
      shippingMethod: `Tindahan ni Tinapa · ${province}`,
      shippingFee: prepared.shippingFee,
      paymentMethod: String(body.paymentMethod || "GCash").trim().slice(0, 80),
      paymentProofFileId: uploadedProof.fileId,
      subtotal: prepared.subtotal,
      total: prepared.total,
      notes: String(body.notes || "").trim().slice(0, 500),
    };
    const result = await db.execute(sql`
      SELECT create_tindahan_order(
        ${JSON.stringify(orderData)}::jsonb,
        ${JSON.stringify(prepared.shipments)}::jsonb,
        ${JSON.stringify(prepared.items)}::jsonb
      ) AS order_result
    `);
    const created = result.rows[0]?.order_result as { id: number; orderNumber: string } | undefined;
    if (!created) throw new Error("Order could not be saved.");

    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "New Tindahan ni Tinapa order",
        body: `Order #${created.orderNumber} from ${customerName}`,
        url: "/admin/group-buy/orders",
        tag: `order-${created.id}`,
      }).catch((error) => console.warn("Group-buy notification failed:", error));
    } catch (error) {
      console.warn("Could not load push service:", error);
    }

    return NextResponse.json({ success: true, orderId: created.id, orderNumber: created.orderNumber }, { status: 201, headers: corsHeaders() });
  } catch (error: any) {
    const message = error?.message || "Could not place order.";
    const clientError = /cart is empty|invalid cart item|not enough stock|no longer available|batch.*closed|shipping is unavailable|valid shipping region|maximum quantity|supported payment limit|invalid price|price .* too high/i.test(message);
    return NextResponse.json({ success: false, error: message }, { status: clientError ? 400 : 500, headers: corsHeaders() });
  }
}

// CORS Headers helper
function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

export async function GET(request: NextRequest) {
  try {
    const latest = await db.query.orders.findFirst({
      where: eq(orders.storefrontKey, "main"),
      orderBy: [desc(orders.id)],
      columns: {
        id: true,
        orderNumber: true,
        customerName: true,
        total: true,
        orderStatus: true,
        paymentStatus: true,
        createdAt: true,
      },
    });

    return NextResponse.json(
      {
        success: true,
        latestOrder: latest || null,
        timestamp: Date.now(),
      },
      { headers: corsHeaders() }
    );
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500, headers: corsHeaders() }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    if (!body) {
      return NextResponse.json(
        { success: false, error: "Invalid JSON payload." },
        { status: 400, headers: corsHeaders() }
      );
    }

    if (body.storefrontKey === "tindahan") return await createTindahanOrder(body);

    // Extract fields with alias fallback support
    const customerName = String(
      body.customerName || body.name || body.recipient || ""
    ).trim();
    const customerPhone = String(
      body.customerPhone || body.phone || body.contactNumber || ""
    ).trim();
    const deliveryAddress = String(
      body.deliveryAddress || body.address || body.street || ""
    ).trim();
    const city = String(body.city || "Metro Manila").trim();
    const province = String(body.province || "Metro Manila").trim();
    const customerEmail = body.customerEmail || body.email || null;
    const postalCode = body.postalCode || null;

    const shippingMethodName = String(
      body.shippingMethod || body.shipping || "Standard Shipping"
    ).trim();
    const rawShippingFee = Number(body.shippingFee ?? 0);

    const paymentMethod = String(body.paymentMethod || "GCash").trim();
    const notes = body.notes || body.specialInstructions || body.remarks || null;

    // Validate required customer info
    if (!customerName) {
      return NextResponse.json(
        { success: false, error: "customerName is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!customerPhone) {
      return NextResponse.json(
        { success: false, error: "customerPhone is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!deliveryAddress) {
      return NextResponse.json(
        { success: false, error: "deliveryAddress is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Validate items array
    const rawItems = Array.isArray(body.items) ? body.items : [];
    if (rawItems.length === 0) {
      return NextResponse.json(
        { success: false, error: "At least one item is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Process & calculate items
    const parsedLineItems: Array<{
      productId: string | null;
      productName: string;
      unitPrice: number;
      quantity: number;
      subtotal: number;
    }> = [];

    let calculatedSubtotalInCents = 0;
    let totalItemCount = 0;

    for (const rawItem of rawItems) {
      const quantity = Math.max(1, Number(rawItem.quantity || 1));
      totalItemCount += quantity;

      const rawItemName = String(
        rawItem.name || rawItem.productName || rawItem.id || "Product Item"
      ).trim();

      // Lookup product reference if available
      const matched =
        (rawItem.id ? getProductById(rawItem.id) : undefined) ||
        getProductByName(rawItem.name || rawItem.productName || "");

      const officialName = matched?.fullName || matched?.name || rawItemName;
      const rawPrice = Number(
        rawItem.price ?? rawItem.unitPrice ?? matched?.price ?? 0
      );

      // Convert unit price to cents if < 100000
      const unitPriceInCents =
        rawPrice > 0 && rawPrice < 100000
          ? Math.round(rawPrice * 100)
          : Math.round(rawPrice);

      const itemSubtotal = unitPriceInCents * quantity;
      calculatedSubtotalInCents += itemSubtotal;

      parsedLineItems.push({
        productId: matched?.id ? String(matched.id) : null,
        productName: officialName,
        unitPrice: unitPriceInCents,
        quantity,
        subtotal: itemSubtotal,
      });
    }

    // Validate & compute tiered shipping fee from products.json shipping_config
    const calculatedTieredShippingFeePesos = calculateShippingFee(
      shippingMethodName || province || city,
      totalItemCount
    );

    // Determine final shipping fee in cents
    const shippingFeeInCents =
      rawShippingFee > 0
        ? rawShippingFee < 10000
          ? Math.round(rawShippingFee * 100)
          : Math.round(rawShippingFee)
        : Math.round(calculatedTieredShippingFeePesos * 100);

    const totalInCents = calculatedSubtotalInCents + shippingFeeInCents;

    // Parse & resolve payment proof Google Drive file ID
    let resolvedProofFileId: string | null = null;

    const base64DataStr =
      typeof body.imageData === "string" && body.imageData.startsWith("data:image/")
        ? body.imageData
        : typeof body.paymentProofUrl === "string" && body.paymentProofUrl.startsWith("data:image/")
        ? body.paymentProofUrl
        : null;

    const urlOrIdCandidate = String(body.driveUrl || body.paymentProofUrl || body.paymentProofFileId || "").trim();
    const driveUrlMatch = urlOrIdCandidate.match(/\/d\/([a-zA-Z0-9_-]+)/);

    if (driveUrlMatch) {
      resolvedProofFileId = driveUrlMatch[1];
    } else if (/^[a-zA-Z0-9_-]{25,50}$/.test(urlOrIdCandidate) && !urlOrIdCandidate.includes(".")) {
      resolvedProofFileId = urlOrIdCandidate;
    } else if (base64DataStr) {
      // Direct base64 image data URL uploaded from client: upload to Google Drive via Service Account
      try {
        const match = base64DataStr.match(/^data:(image\/\w+);base64,(.+)$/);
        if (match) {
          const mimeType = match[1];
          const base64Data = match[2];
          const buffer = Buffer.from(base64Data, "base64");
          const ext = mimeType.split("/")[1] || "png";
          const clientName = typeof body.imageName === "string" && body.imageName.trim() ? body.imageName.trim() : null;
          const filename = clientName || `proof_${Date.now()}.${ext}`;
          const uploadRes = await uploadPaymentProof(buffer, mimeType, filename);
          resolvedProofFileId = uploadRes.fileId;
        }
      } catch (uploadErr) {
        console.warn("Direct base64 Google Drive upload fallback notice:", uploadErr);
      }
    } else if (urlOrIdCandidate && urlOrIdCandidate !== "uploaded_receipt") {
      // Fallback: search Drive by filename if provided
      try {
        const { google } = await import("googleapis");
        const email = process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
        const privateKey = process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;
        if (email && privateKey) {
          const auth = new google.auth.GoogleAuth({
            credentials: {
              client_email: email,
              private_key: privateKey.replace(/\\n/g, "\n"),
            },
            scopes: ["https://www.googleapis.com/auth/drive"],
          });
          const drive = google.drive({ version: "v3", auth });
          const list = await drive.files.list({
            q: `name = '${urlOrIdCandidate.replace(/'/g, "\\'")}' and trashed = false`,
            fields: "files(id, name)",
            pageSize: 1,
          });
          if (list.data.files && list.data.files.length > 0 && list.data.files[0].id) {
            resolvedProofFileId = list.data.files[0].id;
          } else {
            resolvedProofFileId = urlOrIdCandidate;
          }
        } else {
          resolvedProofFileId = urlOrIdCandidate;
        }
      } catch {
        resolvedProofFileId = urlOrIdCandidate;
      }
    }

    const hasProof = Boolean(resolvedProofFileId && resolvedProofFileId.trim() !== "");

    // Generate next Order Number sequence using Drizzle query
    const lastOrder = await db.query.orders.findFirst({
      orderBy: [desc(orders.id)],
      columns: { id: true },
    });
    const nextSeq = (lastOrder?.id ?? 0) + 1;
    const prefix = process.env.ORDER_NUMBER_PREFIX ?? "PB";
    const year = new Date().getFullYear();
    const padded = String(nextSeq).padStart(4, "0");
    const orderNumber = `${prefix}-${year}-${padded}`;

    // 1. Insert main order
    const [newOrder] = await db
      .insert(orders)
      .values({
        orderNumber,
        customerName,
        customerPhone,
        customerEmail,
        deliveryAddress,
        city,
        province,
        postalCode,
        shippingMethod: shippingMethodName,
        shippingFee: shippingFeeInCents,
        paymentMethod,
        paymentProofFileId: hasProof ? resolvedProofFileId : null,
        paymentStatus: hasProof ? "under_verification" : "pending",
        orderStatus: hasProof ? "payment_verification" : "pending_payment",
        subtotal: calculatedSubtotalInCents,
        total: totalInCents,
        notes,
      })
      .returning();

    // 2. Insert line items
    await db.insert(orderItems).values(
      parsedLineItems.map((item) => ({
        ...item,
        orderId: newOrder.id,
      }))
    );

    // 3. Record initial events
    await db.insert(orderEvents).values({
      orderId: newOrder.id,
      eventType: "order_submitted",
      description: "Order submitted by customer.",
    });

    if (hasProof) {
      await db.insert(orderEvents).values({
        orderId: newOrder.id,
        eventType: "payment_proof_uploaded",
        description: "Payment proof attached with order.",
      });
    }

    // 4. Trigger background Web Push notification to all registered phones and devices
    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "🌸 New Order Received!",
        body: `Order #${newOrder.orderNumber} from ${newOrder.customerName} (₱${(newOrder.total / 100).toLocaleString()})`,
        url: `/admin/orders/${newOrder.id}`,
        tag: `order-${newOrder.id}`,
      }).catch((pushErr) => {
        console.warn("Background Web Push trigger error:", pushErr);
      });
    } catch (e) {
      console.warn("Could not load push service:", e);
    }

    return NextResponse.json(
      {
        success: true,
        orderId: newOrder.id,
        orderNumber: newOrder.orderNumber,
        message: "Order placed successfully",
      },
      { status: 201, headers: corsHeaders() }
    );
  } catch (error: any) {
    console.error("Public customer intake order API error:", error);
    return NextResponse.json(
      {
        success: false,
        error: error.message || "Failed to process customer order intake.",
      },
      { status: 500, headers: corsHeaders() }
    );
  }
}

import {
  pgTable,
  serial,
  text,
  integer,
  boolean,
  timestamp,
  pgEnum,
  index,
  unique,
  jsonb,
} from "drizzle-orm/pg-core";
import { relations } from "drizzle-orm";

// ============================================================
// ENUMS
// ============================================================

export const paymentStatusEnum = pgEnum("payment_status", [
  "pending",
  "under_verification",
  "paid",
  "rejected",
]);

export const orderStatusEnum = pgEnum("order_status", [
  "pending_payment",
  "payment_verification",
  "paid",
  "processing",
  "ready_to_ship",
  "shipped",
  "completed",
  "cancelled",
]);

export const userRoleEnum = pgEnum("user_role", ["admin", "staff"]);
export const storefrontKeyEnum = pgEnum("storefront_key", ["main", "tindahan"]);
export const productKindEnum = pgEnum("product_kind", ["standard", "on_hand", "group_buy"]);
export const groupBuyBatchStatusEnum = pgEnum("group_buy_batch_status", [
  "open",
  "closed",
  "ordered",
  "arrived",
]);
export const shipmentKindEnum = pgEnum("shipment_kind", ["combined", "on_hand", "group_buy"]);
export const shipmentStatusEnum = pgEnum("shipment_status", [
  "processing",
  "ready_to_ship",
  "shipped",
  "completed",
]);

// ============================================================
// CATEGORIES
// ============================================================

export const categories = pgTable(
  "categories",
  {
    id: text("id").primaryKey(), // slugified name, e.g. "tirzepatide-complete-set"
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    name: text("name").notNull(),
    icon: text("icon").default("💉"),
    pill: text("pill").default(""),
    sortOrder: integer("sort_order").default(0),
    isActive: boolean("is_active").default(true),
    createdAt: timestamp("created_at").defaultNow(),
  },
  (t) => [
    index("categories_sort_order_idx").on(t.sortOrder),
    index("categories_is_active_idx").on(t.isActive),
  ]
);

// ============================================================
// GROUP BUY BATCHES
// ============================================================

export const groupBuyBatches = pgTable(
  "group_buy_batches",
  {
    id: serial("id").primaryKey(),
    name: text("name").notNull(),
    status: groupBuyBatchStatusEnum("status").notNull().default("open"),
    deadline: timestamp("deadline", { withTimezone: true }).notNull(),
    eta: timestamp("eta", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("group_buy_batches_status_deadline_idx").on(t.status, t.deadline)]
);

// ============================================================
// PRODUCTS
// ============================================================

export const products = pgTable(
  "products",
  {
    id: text("id").primaryKey(), // e.g., "tir10_set"
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    kind: productKindEnum("kind").notNull().default("standard"),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    categoryId: text("category_id").references(() => categories.id, {
      onDelete: "cascade",
    }),
    name: text("name").notNull(),
    fullName: text("full_name").notNull(),
    price: integer("price").notNull(),
    compareAtPrice: integer("compare_at_price"),
    description: text("description"),
    imageUrl: text("image_url"),
    stock: integer("stock").notNull().default(0),
    emoji: text("emoji").default("💉"),
    isAvailable: boolean("is_available").default(true),
    sortOrder: integer("sort_order").default(0),
    createdAt: timestamp("created_at").defaultNow(),
  },
  (t) => [
    index("products_category_id_idx").on(t.categoryId),
    index("products_storefront_kind_idx").on(t.storefrontKey, t.kind),
    index("products_batch_id_idx").on(t.batchId),
    index("products_is_available_idx").on(t.isAvailable),
    index("products_sort_order_idx").on(t.sortOrder),
  ]
);

// ============================================================
// APP SETTINGS
// ============================================================

export const appSettings = pgTable("app_settings", {
  key: text("key").primaryKey(), // e.g., "shipping_config"
  value: jsonb("value").notNull(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// ============================================================
// SHIPPING METHODS (Legacy support)
// ============================================================

export const shippingMethods = pgTable("shipping_methods", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  fee: integer("fee").notNull(), // cents
  isActive: boolean("is_active").notNull().default(true),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// ============================================================
// ORDERS
// ============================================================

export const orders = pgTable(
  "orders",
  {
    id: serial("id").primaryKey(),
    orderNumber: text("order_number").notNull(),
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    shipmentPreference: text("shipment_preference"),
    // Customer info (snapshot at time of order)
    customerName: text("customer_name").notNull(),
    customerPhone: text("customer_phone").notNull(),
    customerEmail: text("customer_email"),
    // Delivery
    deliveryAddress: text("delivery_address").notNull(),
    city: text("city").notNull(),
    province: text("province").notNull(),
    postalCode: text("postal_code"),
    shippingMethod: text("shipping_method").notNull(),
    shippingFee: integer("shipping_fee").notNull().default(0), // cents
    // Payment
    paymentMethod: text("payment_method").notNull(),
    paymentProofFileId: text("payment_proof_file_id"), // Google Drive file ID
    paymentStatus: paymentStatusEnum("payment_status").notNull().default("pending"),
    // Order
    orderStatus: orderStatusEnum("order_status").notNull().default("pending_payment"),
    // Financials (all in cents)
    subtotal: integer("subtotal").notNull(),
    total: integer("total").notNull(),
    // Internal
    notes: text("notes"),
    rejectionReason: text("rejection_reason"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("orders_order_number_unique").on(t.orderNumber),
    index("orders_order_number_idx").on(t.orderNumber),
    index("orders_customer_phone_idx").on(t.customerPhone),
    index("orders_customer_name_idx").on(t.customerName),
    index("orders_payment_status_idx").on(t.paymentStatus),
    index("orders_order_status_idx").on(t.orderStatus),
    index("orders_created_at_idx").on(t.createdAt),
  ]
);

// ============================================================
// ORDER SHIPMENTS
// ============================================================

export const orderShipments = pgTable(
  "order_shipments",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id").notNull().references(() => orders.id, { onDelete: "cascade" }),
    kind: shipmentKindEnum("kind").notNull(),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    shippingFee: integer("shipping_fee").notNull().default(0),
    status: shipmentStatusEnum("status").notNull().default("processing"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("order_shipments_order_id_idx").on(t.orderId)]
);

// ============================================================
// ORDER ITEMS (price snapshot)
// ============================================================

export const orderItems = pgTable(
  "order_items",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    productId: text("product_id"),
    productKind: productKindEnum("product_kind").notNull().default("standard"),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    shipmentId: integer("shipment_id").references(() => orderShipments.id, { onDelete: "set null" }),
    // Price snapshot — historical prices preserved even if product changes
    productName: text("product_name").notNull(),
    unitPrice: integer("unit_price").notNull(), // cents
    quantity: integer("quantity").notNull(),
    subtotal: integer("subtotal").notNull(), // unit_price * quantity in cents
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("order_items_order_id_idx").on(t.orderId),
    index("order_items_product_id_idx").on(t.productId),
  ]
);

// ============================================================
// ORDER EVENTS (timeline)
// ============================================================

export const orderEvents = pgTable(
  "order_events",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    eventType: text("event_type").notNull(), // e.g. "order_submitted", "payment_confirmed"
    description: text("description"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("order_events_order_id_idx").on(t.orderId)]
);

// ============================================================
// USERS (admin/staff)
// ============================================================

export const users = pgTable(
  "users",
  {
    id: serial("id").primaryKey(),
    email: text("email").notNull(),
    passwordHash: text("password_hash").notNull(),
    name: text("name").notNull(),
    role: userRoleEnum("role").notNull().default("admin"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("users_email_unique").on(t.email),
    index("users_email_idx").on(t.email),
  ]
);

// ============================================================
// PUSH SUBSCRIPTIONS
// ============================================================

export const pushSubscriptions = pgTable(
  "push_subscriptions",
  {
    id: serial("id").primaryKey(),
    endpoint: text("endpoint").notNull(),
    p256dh: text("p256dh").notNull(),
    auth: text("auth").notNull(),
    userAgent: text("user_agent"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [unique("push_subscriptions_endpoint_key").on(t.endpoint)]
);

// ============================================================
// DRIZZLE RELATIONS
// ============================================================

export const categoriesRelations = relations(categories, ({ many }) => ({
  products: many(products),
}));

export const groupBuyBatchesRelations = relations(groupBuyBatches, ({ many }) => ({
  products: many(products),
  orderItems: many(orderItems),
  shipments: many(orderShipments),
}));

export const productsRelations = relations(products, ({ one }) => ({
  category: one(categories, {
    fields: [products.categoryId],
    references: [categories.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [products.batchId],
    references: [groupBuyBatches.id],
  }),
}));

export const ordersRelations = relations(orders, ({ many }) => ({
  orderItems: many(orderItems),
  orderEvents: many(orderEvents),
  shipments: many(orderShipments),
}));

export const orderShipmentsRelations = relations(orderShipments, ({ one, many }) => ({
  order: one(orders, {
    fields: [orderShipments.orderId],
    references: [orders.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [orderShipments.batchId],
    references: [groupBuyBatches.id],
  }),
  items: many(orderItems),
}));

export const orderItemsRelations = relations(orderItems, ({ one }) => ({
  order: one(orders, {
    fields: [orderItems.orderId],
    references: [orders.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [orderItems.batchId],
    references: [groupBuyBatches.id],
  }),
  shipment: one(orderShipments, {
    fields: [orderItems.shipmentId],
    references: [orderShipments.id],
  }),
}));

export const orderEventsRelations = relations(orderEvents, ({ one }) => ({
  order: one(orders, {
    fields: [orderEvents.orderId],
    references: [orders.id],
  }),
}));

// ============================================================
// TYPE EXPORTS
// ============================================================

export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;
export type Product = typeof products.$inferSelect;
export type NewProduct = typeof products.$inferInsert;
export type GroupBuyBatch = typeof groupBuyBatches.$inferSelect;
export type NewGroupBuyBatch = typeof groupBuyBatches.$inferInsert;
export type OrderShipment = typeof orderShipments.$inferSelect;
export type NewOrderShipment = typeof orderShipments.$inferInsert;
export type AppSetting = typeof appSettings.$inferSelect;
export type NewAppSetting = typeof appSettings.$inferInsert;

export type Order = typeof orders.$inferSelect;
export type NewOrder = typeof orders.$inferInsert;
export type OrderItem = typeof orderItems.$inferSelect;
export type NewOrderItem = typeof orderItems.$inferInsert;
export type OrderEvent = typeof orderEvents.$inferSelect;
export type User = typeof users.$inferSelect;
export type ShippingMethod = typeof shippingMethods.$inferSelect;
export type PushSubscriptionRecord = typeof pushSubscriptions.$inferSelect;
export type NewPushSubscriptionRecord = typeof pushSubscriptions.$inferInsert;

export type PaymentStatus = (typeof paymentStatusEnum.enumValues)[number];
export type OrderStatus = (typeof orderStatusEnum.enumValues)[number];
export type StorefrontKey = (typeof storefrontKeyEnum.enumValues)[number];
export type ProductKind = (typeof productKindEnum.enumValues)[number];
export type GroupBuyBatchStatus = (typeof groupBuyBatchStatusEnum.enumValues)[number];

export type OrderWithItems = Order & {
  orderItems: OrderItem[];
  orderEvents: OrderEvent[];
};

"use server";

import { db } from "@/lib/db";
import { orders, orderEvents } from "@/lib/db/schema";
import { eq, sql } from "drizzle-orm";
import { auth } from "@/auth";
import {
  confirmPaymentSchema,
  rejectPaymentSchema,
  updateOrderStatusSchema,
  addOrderNoteSchema,
} from "@/lib/validation/schemas";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) {
    throw new Error("Unauthorized");
  }
  return session;
}

const STATUS_LABELS: Record<string, string> = {
  pending_payment: "Pending Payment",
  payment_verification: "Payment Verification",
  paid: "Paid",
  processing: "Processing",
  ready_to_ship: "Ready to Ship",
  shipped: "Shipped",
  completed: "Completed",
  cancelled: "Cancelled",
};

// ============================================================
// CONFIRM PAYMENT
// ============================================================

export async function confirmPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = confirmPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId } = parsed.data;

  const order = await db.query.orders.findFirst({
    where: (o, { eq }) => eq(o.id, orderId),
  });

  if (!order) return { success: false, error: "Order not found." };

  if (order.storefrontKey === "tindahan") {
    try {
      await db.execute(sql`SELECT confirm_tindahan_payment(${orderId})`);
    } catch (error: any) {
      const message = String(error?.message || "");
      if (message.includes("ON_HAND_STOCK_INSUFFICIENT")) {
        return { success: false, error: "Payment not confirmed. On-hand stock is no longer sufficient." };
      }
      console.error("Tindahan payment confirmation failed:", error);
      return { success: false, error: "Payment could not be confirmed. Check the group-buy migration and try again." };
    }

    revalidatePath("/");
    revalidatePath("/admin");
    revalidatePath("/admin/orders");
    revalidatePath("/admin/group-buy");
    revalidatePath("/admin/group-buy/orders");
    revalidatePath(`/admin/orders/${orderId}`);
    return { success: true };
  }

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "paid",
      orderStatus: "processing",
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline events
  await db.insert(orderEvents).values([
    {
      orderId,
      eventType: "payment_confirmed",
      description: "Payment confirmed by seller.",
    },
    {
      orderId,
      eventType: "order_processing",
      description: "Order is now being processed.",
    },
  ]);

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// REJECT PAYMENT
// ============================================================

export async function rejectPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = rejectPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    reason: formData.get("reason") as string | undefined,
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId, reason } = parsed.data;

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "rejected",
      orderStatus: "pending_payment",
      rejectionReason: reason || null,
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline event
  await db.insert(orderEvents).values({
    orderId,
    eventType: "payment_rejected",
    description: reason
      ? `Payment rejected. Reason: ${reason}`
      : "Payment rejected by seller.",
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// UPDATE ORDER STATUS (Form & Direct)
// ============================================================

export async function updateOrderStatus(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const rawNotes = formData.get("notes");
  const notes =
    rawNotes && typeof rawNotes === "string" && rawNotes.trim() !== ""
      ? rawNotes.trim()
      : undefined;

  const parsed = updateOrderStatusSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    orderStatus: formData.get("orderStatus"),
    notes,
  });
  if (!parsed.success) {
    console.error("updateOrderStatus validation failure:", parsed.error.format());
    return { success: false, error: "Invalid status or parameters." };
  }

  const { orderId, orderStatus } = parsed.data;

  return quickChangeOrderStatus(orderId, orderStatus, notes);
}

export async function quickChangeOrderStatus(
  orderId: number,
  orderStatus: string,
  notes?: string
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const currentOrder = await db.query.orders.findFirst({ where: eq(orders.id, orderId) });
  if (!currentOrder) return { success: false, error: "Order not found." };
  if (
    currentOrder.storefrontKey === "tindahan" &&
    currentOrder.paymentStatus !== "paid" &&
    (orderStatus === "paid" || orderStatus === "processing")
  ) {
    return { success: false, error: "Verify the receipt before marking this order paid." };
  }

  const updateData: Record<string, any> = {
    orderStatus,
    updatedAt: new Date(),
  };

  if (notes !== undefined) {
    updateData.notes = notes;
  }

  if (orderStatus === "paid" || orderStatus === "processing") {
    updateData.paymentStatus = "paid";
  }

  await db.update(orders).set(updateData).where(eq(orders.id, orderId));

  await db.insert(orderEvents).values({
    orderId,
    eventType: `status_updated_${orderStatus}`,
    description: `Order status updated to: ${STATUS_LABELS[orderStatus] ?? orderStatus}.`,
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// ADD INTERNAL NOTE
// ============================================================

export async function addOrderNote(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = addOrderNoteSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    note: formData.get("note"),
  });
