export type GroupBuyItemInput = { productId: string; quantity: number };

export type CommerceProduct = {
  id: string;
  name: string;
  fullName: string;
  storefrontKey: string;
  kind: "standard" | "on_hand" | "group_buy";
  price: number;
  stock: number;
  isAvailable: boolean | null;
  batchId: number | null;
};

export type CommerceBatch = {
  id: number;
  status: string;
  deadline: string | Date;
};

type ShippingRates = Record<string, Record<string, number>>;

export function normalizeShippingRates(value: unknown): ShippingRates {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const settings = value as Record<string, unknown>;
  const rates = settings.rates;
  return rates && typeof rates === "object" && !Array.isArray(rates)
    ? rates as ShippingRates
    : settings as ShippingRates;
}

function isOrderable(batch: CommerceBatch | undefined, now: Date) {
  return Boolean(
    batch &&
      batch.status === "open" &&
      new Date(batch.deadline).getTime() > now.getTime()
  );
}

function getShippingRate(config: ShippingRates, region: string, quantity: number) {
  const normalized = region.trim().toLowerCase();
  if (!["luzon", "visayas", "mindanao", "other"].includes(normalized)) {
    throw new Error("Choose a valid shipping region.");
  }
  let rates = config[normalized];
  if (!rates) throw new Error("Shipping is unavailable for this region.");
  const fee = quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
  if (!Number.isSafeInteger(fee) || fee < 0) throw new Error("Shipping is unavailable for this region.");
  return fee;
}

const MAX_DB_INTEGER = 2_147_483_647;

export function prepareGroupBuyOrder(input: {
  items: Array<GroupBuyItemInput & { price?: number }>;
  shipmentPreference: "together" | "separate";
  region: string;
  shippingConfig: ShippingRates;
  products: Map<string, CommerceProduct>;
  batches: Map<number, CommerceBatch>;
  now?: Date;
}) {
  if (!input.items.length) throw new Error("Cart is empty.");
  if (!["luzon", "visayas", "mindanao", "other"].includes(input.region.trim().toLowerCase())) {
    throw new Error("Choose a valid shipping region.");
  }

  const quantities = new Map<string, number>();
  for (const item of input.items) {
    const quantity = Number(item.quantity);
    if (!item.productId || !Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
      throw new Error("Invalid cart item.");
    }
    const totalQuantity = (quantities.get(item.productId) ?? 0) + quantity;
    if (totalQuantity > 100) throw new Error("Maximum quantity per product is 100.");
    quantities.set(item.productId, totalQuantity);
  }

  const now = input.now ?? new Date();
  const orderItems = [...quantities].map(([productId, quantity]) => {
    const product = input.products.get(productId);
    if (
      !product ||
      product.storefrontKey !== "tindahan" ||
      product.kind === "standard" ||
      !product.isAvailable
    ) {
      throw new Error("A product is no longer available. Refresh the catalog and try again.");
    }
    if (product.kind === "on_hand" && product.stock < quantity) {
      throw new Error(`Not enough stock for ${product.name}.`);
    }
    if (product.kind === "group_buy" && !isOrderable(product.batchId ? input.batches.get(product.batchId) : undefined, now)) {
      throw new Error(`The group-buy batch for ${product.name} is closed.`);
    }
    if (!Number.isSafeInteger(product.price) || product.price < 0) throw new Error(`Invalid price for ${product.name}.`);
    const unitPrice = Math.round(product.price * 100);
    if (unitPrice > MAX_DB_INTEGER) throw new Error(`Price for ${product.name} is too high.`);
    const subtotal = unitPrice * quantity;
    if (subtotal > MAX_DB_INTEGER) throw new Error("Order total exceeds the supported payment limit.");
    return {
      productId: product.id,
      productName: product.fullName,
      productKind: product.kind,
      batchId: product.batchId,
      unitPrice,
      quantity,
      subtotal,
    };
  });

  const groups: Array<{ kind: "combined" | "on_hand" | "group_buy"; batchId: number | null; itemIndexes: number[]; quantity: number }> = [];
  if (input.shipmentPreference === "together") {
    groups.push({
      kind: "combined",
      batchId: null,
      itemIndexes: orderItems.map((_, index) => index),
      quantity: orderItems.reduce((sum, item) => sum + item.quantity, 0),
    });
  } else {
    const groupMap = new Map<string, (typeof groups)[number]>();
    orderItems.forEach((item, index) => {
      const kind = item.productKind === "on_hand" ? "on_hand" : "group_buy";
      const key = kind === "on_hand" ? "on_hand" : `batch:${item.batchId}`;
      const group = groupMap.get(key) ?? {
        kind,
        batchId: kind === "group_buy" ? item.batchId : null,
        itemIndexes: [],
        quantity: 0,
      };
      group.itemIndexes.push(index);
      group.quantity += item.quantity;
      groupMap.set(key, group);
    });
    groups.push(...groupMap.values());
  }

  const shipments = groups.map((group) => ({
    ...group,
    shippingFee: Math.round(getShippingRate(input.shippingConfig, input.region, group.quantity) * 100),
  }));
  const subtotal = orderItems.reduce((sum, item) => sum + item.subtotal, 0);
  const shippingFee = shipments.reduce((sum, shipment) => sum + shipment.shippingFee, 0);
  if (subtotal > MAX_DB_INTEGER || shippingFee > MAX_DB_INTEGER || subtotal + shippingFee > MAX_DB_INTEGER) {
    throw new Error("Order total exceeds the supported payment limit.");
  }
  return {
    items: orderItems.map((item, itemIndex) => ({
      ...item,
      shipmentIndex: shipments.findIndex((shipment) => shipment.itemIndexes.includes(itemIndex)),
    })),
    shipments,
    subtotal,
    shippingFee,
    total: subtotal + shippingFee,
  };
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { categories, products, appSettings, groupBuyBatches } from "@/lib/db/schema";
import { eq, asc, and, inArray } from "drizzle-orm";
import { normalizeShippingRates } from "@/lib/group-buy/commerce";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
};

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: corsHeaders,
  });
}

export async function GET(request: Request) {
  try {
    const storefront = new URL(request.url).searchParams.get("storefront") === "tindahan"
      ? "tindahan"
      : "main";
    // 1. Fetch active categories ordered by sortOrder
    const dbCategories = await db.query.categories.findMany({
      where: and(eq(categories.isActive, true), eq(categories.storefrontKey, storefront)),
      orderBy: [asc(categories.sortOrder), asc(categories.createdAt)],
    });

    // 2. Fetch available products ordered by sortOrder
    const dbProducts = await db.query.products.findMany({
      where: and(eq(products.isAvailable, true), eq(products.storefrontKey, storefront)),
      orderBy: [asc(products.sortOrder), asc(products.createdAt)],
    });

    if (storefront === "tindahan") {
      const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
      const dbBatches = batchIds.length
        ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
        : [];
      const now = Date.now();
      const batches = dbBatches.map((batch) => ({
        ...batch,
        status: batch.status === "open" && batch.deadline.getTime() <= now ? "closed" : batch.status,
      }));
      const shippingConfigRecord = await db.query.appSettings.findFirst({
        where: eq(appSettings.key, "shipping_config"),
      });

      return NextResponse.json({
        categories: dbCategories.map((category) => ({
          id: category.id,
          name: category.name,
          icon: category.icon || "📦",
          pill: category.pill || "",
        })),
        products: dbProducts.map((product) => ({
          id: product.id,
          categoryId: product.categoryId,
          name: product.name,
          fullName: product.fullName,
          price: product.price,
          compareAtPrice: product.compareAtPrice,
          description: product.description,
          imageUrl: product.imageUrl,
          emoji: product.emoji || "📦",
          stock: product.stock,
          kind: product.kind,
          batchId: product.batchId,
          batch: batches.find((batch) => batch.id === product.batchId) ?? null,
        })),
        batches,
        shippingConfig: normalizeShippingRates(shippingConfigRecord?.value),
      }, {
        status: 200,
        headers: { ...corsHeaders, "Cache-Control": "public, s-maxage=30, stale-while-revalidate=60" },
      });
    }

    // Group products by categoryId
    const productsByCat = new Map<string, typeof dbProducts>();
    for (const prod of dbProducts) {
      if (!prod.categoryId) continue;
      if (!productsByCat.has(prod.categoryId)) {
        productsByCat.set(prod.categoryId, []);
      }
      productsByCat.get(prod.categoryId)!.push(prod);
    }

    // 3. Assemble category payload matching products.json 1:1
    const catalog = dbCategories
      .map((cat) => {
        const catProducts = productsByCat.get(cat.id) || [];
        return {
          category: cat.name,
          icon: cat.icon || "💉",
          pill: cat.pill || "",
          items: catProducts.map((p) => ({
            id: p.id,
            name: p.name,
            fullName: p.fullName,
            price: p.price,
            emoji: p.emoji || "💉",
          })),
        };
      })
      .filter((cat) => cat.items.length > 0);

    // 4. Fetch shipping_config from appSettings
    const shippingConfigRecord = await db.query.appSettings.findFirst({
      where: eq(appSettings.key, "shipping_config"),
    });

    if (shippingConfigRecord?.value) {
      catalog.push(shippingConfigRecord.value as any);
    }

    return NextResponse.json(catalog, {
      status: 200,
      headers: {
        ...corsHeaders,
        "Cache-Control": "public, s-maxage=30, stale-while-revalidate=60",
      },
    });
  } catch (error: any) {
    console.error("Failed to fetch dynamic products catalog:", error);
    return NextResponse.json(
      { error: "Failed to load products catalog", message: error?.message },
      {
        status: 500,
        headers: corsHeaders,
      }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import { orders, orderItems, orderEvents } from "@/lib/db/schema";
import { appSettings, groupBuyBatches, products } from "@/lib/db/schema";
import { desc, eq, inArray, sql } from "drizzle-orm";
import {
  getProductByName,
  getProductById,
  calculateShippingFee,
} from "@/lib/products";
import { uploadPaymentProof } from "@/lib/google-drive/client";
import { normalizeShippingRates, prepareGroupBuyOrder } from "@/lib/group-buy/commerce";

async function createTindahanOrder(body: any) {
  const customerName = String(body.customerName || "").trim();
  const customerPhone = String(body.customerPhone || "").trim();
  const deliveryAddress = String(body.deliveryAddress || "").trim();
  const city = String(body.city || "").trim();
  const province = String(body.province || "").trim();
  const region = String(body.region || province).trim();
  const items = Array.isArray(body.items) ? body.items : [];
  if (!customerName || !customerPhone || !deliveryAddress || !city || !province) {
    return NextResponse.json({ success: false, error: "Name, phone, address, city, and province are required." }, { status: 400, headers: corsHeaders() });
  }
  if (!items.length || items.length > 100) {
    return NextResponse.json({ success: false, error: "Add between 1 and 100 cart lines." }, { status: 400, headers: corsHeaders() });
  }
  if (body.shipmentPreference !== "together" && body.shipmentPreference !== "separate") {
    return NextResponse.json({ success: false, error: "Choose a shipment option." }, { status: 400, headers: corsHeaders() });
  }

  const proof = typeof body.imageData === "string"
    ? body.imageData.match(/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/)
    : null;
  if (!proof || proof[2].length > 4_200_000) {
    return NextResponse.json({ success: false, error: "Upload a PNG, JPG, or WebP receipt under 3 MB." }, { status: 400, headers: corsHeaders() });
  }

  try {
    const buffer = Buffer.from(proof[2], "base64");
    if (!buffer.length || buffer.length > 3 * 1024 * 1024) {
      return NextResponse.json({ success: false, error: "Receipt must be under 3 MB." }, { status: 400, headers: corsHeaders() });
    }
    const mimeType = proof[1];
    const extension = mimeType === "image/jpeg" ? "jpg" : mimeType.split("/")[1];
    const originalName = typeof body.imageName === "string" ? body.imageName.replace(/\.[^.]+$/, "") : "receipt";
    const safeName = originalName.replace(/[^a-zA-Z0-9_-]/g, "_").slice(-80) || "receipt";

    const productIds: string[] = [...new Set<string>(items.map((item: any) => String(item?.productId || "")).filter((id: string) => id.length > 0))];
    const [dbProducts, shippingRecord] = await Promise.all([
      productIds.length ? db.query.products.findMany({ where: inArray(products.id, productIds) }) : Promise.resolve([]),
      db.query.appSettings.findFirst({ where: eq(appSettings.key, "shipping_config") }),
    ]);
    const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
    const dbBatches = batchIds.length
      ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
      : [];
    const prepared = prepareGroupBuyOrder({
      items,
      shipmentPreference: body.shipmentPreference,
      region,
      shippingConfig: normalizeShippingRates(shippingRecord?.value),
      products: new Map(dbProducts.map((product) => [product.id, product])),
      batches: new Map(dbBatches.map((batch) => [batch.id, batch])),
    });

    const uploadedProof = await uploadPaymentProof(buffer, mimeType, `${Date.now()}_${safeName}.${extension}`);

    const latestOrder = await db.query.orders.findFirst({ orderBy: [desc(orders.id)], columns: { id: true } });
    const orderNumber = `TT-${new Date().getFullYear()}-${String((latestOrder?.id ?? 0) + 1).padStart(5, "0")}-${randomUUID().slice(0, 4).toUpperCase()}`;
    const orderData = {
      orderNumber,
      shipmentPreference: body.shipmentPreference,
      customerName,
      customerPhone,
      customerEmail: String(body.customerEmail || "").trim().slice(0, 254),
      deliveryAddress,
      city,
      province,
      postalCode: String(body.postalCode || "").trim(),
      shippingMethod: `Tindahan ni Tinapa · ${province}`,
      shippingFee: prepared.shippingFee,
      paymentMethod: String(body.paymentMethod || "GCash").trim().slice(0, 80),
      paymentProofFileId: uploadedProof.fileId,
      subtotal: prepared.subtotal,
      total: prepared.total,
      notes: String(body.notes || "").trim().slice(0, 500),
    };
    const result = await db.execute(sql`
      SELECT create_tindahan_order(
        ${JSON.stringify(orderData)}::jsonb,
        ${JSON.stringify(prepared.shipments)}::jsonb,
        ${JSON.stringify(prepared.items)}::jsonb
      ) AS order_result
    `);
    const created = result.rows[0]?.order_result as { id: number; orderNumber: string } | undefined;
    if (!created) throw new Error("Order could not be saved.");

    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "New Tindahan ni Tinapa order",
        body: `Order #${created.orderNumber} from ${customerName}`,
        url: "/admin/group-buy/orders",
        tag: `order-${created.id}`,
      }).catch((error) => console.warn("Group-buy notification failed:", error));
    } catch (error) {
      console.warn("Could not load push service:", error);
    }

    return NextResponse.json({ success: true, orderId: created.id, orderNumber: created.orderNumber }, { status: 201, headers: corsHeaders() });
  } catch (error: any) {
    const message = error?.message || "Could not place order.";
    const clientError = /cart is empty|invalid cart item|not enough stock|no longer available|batch.*closed|shipping is unavailable|valid shipping region|maximum quantity|supported payment limit|invalid price|price .* too high/i.test(message);
    return NextResponse.json({ success: false, error: message }, { status: clientError ? 400 : 500, headers: corsHeaders() });
  }
}

// CORS Headers helper
function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

export async function GET(request: NextRequest) {
  try {
    const latest = await db.query.orders.findFirst({
      where: eq(orders.storefrontKey, "main"),
      orderBy: [desc(orders.id)],
      columns: {
        id: true,
        orderNumber: true,
        customerName: true,
        total: true,
        orderStatus: true,
        paymentStatus: true,
        createdAt: true,
      },
    });

    return NextResponse.json(
      {
        success: true,
        latestOrder: latest || null,
        timestamp: Date.now(),
      },
      { headers: corsHeaders() }
    );
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500, headers: corsHeaders() }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    if (!body) {
      return NextResponse.json(
        { success: false, error: "Invalid JSON payload." },
        { status: 400, headers: corsHeaders() }
      );
    }

    if (body.storefrontKey === "tindahan") return await createTindahanOrder(body);

    // Extract fields with alias fallback support
    const customerName = String(
      body.customerName || body.name || body.recipient || ""
    ).trim();
    const customerPhone = String(
      body.customerPhone || body.phone || body.contactNumber || ""
    ).trim();
    const deliveryAddress = String(
      body.deliveryAddress || body.address || body.street || ""
    ).trim();
    const city = String(body.city || "Metro Manila").trim();
    const province = String(body.province || "Metro Manila").trim();
    const customerEmail = body.customerEmail || body.email || null;
    const postalCode = body.postalCode || null;

    const shippingMethodName = String(
      body.shippingMethod || body.shipping || "Standard Shipping"
    ).trim();
    const rawShippingFee = Number(body.shippingFee ?? 0);

    const paymentMethod = String(body.paymentMethod || "GCash").trim();
    const notes = body.notes || body.specialInstructions || body.remarks || null;

    // Validate required customer info
    if (!customerName) {
      return NextResponse.json(
        { success: false, error: "customerName is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!customerPhone) {
      return NextResponse.json(
        { success: false, error: "customerPhone is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!deliveryAddress) {
      return NextResponse.json(
        { success: false, error: "deliveryAddress is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Validate items array
    const rawItems = Array.isArray(body.items) ? body.items : [];
    if (rawItems.length === 0) {
      return NextResponse.json(
        { success: false, error: "At least one item is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Process & calculate items
    const parsedLineItems: Array<{
      productId: string | null;
      productName: string;
      unitPrice: number;
      quantity: number;
      subtotal: number;
    }> = [];

    let calculatedSubtotalInCents = 0;
    let totalItemCount = 0;

    for (const rawItem of rawItems) {
      const quantity = Math.max(1, Number(rawItem.quantity || 1));
      totalItemCount += quantity;

      const rawItemName = String(
        rawItem.name || rawItem.productName || rawItem.id || "Product Item"
      ).trim();

      // Lookup product reference if available
      const matched =
        (rawItem.id ? getProductById(rawItem.id) : undefined) ||
        getProductByName(rawItem.name || rawItem.productName || "");

      const officialName = matched?.fullName || matched?.name || rawItemName;
      const rawPrice = Number(
        rawItem.price ?? rawItem.unitPrice ?? matched?.price ?? 0
      );

      // Convert unit price to cents if < 100000
      const unitPriceInCents =
        rawPrice > 0 && rawPrice < 100000
          ? Math.round(rawPrice * 100)
          : Math.round(rawPrice);

      const itemSubtotal = unitPriceInCents * quantity;
      calculatedSubtotalInCents += itemSubtotal;

      parsedLineItems.push({
        productId: matched?.id ? String(matched.id) : null,
        productName: officialName,
        unitPrice: unitPriceInCents,
        quantity,
        subtotal: itemSubtotal,
      });
    }

    // Validate & compute tiered shipping fee from products.json shipping_config
    const calculatedTieredShippingFeePesos = calculateShippingFee(
      shippingMethodName || province || city,
      totalItemCount
    );

    // Determine final shipping fee in cents
    const shippingFeeInCents =
      rawShippingFee > 0
        ? rawShippingFee < 10000
          ? Math.round(rawShippingFee * 100)
          : Math.round(rawShippingFee)
        : Math.round(calculatedTieredShippingFeePesos * 100);

    const totalInCents = calculatedSubtotalInCents + shippingFeeInCents;

    // Parse & resolve payment proof Google Drive file ID
    let resolvedProofFileId: string | null = null;

    const base64DataStr =
      typeof body.imageData === "string" && body.imageData.startsWith("data:image/")
        ? body.imageData
        : typeof body.paymentProofUrl === "string" && body.paymentProofUrl.startsWith("data:image/")
        ? body.paymentProofUrl
        : null;

    const urlOrIdCandidate = String(body.driveUrl || body.paymentProofUrl || body.paymentProofFileId || "").trim();
    const driveUrlMatch = urlOrIdCandidate.match(/\/d\/([a-zA-Z0-9_-]+)/);

    if (driveUrlMatch) {
      resolvedProofFileId = driveUrlMatch[1];
    } else if (/^[a-zA-Z0-9_-]{25,50}$/.test(urlOrIdCandidate) && !urlOrIdCandidate.includes(".")) {
      resolvedProofFileId = urlOrIdCandidate;
    } else if (base64DataStr) {
      // Direct base64 image data URL uploaded from client: upload to Google Drive via Service Account
      try {
        const match = base64DataStr.match(/^data:(image\/\w+);base64,(.+)$/);
        if (match) {
          const mimeType = match[1];
          const base64Data = match[2];
          const buffer = Buffer.from(base64Data, "base64");
          const ext = mimeType.split("/")[1] || "png";
          const clientName = typeof body.imageName === "string" && body.imageName.trim() ? body.imageName.trim() : null;
          const filename = clientName || `proof_${Date.now()}.${ext}`;
          const uploadRes = await uploadPaymentProof(buffer, mimeType, filename);
          resolvedProofFileId = uploadRes.fileId;
        }
      } catch (uploadErr) {
        console.warn("Direct base64 Google Drive upload fallback notice:", uploadErr);
      }
    } else if (urlOrIdCandidate && urlOrIdCandidate !== "uploaded_receipt") {
      // Fallback: search Drive by filename if provided
      try {
        const { google } = await import("googleapis");
        const email = process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
        const privateKey = process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;
        if (email && privateKey) {
          const auth = new google.auth.GoogleAuth({
            credentials: {
              client_email: email,
              private_key: privateKey.replace(/\\n/g, "\n"),
            },
            scopes: ["https://www.googleapis.com/auth/drive"],
          });
          const drive = google.drive({ version: "v3", auth });
          const list = await drive.files.list({
            q: `name = '${urlOrIdCandidate.replace(/'/g, "\\'")}' and trashed = false`,
            fields: "files(id, name)",
            pageSize: 1,
          });
          if (list.data.files && list.data.files.length > 0 && list.data.files[0].id) {
            resolvedProofFileId = list.data.files[0].id;
          } else {
            resolvedProofFileId = urlOrIdCandidate;
          }
        } else {
          resolvedProofFileId = urlOrIdCandidate;
        }
      } catch {
        resolvedProofFileId = urlOrIdCandidate;
      }
    }

    const hasProof = Boolean(resolvedProofFileId && resolvedProofFileId.trim() !== "");

    // Generate next Order Number sequence using Drizzle query
    const lastOrder = await db.query.orders.findFirst({
      orderBy: [desc(orders.id)],
      columns: { id: true },
    });
    const nextSeq = (lastOrder?.id ?? 0) + 1;
    const prefix = process.env.ORDER_NUMBER_PREFIX ?? "PB";
    const year = new Date().getFullYear();
    const padded = String(nextSeq).padStart(4, "0");
    const orderNumber = `${prefix}-${year}-${padded}`;

    // 1. Insert main order
    const [newOrder] = await db
      .insert(orders)
      .values({
        orderNumber,
        customerName,
        customerPhone,
        customerEmail,
        deliveryAddress,
        city,
        province,
        postalCode,
        shippingMethod: shippingMethodName,
        shippingFee: shippingFeeInCents,
        paymentMethod,
        paymentProofFileId: hasProof ? resolvedProofFileId : null,
        paymentStatus: hasProof ? "under_verification" : "pending",
        orderStatus: hasProof ? "payment_verification" : "pending_payment",
        subtotal: calculatedSubtotalInCents,
        total: totalInCents,
        notes,
      })
      .returning();

    // 2. Insert line items
    await db.insert(orderItems).values(
      parsedLineItems.map((item) => ({
        ...item,
        orderId: newOrder.id,
      }))
    );

    // 3. Record initial events
    await db.insert(orderEvents).values({
      orderId: newOrder.id,
      eventType: "order_submitted",
      description: "Order submitted by customer.",
    });

    if (hasProof) {
      await db.insert(orderEvents).values({
        orderId: newOrder.id,
        eventType: "payment_proof_uploaded",
        description: "Payment proof attached with order.",
      });
    }

    // 4. Trigger background Web Push notification to all registered phones and devices
    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "🌸 New Order Received!",
        body: `Order #${newOrder.orderNumber} from ${newOrder.customerName} (₱${(newOrder.total / 100).toLocaleString()})`,
        url: `/admin/orders/${newOrder.id}`,
        tag: `order-${newOrder.id}`,
      }).catch((pushErr) => {
        console.warn("Background Web Push trigger error:", pushErr);
      });
    } catch (e) {
      console.warn("Could not load push service:", e);
    }

    return NextResponse.json(
      {
        success: true,
        orderId: newOrder.id,
        orderNumber: newOrder.orderNumber,
        message: "Order placed successfully",
      },
      { status: 201, headers: corsHeaders() }
    );
  } catch (error: any) {
    console.error("Public customer intake order API error:", error);
    return NextResponse.json(
      {
        success: false,
        error: error.message || "Failed to process customer order intake.",
      },
      { status: 500, headers: corsHeaders() }
    );
  }
}

