 */

export const FULLSTACK_AUDIT_VERSION = "2.16.0";
export const FULLSTACK_AUDIT_ENGINE = "Living Fullstack Atlas & Minimalist Engine v2.16.0";
export const FULLSTACK_AUDIT_RELEASE_DATE = "2026-10-27";

export type AuditProfile = "triad" | "standalone" | "custom";

export interface ProfileOptions {
  profile: AuditProfile;
  ponytail: boolean;
  caveman: boolean;
  superpowers: boolean;
}

export interface VersionInfo {
  version: string;
  engine: string;
  releaseDate: string;
}

export function getVersionBanner(): string {
  return `fullstack-audit v${FULLSTACK_AUDIT_VERSION} (engine: ${FULLSTACK_AUDIT_ENGINE}, released: ${FULLSTACK_AUDIT_RELEASE_DATE})`;
}

export function getAtlasProvenanceHeader(title: string, subtitle: string): string {
  return `<!-- Generated by fullstack-audit v${FULLSTACK_AUDIT_VERSION} on ${FULLSTACK_AUDIT_RELEASE_DATE} -->
# ${title}

> ${subtitle}
> **Atlas Version**: \`v${FULLSTACK_AUDIT_VERSION}\` | **Engine**: \`${FULLSTACK_AUDIT_ENGINE}\` | **Status**: Verified Clean

`;
}

export interface AtlasIndexEntry {
  symbol: string;
  category: "route" | "component" | "overlay" | "icon" | "query" | "api" | "model" | "action" | "slice" | "label" | "test" | "symbol" | "live-dot" | "capsule-pill";
  file: string;
  line: number;
  meta?: string;
  atlasRef: string;
}

export interface CausalGraphNode {
  id: string;
  label?: string;
  type: string;
}

export interface CausalGraphLink {
  source: string;
  target: string;
  type: string;
}

export interface CausalGraph {
  nodes: CausalGraphNode[];
  links: CausalGraphLink[];
}

export interface AtlasIndex {
  version: string;
  engine: string;
  generatedAt: string;
  totalEntries: number;
  files?: string[];
  entries: AtlasIndexEntry[];
  causalGraph?: CausalGraph;
}

// Zero-Dependency Sub-Word Tokenizer for Code & Architecture Identifiers
export function tokenizeCodeIdentifier(input: string): string[] {
  if (!input) return [];
  return input
    // Split camelCase & PascalCase
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    // Split acronyms like HTMLParser -> HTML Parser
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    // Split punctuation and path separators
    .replace(/[-_./\\:()[\]{}'"`]/g, " ")
    .toLowerCase()
    .split(/\s+/)
    .filter(t => t.length > 1);
}

// Fullstack Concept & Synonym Map (0ms In-Memory Concept Expansion)
export const FULLSTACK_SYNONYMS: Record<string, string[]> = {
  "login": ["signin", "auth", "session", "user"],
  "signin": ["login", "auth", "session"],
  "auth": ["login", "signin", "session", "guard", "middleware", "token"],
  "checkout": ["payment", "stripe", "cart", "order", "purchase", "billing", "subscription"],
  "payment": ["checkout", "stripe", "invoice", "billing"],
  "modal": ["dialog", "drawer", "sheet", "overlay", "popup"],
  "dialog": ["modal", "drawer", "sheet", "overlay"],
  "drawer": ["modal", "sheet", "dock", "overlay"],
  "pill": ["badge", "chip", "tag", "capsule"],
  "badge": ["pill", "chip", "tag", "status"],
  "dot": ["pulse", "status", "indicator", "pip"],
  "pulse": ["dot", "live", "animate-pulse"],
  "table": ["model", "schema", "entity", "database", "prisma", "drizzle"],
  "model": ["table", "schema", "entity", "prisma", "drizzle"],
  "api": ["route", "endpoint", "handler", "action", "server"],
  "action": ["server-action", "mutation", "handler", "api"],
  "button": ["btn", "trigger", "cta"],
};

export function expandSynonyms(tokens: string[]): string[] {
  const expanded = new Set<string>(tokens);
  for (const token of tokens) {
    const syns = FULLSTACK_SYNONYMS[token];
    if (syns) {
      for (const s of syns) expanded.add(s);
    }
  }
  return Array.from(expanded);
}

