import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  images: {
    remotePatterns: [
      {
        protocol: "https",
        hostname: "images.unsplash.com",
      },
      {
        protocol: "https",
        hostname: "lh3.googleusercontent.com",
      },
    ],
  },
  experimental: {
    serverActions: {
      bodySizeLimit: "12mb", // Allow larger uploads for payment proofs
    },
  },
};

export default nextConfig;
import { google } from "googleapis";

let _drive: ReturnType<typeof google.drive> | null = null;
let _tindahanProductImagesFolderId: string | null = null;

function getDriveClient() {
  if (_drive) return _drive;

  const email =
    process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
  const privateKey =
    process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;

  if (!email || !privateKey) {
    throw new Error(
      "Google Drive credentials not configured. Set GOOGLE_CLIENT_EMAIL and GOOGLE_PRIVATE_KEY in .env.local."
    );
  }

  const auth = new google.auth.GoogleAuth({
    credentials: {
      client_email: email,
      // Replace escaped \n with actual newlines
      private_key: privateKey.replace(/\\n/g, "\n"),
    },
    scopes: ["https://www.googleapis.com/auth/drive"],
  });

  _drive = google.drive({ version: "v3", auth });
  return _drive;
}

export interface UploadResult {
  fileId: string;
  webViewLink: string;
}

/**
 * Upload a payment proof image to Google Drive.
 * Returns the file ID stored in Neon.
 * The caller (server action) must have already validated file type + size.
 */
export async function uploadPaymentProof(
  buffer: Buffer,
  mimeType: string,
  filename: string
): Promise<UploadResult> {
  const drive = getDriveClient();
  const folderId = process.env.GOOGLE_DRIVE_FOLDER_ID;

  if (!folderId) {
    throw new Error("GOOGLE_DRIVE_FOLDER_ID environment variable is not set.");
  }

  const { Readable } = await import("stream");
  const stream = Readable.from(buffer);

  const response = await drive.files.create({
    requestBody: {
      name: filename,
      parents: [folderId],
      mimeType,
    },
    media: {
      mimeType,
      body: stream,
    },
    fields: "id,webViewLink",
  });

  const fileId = response.data.id;
  const webViewLink = response.data.webViewLink;

  if (!fileId) {
    throw new Error("Google Drive did not return a file ID.");
  }

  return { fileId, webViewLink: webViewLink ?? "" };
}

async function getTindahanProductImagesFolderId(): Promise<string> {
  if (_tindahanProductImagesFolderId) return _tindahanProductImagesFolderId;

  const drive = getDriveClient();
  const parentId = process.env.GOOGLE_DRIVE_FOLDER_ID;
  if (!parentId) throw new Error("GOOGLE_DRIVE_FOLDER_ID environment variable is not set.");

  const folderName = "Tindahan ni Tinapa Product Images";
  const existing = await drive.files.list({
    q: `'${parentId}' in parents and name = '${folderName}' and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
    fields: "files(id)",
    pageSize: 1,
  });
  const existingId = existing.data.files?.[0]?.id;
  if (existingId) {
    _tindahanProductImagesFolderId = existingId;
    return existingId;
  }

  const created = await drive.files.create({
    requestBody: {
      name: folderName,
      mimeType: "application/vnd.google-apps.folder",
      parents: [parentId],
    },
    fields: "id",
  });
  if (!created.data.id) throw new Error("Google Drive did not create the product image folder.");
  _tindahanProductImagesFolderId = created.data.id;
  return created.data.id;
}

export async function uploadTindahanProductImage(
  buffer: Buffer,
  mimeType: string,
  filename: string
): Promise<{ fileId: string }> {
  const drive = getDriveClient();
  const folderId = await getTindahanProductImagesFolderId();
  const { Readable } = await import("stream");
  const response = await drive.files.create({
    requestBody: { name: filename, parents: [folderId], mimeType },
    media: { mimeType, body: Readable.from(buffer) },
    fields: "id",
  });
  if (!response.data.id) throw new Error("Google Drive did not return a product image ID.");
  return { fileId: response.data.id };
}

export async function streamTindahanProductImage(
  fileId: string
): Promise<{ data: NodeJS.ReadableStream; mimeType: string }> {
  const drive = getDriveClient();
  const folderId = await getTindahanProductImagesFolderId();
  const meta = await drive.files.get({ fileId, fields: "mimeType,parents" });
  const mimeType = meta.data.mimeType ?? "";
  if (!meta.data.parents?.includes(folderId) || !["image/jpeg", "image/png", "image/webp"].includes(mimeType)) {
    throw new Error("Product image is not available.");
  }
  const response = await drive.files.get({ fileId, alt: "media" }, { responseType: "stream" });
  return { data: response.data as NodeJS.ReadableStream, mimeType };
}

/**
 * Stream a file from Google Drive back to an admin-only API route.
 * Never called from client-side code.
 */
export async function streamFileFromDrive(
  fileId: string
): Promise<{ data: NodeJS.ReadableStream; mimeType: string }> {
  const drive = getDriveClient();

  let targetId = fileId.trim();

  // If input looks like a filename (contains dot or extension or hyphenated UUID), query Drive by name
  if (targetId.includes(".") || targetId.includes("-")) {
    try {
      const sanitized = targetId.replace(/'/g, "\\'");
      const searchRes = await drive.files.list({
        q: `name = '${sanitized}' and trashed = false`,
        fields: "files(id, name, mimeType)",
        pageSize: 1,
      });
      if (searchRes.data.files && searchRes.data.files.length > 0 && searchRes.data.files[0].id) {
        targetId = searchRes.data.files[0].id;
      }
    } catch (searchErr) {
      console.warn("Drive filename search notice:", searchErr);
    }
  }

  try {
    // Get metadata first
    const meta = await drive.files.get({
      fileId: targetId,
      fields: "mimeType",
    });

    const mimeType = meta.data.mimeType ?? "application/octet-stream";

    const response = await drive.files.get(
      { fileId: targetId, alt: "media" },
      { responseType: "stream" }
    );

    return { data: response.data as NodeJS.ReadableStream, mimeType };
  } catch (err: any) {
    // If direct lookup by targetId failed and we hadn't searched by name yet, attempt name search fallback
    if (targetId === fileId) {
      try {
        const sanitized = fileId.replace(/'/g, "\\'");
        const fallbackRes = await drive.files.list({
          q: `name = '${sanitized}' and trashed = false`,
          fields: "files(id, name, mimeType)",
          pageSize: 1,
        });
        if (fallbackRes.data.files && fallbackRes.data.files.length > 0 && fallbackRes.data.files[0].id) {
          const resolvedId = fallbackRes.data.files[0].id;
          const meta = await drive.files.get({
            fileId: resolvedId,
            fields: "mimeType",
          });
          const mimeType = meta.data.mimeType ?? "application/octet-stream";
          const response = await drive.files.get(
            { fileId: resolvedId, alt: "media" },
            { responseType: "stream" }
          );
          return { data: response.data as NodeJS.ReadableStream, mimeType };
        }
      } catch (fallbackErr) {
        // ignore
      }
    }
    throw err;
  }
}

/**
 * Delete a file from Google Drive (e.g. on order deletion or re-upload).
 */
export async function deleteFileFromDrive(fileId: string): Promise<void> {
  const drive = getDriveClient();
  await drive.files.delete({ fileId });
}
"use server";

import { auth } from "@/auth";
import { db } from "@/lib/db";
import { categories, groupBuyBatches, products, orderShipments, orderEvents } from "@/lib/db/schema";
import { eq, desc, and } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { uploadTindahanProductImage } from "@/lib/google-drive/client";

const productImageExtensions: Record<string, string> = {
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/webp": "webp",
};
const maxProductImageBytes = 5 * 1024 * 1024;

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) throw new Error("Unauthorized");
}

function slug(value: string) {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "item";
}

function refresh() {
  revalidatePath("/admin/group-buy");
  revalidatePath("/api/products");
}

export async function createTindahanCategory(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  if (!name || name.length > 60) throw new Error("Category name must be 1 to 60 characters.");
  const base = `tindahan-${slug(name)}`;
  const found = await db.query.categories.findFirst({ where: eq(categories.id, base) });
  const id = found ? `${base}-${Date.now().toString(36)}` : base;
  const last = await db.query.categories.findFirst({ orderBy: [desc(categories.sortOrder)] });
  await db.insert(categories).values({
    id,
    storefrontKey: "tindahan",
    name,
    icon: String(formData.get("icon") || "📦").slice(0, 8),
    pill: String(formData.get("pill") || "").slice(0, 30),
    sortOrder: (last?.sortOrder ?? 0) + 1,
    isActive: true,
  });
  refresh();
}

export async function saveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "").trim();
  const categoryId = String(formData.get("categoryId") || "").trim();
  const fullName = String(formData.get("fullName") || "").trim();
  const name = String(formData.get("name") || "").trim() || fullName.slice(0, 100);
  const rawProductImage = formData.get("productImage");
  const productImage = rawProductImage instanceof File && rawProductImage.size > 0 ? rawProductImage : null;
  const kind = String(formData.get("kind") || "");
  const price = Number(formData.get("price"));
  const compareAt = String(formData.get("compareAtPrice") || "").trim();
  const stock = Number(formData.get("stock"));
  const manualImageUrl = String(formData.get("imageUrl") || "").trim().slice(0, 1000);
  if (productImage && (!productImageExtensions[productImage.type] || productImage.size > maxProductImageBytes)) {
    throw new Error("Choose a JPG, PNG, or WebP image under 5 MB.");
  }
  const category = await db.query.categories.findFirst({ where: eq(categories.id, categoryId) });
  if (!category || category.storefrontKey !== "tindahan") throw new Error("Choose a Tindahan ni Tinapa category.");
  if (!name || name.length > 100 || !fullName || fullName.length > 160) throw new Error("Product names are required and must fit their limits.");
  if (kind !== "on_hand" && kind !== "group_buy") throw new Error("Choose on-hand or group-buy stock.");
  if (!Number.isSafeInteger(price) || price < 0 || price > 2_000_000) throw new Error("Enter a valid price in pesos.");
  if (!Number.isSafeInteger(stock) || stock < 0 || stock > 1_000_000) throw new Error("Enter a valid stock count.");
  const compareAtPrice = compareAt ? Number(compareAt) : null;
  if (compareAtPrice !== null && (!Number.isSafeInteger(compareAtPrice) || compareAtPrice < price)) throw new Error("Original price must be a whole number at or above the sale price.");
  const batchRaw = String(formData.get("batchId") || "");
  const batchId = kind === "group_buy" ? Number(batchRaw) : null;
  if (kind === "group_buy") {
    const batch = Number.isInteger(batchId) ? await db.query.groupBuyBatches.findFirst({ where: eq(groupBuyBatches.id, batchId!) }) : null;
    if (!batch) throw new Error("Choose a group-buy batch.");
  }

  const existing = id ? await db.query.products.findFirst({ where: eq(products.id, id) }) : null;
  if (id && (!existing || existing.storefrontKey !== "tindahan")) throw new Error("Tindahan product not found.");

  let productId = id;
  if (!id) {
    const base = `tt_${slug(name).replace(/-/g, "_")}`;
    const found = await db.query.products.findFirst({ where: eq(products.id, base) });
    productId = found ? `${base}_${Date.now().toString(36)}` : base;
  }

  let imageUrl = manualImageUrl || null;
  if (!imageUrl && existing && formData.get("removeProductImage") !== "on") imageUrl = existing.imageUrl;
  if (productImage) {
    const extension = productImageExtensions[productImage.type];
    const uploaded = await uploadTindahanProductImage(
      Buffer.from(await productImage.arrayBuffer()),
      productImage.type,
      `${productId}-${Date.now()}.${extension}`
    );
    imageUrl = `drive:${uploaded.fileId}`;
  }

  if (id) {
    await db.update(products).set({
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: formData.get("isAvailable") === "on",
    }).where(eq(products.id, id));
  } else {
    const last = await db.query.products.findFirst({ where: eq(products.categoryId, categoryId), orderBy: [desc(products.sortOrder)] });
    await db.insert(products).values({
      id: productId,
      storefrontKey: "tindahan",
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: true,
      sortOrder: (last?.sortOrder ?? 0) + 1,
    });
  }
  refresh();
}

export async function archiveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "");
  await db.update(products).set({ isAvailable: false }).where(and(eq(products.id, id), eq(products.storefrontKey, "tindahan")));
  refresh();
}

export async function createTindahanBatch(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!name || name.length > 100 || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Enter a batch name and valid deadline and ETA.");
  }
  await db.insert(groupBuyBatches).values({ name, deadline, eta, status: deadline.getTime() > Date.now() ? "open" : "closed" });
  refresh();
}
import { and, eq } from "drizzle-orm";
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { products } from "@/lib/db/schema";
import { streamTindahanProductImage } from "@/lib/google-drive/client";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Cross-Origin-Resource-Policy": "cross-origin",
  "X-Content-Type-Options": "nosniff",
};

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ fileId: string }> }
) {
  const { fileId } = await params;
  if (!fileId || fileId.length > 256) {
    return new NextResponse(null, { status: 404, headers: corsHeaders });
  }

  const product = await db.query.products.findFirst({
    where: and(
      eq(products.storefrontKey, "tindahan"),
      eq(products.imageUrl, `drive:${fileId}`)
    ),
    columns: { id: true },
  });
  if (!product) return new NextResponse(null, { status: 404, headers: corsHeaders });

  try {
    const { data, mimeType } = await streamTindahanProductImage(fileId);
    const stream = new ReadableStream({
      start(controller) {
        data.on("data", (chunk) => controller.enqueue(chunk));
        data.on("end", () => controller.close());
        data.on("error", (error) => controller.error(error));
      },
    });

    return new NextResponse(stream, {
      headers: {
        ...corsHeaders,
        "Content-Type": mimeType,
        "Cache-Control": "public, max-age=86400, s-maxage=86400, stale-while-revalidate=604800",
      },
    });
  } catch (error) {
    console.warn("Tindahan product image could not be loaded:", error);
    return new NextResponse(null, { status: 404, headers: corsHeaders });
  }
}
"use client";

import { useEffect, useState } from "react";
import Image from "next/image";

interface TindahanProductImageInputProps {
  imageUrl?: string;
  allowRemove?: boolean;
}

export default function TindahanProductImageInput({
  imageUrl = "",
  allowRemove = false,
}: TindahanProductImageInputProps) {
  const [preview, setPreview] = useState(imageUrl);

  useEffect(() => {
    if (!preview.startsWith("blob:")) return;
    return () => URL.revokeObjectURL(preview);
  }, [preview]);

  return (
    <div className="grid gap-2">
      <input
        name="productImage"
        type="file"
        aria-label="Product photo"
        accept="image/jpeg,image/png,image/webp"
        className="neu-input rounded-xl px-3 py-2 text-sm file:mr-3 file:rounded-lg file:border-0 file:bg-[var(--color-accent)] file:px-3 file:py-1 file:font-semibold file:text-white"
        onChange={(event) => {
          const file = event.currentTarget.files?.[0];
          setPreview(file ? URL.createObjectURL(file) : imageUrl);
        }}
      />
      <p className="text-xs text-[var(--color-text-secondary)]">Choose a JPG, PNG, or WebP image. Maximum 5 MB.</p>
      {preview && <Image src={preview} alt="Product preview" width={112} height={112} unoptimized className="h-28 w-28 rounded-xl border border-black/10 object-cover" />}
      {allowRemove && (
        <label className="flex items-center gap-2 text-xs">
          <input type="checkbox" name="removeProductImage" />
          Remove current photo if no new photo is selected.
        </label>
      )}
    </div>
  );
}

tools.description:
Run JavaScript code to orchestrate/compose tool calls
- Evaluates the provided JavaScript code in a fresh V8 isolate as an async module.
- All nested tools are available on the global `tools` object, for example `await tools.exec_command(...)`. Tool names are exposed as normalized JavaScript identifiers, for example `await tools.mcp__ologs__get_profile(...)`.
- Nested tool methods take either a string or an object as their input argument.
- Nested tools return either an object or a string, based on the description.
- Runs raw JavaScript -- no Node, no file system, no network access, no console.
- Accepts raw JavaScript source text, not JSON, quoted strings, or markdown code fences.
- You may optionally start the tool input with a first-line pragma like `// @exec: {"yield_time_ms": 10000, "max_output_tokens": 1000}`.
- `yield_time_ms` asks `exec` to yield early if the script is still running. Defaults to 30000 ms.
- `max_output_tokens` sets the token budget for direct `exec` results. Defaults to 10000 tokens.
- When the JS code is fully evaluated, the isolate's lifetime ends and unawaited promises are silently discarded.

- Global helpers:
- `exit()`: Immediately ends the current script successfully (like an early return from the top level).
- `text(value: string | number | boolean | undefined | null)`: Appends a text item. Non-string values are stringified with `JSON.stringify(...)` when possible.
- `image(imageUrlOrItem: string | { image_url: string; detail?: "auto" | "low" | "high" | "original" | null } | ImageContent, detail?: "auto" | "low" | "high" | "original" | null)`: Appends an image item. `image_url` should be a base64-encoded `data:` URL. To forward an MCP tool image, pass an individual `ImageContent` block from `result.content`, for example `image(result.content[0])`. MCP image blocks may request detail with `_meta: { "codex/imageDetail": "original" }`. When provided, the second `detail` argument overrides any detail embedded in the first argument.
- `audio(audioUrlOrItem: string | { audio_url: string } | AudioContent)`: Appends an audio item. `audio_url` should be a base64-encoded `data:` URL. To forward an MCP tool audio block, pass an individual `AudioContent` block from `result.content`, for example `audio(result.content[0])`.
- `generatedImage(result: { image_url: string; output_hint?: string })`: Appends an image-generation result and its optional output hint. HTTP(S) URLs are not supported.
- `store(key: string, value: any)`: stores a serializable value under a string key for later `exec` calls in the same session.
- `load(key: string)`: returns the stored value for a string key, or `undefined` if it is missing.
- `notify(value: string | number | boolean | undefined | null)`: immediately injects an extra `custom_tool_call_output` for the current `exec` call. Values are stringified like `text(...)`.
- `setTimeout(callback: () => void, delayMs?: number)`: schedules a callback to run later and returns a timeout id. Pending timeouts do not keep `exec` alive by themselves; await an explicit promise if you need to wait for one.
- `clearTimeout(timeoutId?: number)`: cancels a timeout created by `setTimeout`.
- `ALL_TOOLS`: metadata for the enabled nested tools as `{ name, description }` entries.
- `yield_control()`: yields the accumulated output to the model immediately while the script keeps running.

Some deferred nested tools may be omitted from this description. They are still available on the global `tools` object and listed in `ALL_TOOLS`.
To find one, filter `ALL_TOOLS` by `name` and `description`.

Tool availability can change between calls.

Shared MCP Types:
```ts
type Role = "user" | "assistant";
type MetaObject = Record<string, unknown>;
type Annotations = {
  audience?: Role[];
  priority?: number;
  lastModified?: string;
};
type Icon = {
  src: string;
  mimeType?: string;
  sizes?: string[];
  theme?: "light" | "dark";
};
type TextResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  text: string;
};
type BlobResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  blob: string;
};
type TextContent = {
  type: "text";
  text: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ImageContent = {
  type: "image";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type AudioContent = {
  type: "audio";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ResourceLink = {
  icons?: Icon[];
  name: string;
  title?: string;
  uri: string;
  description?: string;
  mimeType?: string;
  annotations?: Annotations;
  size?: number;
  _meta?: MetaObject;
  type: "resource_link";
};
type EmbeddedResource = {
  type: "resource";
  resource: TextResourceContents | BlobResourceContents;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ContentBlock =
  | TextContent
  | ImageContent
  | AudioContent
  | ResourceLink
  | EmbeddedResource;
type CallToolResult<TStructured = { [key: string]: unknown }> = {
  _meta?: MetaObject;
  content: ContentBlock[];
  isError?: boolean;
  structuredContent?: TStructured;
  [key: string]: unknown;
};
```

