"use client";

import { useEffect, useState } from "react";
import Image from "next/image";

interface TindahanProductImageInputProps {
  imageUrl?: string;
  allowRemove?: boolean;
}

export default function TindahanProductImageInput({
  imageUrl = "",
  allowRemove = false,
}: TindahanProductImageInputProps) {
  const [preview, setPreview] = useState(imageUrl);

  useEffect(() => {
    if (!preview.startsWith("blob:")) return;
    return () => URL.revokeObjectURL(preview);
  }, [preview]);

  return (
    <div className="grid gap-2">
      <input
        name="productImage"
        type="file"
        aria-label="Product photo"
        accept="image/jpeg,image/png,image/webp"
        className="neu-input rounded-xl px-3 py-2 text-sm file:mr-3 file:rounded-lg file:border-0 file:bg-[var(--color-accent)] file:px-3 file:py-1 file:font-semibold file:text-white"
        onChange={(event) => {
          const file = event.currentTarget.files?.[0];
          setPreview(file ? URL.createObjectURL(file) : imageUrl);
        }}
      />
      <p className="text-xs text-[var(--color-text-secondary)]">Choose a JPG, PNG, or WebP image. Maximum 5 MB.</p>
      {preview && <Image src={preview} alt="Product preview" width={112} height={112} unoptimized className="h-28 w-28 rounded-xl border border-black/10 object-cover" />}
      {allowRemove && (
        <label className="flex items-center gap-2 text-xs">
          <input type="checkbox" name="removeProductImage" />
          Remove current photo if no new photo is selected.
        </label>
      )}
    </div>
  );
}

