import { and, eq } from "drizzle-orm";
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { products } from "@/lib/db/schema";
import { streamTindahanProductImage } from "@/lib/google-drive/client";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Cross-Origin-Resource-Policy": "cross-origin",
  "X-Content-Type-Options": "nosniff",
};

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ fileId: string }> }
) {
  const { fileId } = await params;
  if (!fileId || fileId.length > 256) {
    return new NextResponse(null, { status: 404, headers: corsHeaders });
  }

  const product = await db.query.products.findFirst({
    where: and(
      eq(products.storefrontKey, "tindahan"),
      eq(products.imageUrl, `drive:${fileId}`)
    ),
    columns: { id: true },
  });
  if (!product) return new NextResponse(null, { status: 404, headers: corsHeaders });

  try {
    const { data, mimeType } = await streamTindahanProductImage(fileId);
    const stream = new ReadableStream({
      start(controller) {
        data.on("data", (chunk) => controller.enqueue(chunk));
        data.on("end", () => controller.close());
        data.on("error", (error) => controller.error(error));
      },
    });

    return new NextResponse(stream, {
      headers: {
        ...corsHeaders,
        "Content-Type": mimeType,
        "Cache-Control": "public, max-age=86400, s-maxage=86400, stale-while-revalidate=604800",
      },
    });
  } catch (error) {
    console.warn("Tindahan product image could not be loaded:", error);
    return new NextResponse(null, { status: 404, headers: corsHeaders });
  }
}

