  tools.mcp__codex_apps__github_fetch_file({repository_full_name:"AK-Lmn/admin-pbc",path:"package.json",ref:"main"}),
  tools.mcp__codex_apps__github_fetch_file({repository_full_name:"AK-Lmn/admin-pbc",path:"package-lock.json",ref:"main"})
]);
function short(v) { return v?.structuredContent?.content ?? v?.content?.map?.(x=>x.text).join("\n") ?? v; }
