const finalFiles=load("gb-blob-final-files");
const [refResult,commitResult]=await Promise.all([
 tools.mcp__codex_apps__github_fetch({url:"https://api.github.com/repos/AK-Lmn/admin-pbc/git/ref/heads/main"}),
 tools.mcp__codex_apps__github_fetch_commit({repo_full_name:"AK-Lmn/admin-pbc",commit_sha:"c3d935b0258dcf561c2c59cd2f7813d0fae61c39"})
]);
const refJson=JSON.parse(refResult.structuredContent.content);
const commit=commitResult.structuredContent;
const action=finalFiles["lib/actions/group-buy.ts"];
const aLines=action.split("\n");
const relevant=aLines.filter((line,i)=>i<14||line.includes("maxProductImageBytes")||line.includes("under 4 MB")||line.includes("await put(")||line.includes("access: \"public\"")||line.includes("addRandomSuffix: true")||line.includes("imageUrl = uploaded.url"));
const lock=JSON.parse(finalFiles["package-lock.json"]);
text("main="+refJson.object.sha+" tree="+(commit?.tree?.sha??commit?.commit?.tree?.sha??"unknown"));
text("changed paths="+Object.keys(finalFiles).join(", "));
text("upload changes:\n"+relevant.join("\n"));
text("component: "+finalFiles["components/products/tindahan-product-image-input.tsx"].split("\n").find(x=>x.includes("Maximum")));
text("admin photo url field: "+finalFiles["app/admin/group-buy/page.tsx"].split("\n").find(x=>x.includes("Leave blank to keep current photo")));
text("package dependency: "+JSON.stringify(JSON.parse(finalFiles["package.json"]).dependencies["@vercel/blob"]));
text("lock Blob entries: "+Object.keys(lock.packages).filter(k=>k.includes("@vercel")||k==="node_modules/async-retry"||k==="node_modules/undici").join(", "));
text("lock path count="+Object.keys(lock.packages).length+" size="+finalFiles["package-lock.json"].length);

