  if (!name || name.length > 100 || !fullName || fullName.length > 160) throw new Error("Product names are required and must fit their limits.");
  if (kind !== "on_hand" && kind !== "group_buy") throw new Error("Choose on-hand or group-buy stock.");
  if (!Number.isSafeInteger(price) || price < 0 || price > 2_000_000) throw new Error("Enter a valid price in pesos.");
  if (!Number.isSafeInteger(stock) || stock < 0 || stock > 1_000_000) throw new Error("Enter a valid stock count.");
  const compareAtPrice = compareAt ? Number(compareAt) : null;
  if (compareAtPrice !== null && (!Number.isSafeInteger(compareAtPrice) || compareAtPrice < price)) throw new Error("Original price must be a whole number at or above the sale price.");
  const batchRaw = String(formData.get("batchId") || "");
  const batchId = kind === "group_buy" ? Number(batchRaw) : null;
  if (kind === "group_buy") {
    const batch = Number.isInteger(batchId) ? await db.query.groupBuyBatches.findFirst({ where: eq(groupBuyBatches.id, batchId!) }) : null;
    if (!batch) throw new Error("Choose a group-buy batch.");
  }

  const existing = id ? await db.query.products.findFirst({ where: eq(products.id, id) }) : null;
  if (id && (!existing || existing.storefrontKey !== "tindahan")) throw new Error("Tindahan product not found.");

  let productId = id;
  if (!id) {
    const base = `tt_${slug(name).replace(/-/g, "_")}`;
    const found = await db.query.products.findFirst({ where: eq(products.id, base) });
    productId = found ? `${base}_${Date.now().toString(36)}` : base;
  }

  let imageUrl = manualImageUrl || null;
  if (!imageUrl && existing && formData.get("removeProductImage") !== "on") imageUrl = existing.imageUrl;
  if (productImage) {
    const extension = productImageExtensions[productImage.type];
    const uploaded = await put(`tindahan/products/${productId}-${Date.now()}.${extension}`, productImage, {
      access: "public",
      addRandomSuffix: true,
      contentType: productImage.type,
    });
    imageUrl = uploaded.url;
  }

  if (id) {
    await db.update(products).set({
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: formData.get("isAvailable") === "on",
    }).where(eq(products.id, id));
  } else {
    const last = await db.query.products.findFirst({ where: eq(products.categoryId, categoryId), orderBy: [desc(products.sortOrder)] });
    await db.insert(products).values({
      id: productId,
      storefrontKey: "tindahan",
      categoryId,
      name,
      fullName,
      kind,
      batchId,
      price,
      compareAtPrice,
      description: String(formData.get("description") || "").trim().slice(0, 500) || null,
      imageUrl,
      emoji: String(formData.get("emoji") || "📦").slice(0, 8),
      stock: kind === "on_hand" ? stock : 0,
      isAvailable: true,
      sortOrder: (last?.sortOrder ?? 0) + 1,
    });
  }
  refresh();
}

export async function archiveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "");
  await db.update(products).set({ isAvailable: false }).where(and(eq(products.id, id), eq(products.storefrontKey, "tindahan")));
  refresh();
}

export async function createTindahanBatch(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!name || name.length > 100 || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Enter a batch name and valid deadline and ETA.");
  }
  await db.insert(groupBuyBatches).values({ name, deadline, eta, status: deadline.getTime() > Date.now() ? "open" : "closed" });
  refresh();
}

export async function updateTindahanBatch(formData: FormData) {
  await requireAdmin();
  const id = Number(formData.get("id"));
  const name = String(formData.get("name") || "").trim();
  const status = String(formData.get("status") || "");
  const deadline = new Date(String(formData.get("deadline") || ""));
  const etaRaw = String(formData.get("eta") || "");
  const eta = etaRaw ? new Date(etaRaw) : null;
  if (!Number.isInteger(id) || !name || name.length > 100 || !["open", "closed", "ordered", "arrived"].includes(status) || Number.isNaN(deadline.getTime()) || (eta && Number.isNaN(eta.getTime()))) {
    throw new Error("Invalid batch update.");
  }
  await db.update(groupBuyBatches).set({ name, status: status as "open" | "closed" | "ordered" | "arrived", deadline, eta, updatedAt: new Date() }).where(eq(groupBuyBatches.id, id));
  refresh();
}

export async function updateTindahanShipment(formData: FormData) {
  await requireAdmin();
  const id = Number(formData.get("id"));
  const status = String(formData.get("status") || "");
  if (!Number.isInteger(id) || !["processing", "ready_to_ship", "shipped", "completed"].includes(status)) {
    throw new Error("Invalid shipment update.");
  }
  const shipment = await db.query.orderShipments.findFirst({
    where: eq(orderShipments.id, id),
    with: { order: true },
  });
  if (!shipment || shipment.order.storefrontKey !== "tindahan") throw new Error("Tindahan shipment not found.");
  await db.update(orderShipments).set({ status: status as "processing" | "ready_to_ship" | "shipped" | "completed", updatedAt: new Date() }).where(eq(orderShipments.id, id));
  await db.insert(orderEvents).values({
    orderId: shipment.orderId,
    eventType: `shipment_${status}`,
    description: `Shipment ${id} updated to ${status.replaceAll("_", " ")}.`,
  });
  revalidatePath("/admin/group-buy/orders");
  revalidatePath(`/admin/orders/${shipment.orderId}`);
}

"use client";

import { useEffect, useState } from "react";
import Image from "next/image";

interface TindahanProductImageInputProps {
  imageUrl?: string;
  allowRemove?: boolean;
}

export default function TindahanProductImageInput({
  imageUrl = "",
  allowRemove = false,
}: TindahanProductImageInputProps) {
  const [preview, setPreview] = useState(imageUrl);

  useEffect(() => {
    if (!preview.startsWith("blob:")) return;
    return () => URL.revokeObjectURL(preview);
  }, [preview]);

  return (
    <div className="grid gap-2">
      <input
        name="productImage"
        type="file"
        aria-label="Product photo"
        accept="image/jpeg,image/png,image/webp"
        className="neu-input rounded-xl px-3 py-2 text-sm file:mr-3 file:rounded-lg file:border-0 file:bg-[var(--color-accent)] file:px-3 file:py-1 file:font-semibold file:text-white"
        onChange={(event) => {
          const file = event.currentTarget.files?.[0];
          setPreview(file ? URL.createObjectURL(file) : imageUrl);
        }}
      />
      <p className="text-xs text-[var(--color-text-secondary)]">Choose a JPG, PNG, or WebP image. Maximum 4 MB.</p>
      {preview && <Image src={preview} alt="Product preview" width={112} height={112} unoptimized className="h-28 w-28 rounded-xl border border-black/10 object-cover" />}
      {allowRemove && (
        <label className="flex items-center gap-2 text-xs">
          <input type="checkbox" name="removeProductImage" />
          Remove current photo if no new photo is selected.
        </label>
      )}
    </div>
  );
}

