+"use client";
+
+import { useTransition, type FormEvent, type ReactNode } from "react";
+import { toast } from "sonner";
+
+type TindahanFormAction = (formData: FormData) => Promise<void>;
+
+interface TindahanActionFormProps {
+  action: TindahanFormAction;
+  children: ReactNode;
+  className?: string;
+  resetOnSuccess?: boolean;
+  successMessage: string;
+}
+
+export default function TindahanActionForm({
+  action,
+  children,
+  className,
+  resetOnSuccess = false,
+  successMessage,
+}: TindahanActionFormProps) {
+  const [isPending, startTransition] = useTransition();
+
+  function handleSubmit(event: FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    if (isPending) return;
+
+    const form = event.currentTarget;
+    const formData = new FormData(form);
+
+    startTransition(async () => {
+      try {
+        await action(formData);
+        toast.success(successMessage);
+        if (resetOnSuccess) form.reset();
+      } catch (error) {
+        toast.error(
+          error instanceof Error && error.message
+            ? error.message
+            : "Couldn't save changes. Please try again.",
+        );
+      }
+    });
+  }
+
+  return (
+    <form className={className} onSubmit={handleSubmit} aria-busy={isPending}>
+      <fieldset disabled={isPending} className="contents">
+        {children}
+      </fieldset>
+    </form>
+  );
+}

