let _drive: ReturnType<typeof google.drive> | null = null;
let _tindahanProductImagesFolderId: string | null = null;

function getDriveClient() {
  if (_drive) return _drive;

  const email =
    process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
  const privateKey =
    process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;

  if (!email || !privateKey) {
    throw new Error(
      "Google Drive credentials not configured. Set GOOGLE_CLIENT_EMAIL and GOOGLE_PRIVATE_KEY in .env.local."
    );
  }

  const auth = new google.auth.GoogleAuth({
    credentials: {
      client_email: email,
      // Replace escaped \n with actual newlines
      private_key: privateKey.replace(/\\n/g, "\n"),
    },
    scopes: ["https://www.googleapis.com/auth/drive"],
  });

  _drive = google.drive({ version: "v3", auth });
  return _drive;
}

export interface UploadResult {
  fileId: string;
  webViewLink: string;
}

/**
 * Upload a payment proof image to Google Drive.
 * Returns the file ID stored in Neon.
 * The caller (server action) must have already validated file type + size.
 */
export async function uploadPaymentProof(
  buffer: Buffer,
  mimeType: string,
  filename: string
): Promise<UploadResult> {
  const drive = getDriveClient();
  const folderId = process.env.GOOGLE_DRIVE_FOLDER_ID;

  if (!folderId) {
    throw new Error("GOOGLE_DRIVE_FOLDER_ID environment variable is not set.");
  }

  const { Readable } = await import("stream");
  const stream = Readable.from(buffer);

  const response = await drive.files.create({
    requestBody: {
      name: filename,
      parents: [folderId],
      mimeType,
    },
    media: {
      mimeType,
      body: stream,
    },
    fields: "id,webViewLink",
  });

  const fileId = response.data.id;
  const webViewLink = response.data.webViewLink;

  if (!fileId) {
    throw new Error("Google Drive did not return a file ID.");
  }

  return { fileId, webViewLink: webViewLink ?? "" };
}

async function getTindahanProductImagesFolderId(): Promise<string> {
  if (_tindahanProductImagesFolderId) return _tindahanProductImagesFolderId;

  const drive = getDriveClient();
  const parentId = process.env.GOOGLE_DRIVE_FOLDER_ID;
  if (!parentId) throw new Error("GOOGLE_DRIVE_FOLDER_ID environment variable is not set.");

  const folderName = "Tindahan ni Tinapa Product Images";
  const existing = await drive.files.list({
    q: `'${parentId}' in parents and name = '${folderName}' and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
    fields: "files(id)",
    pageSize: 1,
  });
  const existingId = existing.data.files?.[0]?.id;
  if (existingId) {
    _tindahanProductImagesFolderId = existingId;
    return existingId;
  }

  const created = await drive.files.create({
    requestBody: {
      name: folderName,
      mimeType: "application/vnd.google-apps.folder",
      parents: [parentId],
    },
    fields: "id",
  });
  if (!created.data.id) throw new Error("Google Drive did not create the product image folder.");
  _tindahanProductImagesFolderId = created.data.id;
  return created.data.id;
}

export async function uploadTindahanProductImage(
  buffer: Buffer,
  mimeType: string,
  filename: string
): Promise<{ fileId: string }> {
  const drive = getDriveClient();
  const folderId = await getTindahanProductImagesFolderId();
  const { Readable } = await import("stream");
  const response = await drive.files.create({
    requestBody: { name: filename, parents: [folderId], mimeType },
    media: { mimeType, body: Readable.from(buffer) },
    fields: "id",
  });
  if (!response.data.id) throw new Error("Google Drive did not return a product image ID.");
  return { fileId: response.data.id };
}

export async function streamTindahanProductImage(
  fileId: string
): Promise<{ data: NodeJS.ReadableStream; mimeType: string }> {
  const drive = getDriveClient();
  const folderId = await getTindahanProductImagesFolderId();
  const meta = await drive.files.get({ fileId, fields: "mimeType,parents" });
  const mimeType = meta.data.mimeType ?? "";
  if (!meta.data.parents?.includes(folderId) || !["image/jpeg", "image/png", "image/webp"].includes(mimeType)) {
    throw new Error("Product image is not available.");
  }
  const response = await drive.files.get({ fileId, alt: "media" }, { responseType: "stream" });
  return { data: response.data as NodeJS.ReadableStream, mimeType };
}

/**
 * Stream a file from Google Drive back to an admin-only API route.
 * Never called from client-side code.
 */
export async function streamFileFromDrive(
  fileId: string
): Promise<{ data: NodeJS.ReadableStream; mimeType: string }> {
  const drive = getDriveClient();

  let targetId = fileId.trim();

  // If input looks like a filename (contains dot or extension or hyphenated UUID), query Drive by name
  if (targetId.includes(".") || targetId.includes("-")) {
    try {
      const sanitized = targetId.replace(/'/g, "\\'");
      const searchRes = await drive.files.list({
        q: `name = '${sanitized}' and trashed = false`,
        fields: "files(id, name, mimeType)",
        pageSize: 1,
      });
      if (searchRes.data.files && searchRes.data.files.length > 0 && searchRes.data.files[0].id) {
        targetId = searchRes.data.files[0].id;
      }
    } catch (searchErr) {
      console.warn("Drive filename search notice:", searchErr);
    }
  }

  try {
    // Get metadata first
    const meta = await drive.files.get({
      fileId: targetId,
      fields: "mimeType",
    });

    const mimeType = meta.data.mimeType ?? "application/octet-stream";

    const response = await drive.files.get(
      { fileId: targetId, alt: "media" },
      { responseType: "stream" }
    );

    return { data: response.data as NodeJS.ReadableStream, mimeType };
  } catch (err: any) {
    // If direct lookup by targetId failed and we hadn't searched by name yet, attempt name search fallback
    if (targetId === fileId) {
      try {
        const sanitized = fileId.replace(/'/g, "\\'");
        const fallbackRes = await drive.files.list({
          q: `name = '${sanitized}' and trashed = false`,
          fields: "files(id, name, mimeType)",
