// Proxy endpoint to stream payment proof images directly from Google Drive
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ fileId: string }> }
) {
  const { fileId } = await params;

  if (!fileId || fileId.trim() === "" || fileId === "null" || fileId === "undefined") {
    return new NextResponse(generateFallbackSvg("N/A"), {
      status: 200,
      headers: { "Content-Type": "image/svg+xml" },
    });
  }

  try {
    const { data, mimeType } = await streamFileFromDrive(fileId);

    const stream = new ReadableStream({
      start(controller) {
        (data as NodeJS.ReadableStream).on("data", (chunk) => {
          controller.enqueue(chunk);
        });
        (data as NodeJS.ReadableStream).on("end", () => {
          controller.close();
        });
        (data as NodeJS.ReadableStream).on("error", (err) => {
          controller.error(err);
        });
      },
    });

    return new NextResponse(stream, {
      headers: {
        "Content-Type": mimeType,
        "Cache-Control": "public, max-age=86400, s-maxage=86400, stale-while-revalidate=604800",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch (error: any) {
    console.warn("Drive payment proof proxy notice for fileId", fileId, error.message || error);
    
    // Serve clean SVG fallback image on 404 or Drive stream errors instead of broken image icons
    return new NextResponse(generateFallbackSvg(fileId), {
      status: 200,
      headers: {
        "Content-Type": "image/svg+xml",
        "Cache-Control": "no-store",
      },
    });
  }
}
