const stateCookie = "tindahan-drive-oauth-state";

export async function GET(request: NextRequest) {
  if (!(await isTindahanDriveAdmin())) return NextResponse.redirect(new URL("/admin/login", request.url));
  try {
    const state = randomBytes(32).toString("base64url");
    const callbackUrl = new URL("/api/admin/google-drive/callback", process.env.AUTH_URL || process.env.NEXT_PUBLIC_APP_URL || request.nextUrl.origin).toString();
