import { NextRequest, NextResponse } from "next/server";
import { streamFileFromDrive } from "@/lib/google-drive/client";

function generateFallbackSvg(fileId: string): string {
  const cleanId = (fileId || "N/A").trim().slice(0, 32);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="460" height="300" viewBox="0 0 460 300" fill="none">
    <rect width="460" height="300" rx="16" fill="#FDF8F6"/>
    <rect x="1.5" y="1.5" width="457" height="297" rx="14.5" stroke="#F3E8E2" stroke-width="2"/>
    
    <!-- Icon Circle -->
    <circle cx="230" cy="65" r="30" fill="#FCE7F3"/>
    <circle cx="230" cy="65" r="22" fill="#FBCFE8"/>
    <!-- Receipt Icon -->
    <path d="M220 54h20c1.6 0 3 1.4 3 3v20l-3.5-1.5-3 1.5-3.5-1.5-3 1.5-3.5-1.5-3.5 1.5V57c0-1.6 1.4-3 3-3z" fill="#DB2777" opacity="0.9"/>
    <path d="M224 61h12M224 66h8M224 71h10" stroke="#FFF" stroke-width="1.8" stroke-linecap="round"/>

    <!-- Main Title -->
    <text x="230" y="125" text-anchor="middle" fill="#1F2937" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="16" font-weight="700">Receipt Not Synced to Drive</text>
    <text x="230" y="147" text-anchor="middle" fill="#6B7280" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="12">The customer placed this order, but the image proof wasn't stored.</text>

    <!-- Guide Box -->
    <rect x="40" y="168" width="380" height="68" rx="10" fill="#FFFFFF" stroke="#E5E7EB" stroke-width="1"/>
    <text x="56" y="190" fill="#374151" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="11.5" font-weight="600">Verification Steps:</text>
    <text x="56" y="208" fill="#4B5563" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="11">• Check GCash / GoTyme for matching name or amount</text>
    <text x="56" y="224" fill="#4B5563" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="11">• Or reach out to customer to confirm payment reference</text>

    <!-- Reference Tag -->
    <text x="230" y="268" text-anchor="middle" fill="#9CA3AF" font-family="monospace" font-size="10.5">Reference: ${cleanId}</text>
  </svg>`;
}

// Proxy endpoint to stream payment proof images directly from Google Drive
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ fileId: string }> }
) {
  const { fileId } = await params;

  if (!fileId || fileId.trim() === "" || fileId === "null" || fileId === "undefined") {
    return new NextResponse(generateFallbackSvg("N/A"), {
      status: 200,
      headers: { "Content-Type": "image/svg+xml" },
    });
  }

  try {
    const { data, mimeType } = await streamFileFromDrive(fileId);

    const stream = new ReadableStream({
      start(controller) {
        (data as NodeJS.ReadableStream).on("data", (chunk) => {
          controller.enqueue(chunk);
        });
        (data as NodeJS.ReadableStream).on("end", () => {
          controller.close();
        });
        (data as NodeJS.ReadableStream).on("error", (err) => {
          controller.error(err);
        });
      },
    });

    return new NextResponse(stream, {
      headers: {
        "Content-Type": mimeType,
        "Cache-Control": "public, max-age=86400, s-maxage=86400, stale-while-revalidate=604800",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch (error: any) {
    console.warn("Drive payment proof proxy notice for fileId", fileId, error.message || error);
    
    // Serve clean SVG fallback image on 404 or Drive stream errors instead of broken image icons
    return new NextResponse(generateFallbackSvg(fileId), {
      status: 200,
      headers: {
        "Content-Type": "image/svg+xml",
        "Cache-Control": "no-store",
      },
    });
  }
}
