"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

type PickerView = {
  setIncludeFolders: (include: boolean) => PickerView;
  setSelectFolderEnabled: (enabled: boolean) => PickerView;
};
type PickerResult = { action?: string; docs?: Array<{ id?: string; name?: string }> };
type PickerBuilder = {
  addView: (view: PickerView) => PickerBuilder;
  setOAuthToken: (token: string) => PickerBuilder;
  setDeveloperKey: (key: string) => PickerBuilder;
  setAppId: (id: string) => PickerBuilder;
  setCallback: (callback: (result: PickerResult) => void) => PickerBuilder;
  build: () => { setVisible: (visible: boolean) => void };
};
type PickerApi = {
  PickerBuilder: new () => PickerBuilder;
  DocsView: new (viewId?: string) => PickerView;
  ViewId: { FOLDERS: string };
  Action: { PICKED: string };
};
declare global {
  interface Window {
    gapi?: { load: (api: string, callback: () => void) => void };
    google?: { picker?: PickerApi };
  }
}

type Props = {
  connected: boolean;
  canManageDrive: boolean;
  folderName: string | null;
  oauthConfigured: boolean;
  pickerApiKey: string;
  pickerAppId: string;
  notice: string | null;
};

const noticeText: Record<string, string> = {
  connected: "Google Drive connected. Now choose the receipt folder.",
  setup: "Google OAuth is not configured yet. Add its credentials to admin-pbc on Vercel.",
  cancelled: "Google Drive was not connected. You can try again.",
  error: "Google Drive could not connect. Check the setup and try again.",
  unauthorized: "Sign in as an admin, then connect Google Drive again.",
  "folder-saved": "Receipt folder saved.",
};

export function TindahanDriveSetup({ connected, canManageDrive, folderName, oauthConfigured, pickerApiKey, pickerAppId, notice }: Props) {
  const router = useRouter();
  const [pickerReady, setPickerReady] = useState(false);
  const [busy, setBusy] = useState(false);
  const initialMessage = notice === "connected" && folderName ? "Google Drive reconnected." : notice ? noticeText[notice] ?? "" : "";
  const [message, setMessage] = useState(initialMessage);

  useEffect(() => {
    let mounted = true;
    const loadPicker = () => window.gapi?.load("picker", () => mounted && setPickerReady(true));
    const existing = document.querySelector<HTMLScriptElement>("script[data-tindahan-picker]");
    if (existing) {
      if (window.gapi) loadPicker();
      else existing.addEventListener("load", loadPicker, { once: true });
    } else {
      const script = document.createElement("script");
      script.src = "https://apis.google.com/js/api.js";
      script.async = true;
      script.dataset.tindahanPicker = "true";
      script.onload = loadPicker;
      script.onerror = () => mounted && setMessage("Google Drive folder picker did not load. Refresh the page and try again.");
      document.head.appendChild(script);
    }
    return () => { mounted = false; };
  }, []);

  async function chooseFolder() {
    if (!pickerReady || !pickerApiKey || !pickerAppId) return;
    setBusy(true);
    setMessage("");
    try {
      const tokenResponse = await fetch("/api/admin/google-drive/access-token", { cache: "no-store" });
      const tokenBody = await tokenResponse.json() as { accessToken?: string; error?: string };
      if (!tokenResponse.ok || !tokenBody.accessToken) throw new Error(tokenBody.error || "Could not open Google Drive.");
      const picker = window.google?.picker;
      if (!picker) throw new Error("Google Drive folder picker is still loading.");
      const folderView = new picker.DocsView(picker.ViewId.FOLDERS).setIncludeFolders(true).setSelectFolderEnabled(true);
      new picker.PickerBuilder()
        .addView(folderView)
        .setOAuthToken(tokenBody.accessToken)
        .setDeveloperKey(pickerApiKey)
        .setAppId(pickerAppId)
        .setCallback(async (result) => {
          if (result.action !== picker.Action.PICKED) return;
          const folderId = result.docs?.[0]?.id;
          if (!folderId) { setMessage("Choose a folder, then try again."); return; }
          setBusy(true);
          try {
            const response = await fetch("/api/admin/google-drive/folder", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ folderId }),
            });
            const body = await response.json() as { folderName?: string; error?: string };
            if (!response.ok || !body.folderName) throw new Error(body.error || "Could not save that folder.");
            router.push("/admin/settings?drive=folder-saved");
          } catch (error) {
            setMessage(error instanceof Error ? error.message : "Could not save that folder.");
          } finally {
            setBusy(false);
          }
        })
        .build()
        .setVisible(true);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not open Google Drive.");
    } finally {
      setBusy(false);
    }
  }

  const pickerConfigured = Boolean(pickerApiKey && pickerAppId);
  return (
    <section id="group-buy-drive" className="neu-card p-4 md:p-5 space-y-3">
      <div>
        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">Group-buy receipt folder</h2>
        <p className="mt-1 text-sm text-[var(--color-text-secondary)]">Connect Google Drive, then choose the Tindahan ni Tinapa Group Buy Receipts folder.</p>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        {!canManageDrive ? (
          <span className="text-sm text-[var(--color-text-secondary)]">Ask an admin to manage this Drive connection.</span>
        ) : !connected ? (
          oauthConfigured ? (
            <a href="/api/admin/google-drive/connect" className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold">Connect Google Drive</a>
          ) : <span className="text-sm text-[var(--color-text-secondary)]">Google Drive setup needed.</span>
        ) : (
          <>
            <button type="button" onClick={chooseFolder} disabled={busy || !pickerReady || !pickerConfigured} className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold disabled:opacity-50">
              {busy ? "Opening Drive…" : folderName ? "Change receipt folder" : "Choose receipt folder"}
            </button>
            {oauthConfigured && <a href="/api/admin/google-drive/connect" className="text-sm font-semibold underline">Reconnect Google Drive</a>}
          </>
        )}
        <span className="text-sm text-[var(--color-text-secondary)]">
          {connected ? folderName ? `Saving receipts to ${folderName}` : "Drive connected; choose a receipt folder." : "PBC's existing receipt uploads stay unchanged."}
        </span>
      </div>
      {connected && !pickerConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set NEXT_PUBLIC_GOOGLE_PICKER_API_KEY and NEXT_PUBLIC_GOOGLE_PICKER_APP_ID in Vercel to choose a folder.</p>}
      {!oauthConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set GOOGLE_OAUTH_CLIENT_ID and GOOGLE_OAUTH_CLIENT_SECRET in Vercel before connecting.</p>}
      {message && <p role="status" className="text-sm text-[var(--color-text-secondary)]">{message}</p>}
    </section>
  );
}

