  if (!fileId || fileId.trim() === "" || fileId === "null" || fileId === "undefined") {
    return new NextResponse(generateFallbackSvg("N/A"), {
      status: 200,
      headers: { "Content-Type": "image/svg+xml" },
    });
  }

  try {
    const order = await db.query.orders.findFirst({
      where: eq(orders.paymentProofFileId, fileId),
      columns: { storefrontKey: true },
    });

    const isTindahanReceipt = order?.storefrontKey === "tindahan";
