function doPost(e) {
  try {
    var data = {};

    var contentType = (e.postData && e.postData.type) ? e.postData.type : '';
    var contents    = (e.postData && e.postData.contents) ? e.postData.contents : '';

    if (contentType.indexOf('application/json') === 0 || contentType.indexOf('text/plain') === 0) {
      try {
        data = JSON.parse(contents);
      } catch (parseErr) {
        data = {};
      }
    } else {
      data = {
        name:      e.parameter.name      || '',
        contact:   e.parameter.contact   || '',
        address:   e.parameter.address   || '',
        items:     e.parameter.items     || '',
        total:     e.parameter.total     || '',
        notes:     e.parameter.notes     || '',
