let _tindahanGroupBuyReceiptsFolderId: string | null = null;

async function getTindahanGroupBuyReceiptsFolder(): Promise<{ id: string; created: boolean }> {
  if (_tindahanGroupBuyReceiptsFolderId) {
    return { id: _tindahanGroupBuyReceiptsFolderId, created: false };
  }

  const drive = getDriveClient();
  const parentId = process.env.GOOGLE_DRIVE_FOLDER_ID;
  if (!parentId) throw new Error("GOOGLE_DRIVE_FOLDER_ID environment variable is not set.");

  const folderName = "Tindahan ni Tinapa Group Buy Receipts";
  const existing = await drive.files.list({
    q: `'${parentId}' in parents and name = '${folderName}' and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
    fields: "files(id)",
    pageSize: 1,
  });
  const existingId = existing.data.files?.[0]?.id;
  if (existingId) {
    _tindahanGroupBuyReceiptsFolderId = existingId;
    return { id: existingId, created: false };
  }

  const created = await drive.files.create({
    requestBody: {
      name: folderName,
      mimeType: "application/vnd.google-apps.folder",
      parents: [parentId],
    },
    fields: "id",
  });
  if (!created.data.id) throw new Error("Google Drive did not create the group-buy receipts folder.");
  _tindahanGroupBuyReceiptsFolderId = created.data.id;
  return { id: created.data.id, created: true };
}

export async function ensureTindahanGroupBuyReceiptsFolder(): Promise<{ created: boolean }> {
  const folder = await getTindahanGroupBuyReceiptsFolder();
  return { created: folder.created };
}

export async function uploadTindahanGroupBuyPaymentProof(
  buffer: Buffer,
  mimeType: string,
  filename: string
): Promise<UploadResult> {
  const drive = getDriveClient();
  const folder = await getTindahanGroupBuyReceiptsFolder();
  const { Readable } = await import("stream");
  const response = await drive.files.create({
    requestBody: { name: filename, parents: [folder.id], mimeType },
    media: { mimeType, body: Readable.from(buffer) },
    fields: "id,webViewLink",
  });
  const fileId = response.data.id;
  if (!fileId) throw new Error("Google Drive did not return a file ID.");
  return { fileId, webViewLink: response.data.webViewLink ?? "" };
}
