import { auth } from "@/auth";
import { db } from "@/lib/db";
import { shippingMethods } from "@/lib/db/schema";
import { formatPrice } from "@/lib/utils";
import { redirect } from "next/navigation";
import productsData from "@/data/products.json";
import { Truck, MapPin, Layers } from "lucide-react";
import { TindahanDriveSetup } from "@/components/admin/tindahan-drive-setup";
import { getTindahanGroupBuyDriveStatus } from "@/lib/google-drive/tindahan";

export const metadata = { title: "Settings — SellerHub" };

export default async function SettingsPage({ searchParams }: { searchParams: Promise<{ [key: string]: string | string[] | undefined }> }) {
  const session = await auth();
  if (!session?.user) redirect("/admin/login");

  const [methods, driveStatus, params] = await Promise.all([
    db.query.shippingMethods.findMany({ orderBy: (sm, { asc }) => [asc(sm.fee)] }),
    getTindahanGroupBuyDriveStatus(),
    searchParams,
  ]);

  const shippingConfig = productsData.find(
    (p: any) => p.type === "shipping_config"
  ) as { type: string; category?: string; rates?: Record<string, Record<string, number>> } | undefined;

  const rates = shippingConfig?.rates || {};

  return (
    <div className="p-4 md:p-8 max-w-3xl space-y-8">
      <div>
        <h1 className="text-2xl font-bold text-[var(--color-text-primary)]">
          Settings &amp; Configuration
        </h1>
        <p className="text-sm text-[var(--color-text-secondary)] mt-1">
          Manage shipping rates, regions, and seller account configuration.
        </p>
      </div>

      <TindahanDriveSetup
        connected={driveStatus.connected}
        canManageDrive={(session.user as { role?: string }).role === "admin"}
        folderName={driveStatus.folderName}
        oauthConfigured={Boolean(process.env.GOOGLE_OAUTH_CLIENT_ID && process.env.GOOGLE_OAUTH_CLIENT_SECRET)}
        pickerApiKey=REDACTED ?? ""}
        pickerAppId={process.env.NEXT_PUBLIC_GOOGLE_PICKER_APP_ID ?? ""}
        notice={typeof params.drive === "string" ? params.drive : null}
      />

      {/* Shipping Methods & Tiered Rates */}
      <section className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-bold text-[var(--color-text-primary)] flex items-center gap-2">
            <Truck size={20} className="text-[var(--color-accent)]" /> Tiered Regional Shipping Rates
          </h2>
          <span className="text-xs font-semibold px-2.5 py-1 rounded-full bg-[var(--color-status-success-bg)] text-[var(--color-status-success)]">
            Active in products.json
          </span>
        </div>

        <div className="grid gap-3">
          {methods.map((method) => {
            const key = method.name.toLowerCase().includes("luzon")
              ? "luzon"
              : method.name.toLowerCase().includes("visayas")
              ? "visayas"
              : method.name.toLowerCase().includes("mindanao")
              ? "mindanao"
              : "other";

            const regionRates = rates[key];

            return (
              <div
                key={method.id}
                className="neu-card p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <MapPin size={16} className="text-[var(--color-accent)]" />
                    <p className="font-bold text-sm text-[var(--color-text-primary)]">
                      {method.name}
                    </p>
                    <span
                      className={`text-[10px] font-extrabold px-2 py-0.5 rounded-full ${
                        method.isActive ? "status-success" : "status-neutral"
                      }`}
                    >
                      {method.isActive ? "Active" : "Inactive"}
                    </span>
                  </div>

                  {/* Tiered Rates Breakdown from products.json */}
                  {regionRates ? (
                    <div className="flex flex-wrap items-center gap-2 text-xs text-[var(--color-text-secondary)] pl-6">
                      <span className="bg-[var(--color-neu-bg)] px-2 py-1 rounded-lg">
                        1 pc: <strong className="text-[var(--color-text-primary)]">₱{regionRates["1"] ?? 0}</strong>
                      </span>
                      <span className="bg-[var(--color-neu-bg)] px-2 py-1 rounded-lg">
                        2 pcs: <strong className="text-[var(--color-text-primary)]">₱{regionRates["2"] ?? 0}</strong>
                      </span>
                      <span className="bg-[var(--color-neu-bg)] px-2 py-1 rounded-lg">
                        3+ pcs: <strong className="text-[var(--color-text-primary)]">₱{regionRates["max"] ?? 0}</strong>
                      </span>
                    </div>
                  ) : (
                    <p className="text-xs text-[var(--color-text-muted)] pl-6">
                      Standard fee: {formatPrice(method.fee)}
                    </p>
                  )}
                </div>

                <div className="text-right sm:self-center pl-6 sm:pl-0">
                  <span className="text-xs text-[var(--color-text-muted)] block">Base Rate</span>
                  <span className="text-base font-extrabold text-[var(--color-accent)]">
                    {formatPrice(method.fee)}
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        <p className="text-xs text-[var(--color-text-muted)] italic">
          Regional rates are automatically evaluated and calculated at checkout based on the delivery region and cart item count.
        </p>
      </section>

      {/* Account Details */}
      <section className="space-y-4">
        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">
          Account
        </h2>
        <div className="neu-card p-4">
          <p className="text-xs font-medium uppercase tracking-wide text-[var(--color-text-muted)]">
            Signed in as
          </p>
          <p className="font-bold text-base mt-1 text-[var(--color-text-primary)]">
            {session.user.name || "Seller"}
          </p>
          <p className="text-sm text-[var(--color-text-secondary)]">
            {session.user.email}
          </p>
        </div>
      </section>

      {/* App Info */}
      <section className="space-y-4">
        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">
          System Information
        </h2>
        <div className="neu-card p-4 space-y-2 text-sm text-[var(--color-text-secondary)]">
          <div className="flex justify-between">
            <span>Version</span>
            <span className="font-bold text-[var(--color-text-primary)]">1.2.0</span>
          </div>
          <div className="flex justify-between">
            <span>Order Prefix</span>
            <span className="font-bold text-[var(--color-text-primary)] font-mono">
              {process.env.ORDER_NUMBER_PREFIX ?? "PB"}
            </span>
          </div>
          <div className="flex justify-between">
            <span>Shipping Engine</span>
            <span className="font-bold text-[var(--color-status-success)]">Tiered Dynamic Matrix</span>
          </div>
        </div>
      </section>
    </div>
  );
}
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

type PickerView = {
  setIncludeFolders: (include: boolean) => PickerView;
  setSelectFolderEnabled: (enabled: boolean) => PickerView;
};
type PickerResult = { action?: string; docs?: Array<{ id?: string; name?: string }> };
type PickerBuilder = {
  addView: (view: PickerView) => PickerBuilder;
  setOAuthToken: (token: string) => PickerBuilder;
  setDeveloperKey: (key: string) => PickerBuilder;
  setAppId: (id: string) => PickerBuilder;
  setCallback: (callback: (result: PickerResult) => void) => PickerBuilder;
  build: () => { setVisible: (visible: boolean) => void };
};
type PickerApi = {
  PickerBuilder: new () => PickerBuilder;
  DocsView: new (viewId?: string) => PickerView;
  ViewId: { FOLDERS: string };
  Action: { PICKED: string };
};
declare global {
  interface Window {
    gapi?: { load: (api: string, callback: () => void) => void };
    google?: { picker?: PickerApi };
  }
}

type Props = {
  connected: boolean;
  canManageDrive: boolean;
  folderName: string | null;
  oauthConfigured: boolean;
  pickerApiKey: string;
  pickerAppId: string;
  notice: string | null;
};

const noticeText: Record<string, string> = {
  connected: "Google Drive connected. Now choose the main order folder.",
  setup: "Google OAuth is not configured yet. Add its credentials to admin-pbc on Vercel.",
  cancelled: "Google Drive was not connected. You can try again.",
  error: "Google Drive could not connect. Check the setup and try again.",
  unauthorized: "Sign in as an admin, then connect Google Drive again.",
  "folder-saved": "Group-buy receipt folder ready.",
};

export function TindahanDriveSetup({ connected, canManageDrive, folderName, oauthConfigured, pickerApiKey, pickerAppId, notice }: Props) {
  const router = useRouter();
  const [pickerReady, setPickerReady] = useState(false);
  const [busy, setBusy] = useState(false);
  const initialMessage = notice === "connected" && folderName ? "Google Drive reconnected." : notice ? noticeText[notice] ?? "" : "";
  const [message, setMessage] = useState(initialMessage);

  useEffect(() => {
    let mounted = true;
    const loadPicker = () => window.gapi?.load("picker", () => mounted && setPickerReady(true));
    const existing = document.querySelector<HTMLScriptElement>("script[data-tindahan-picker]");
    if (existing) {
      if (window.gapi) loadPicker();
      else existing.addEventListener("load", loadPicker, { once: true });
    } else {
      const script = document.createElement("script");
      script.src = "https://apis.google.com/js/api.js";
      script.async = true;
      script.dataset.tindahanPicker = "true";
      script.onload = loadPicker;
      script.onerror = () => mounted && setMessage("Google Drive folder picker did not load. Refresh the page and try again.");
      document.head.appendChild(script);
    }
    return () => { mounted = false; };
  }, []);

  async function chooseFolder() {
    if (!pickerReady || !pickerApiKey || !pickerAppId) return;
    setBusy(true);
    setMessage("");
    try {
      const tokenResponse = await fetch("/api/admin/google-drive/access-token", { cache: "no-store" });
      const tokenBody = await tokenResponse.json() as { accessToken?: string; error?: string };
      if (!tokenResponse.ok || !tokenBody.accessToken) throw new Error(tokenBody.error || "Could not open Google Drive.");
      const picker = window.google?.picker;
      if (!picker) throw new Error("Google Drive folder picker is still loading.");
      const folderView = new picker.DocsView(picker.ViewId.FOLDERS).setIncludeFolders(true).setSelectFolderEnabled(true);
      new picker.PickerBuilder()
        .addView(folderView)
        .setOAuthToken(tokenBody.accessToken)
        .setDeveloperKey(pickerApiKey)
        .setAppId(pickerAppId)
        .setCallback(async (result) => {
          if (result.action !== picker.Action.PICKED) return;
          const folderId = result.docs?.[0]?.id;
          if (!folderId) { setMessage("Choose a folder, then try again."); return; }
          setBusy(true);
          try {
            const response = await fetch("/api/admin/google-drive/folder", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ folderId }),
            });
            const body = await response.json() as { folderName?: string; error?: string };
            if (!response.ok || !body.folderName) throw new Error(body.error || "Could not save that folder.");
            router.push("/admin/settings?drive=folder-saved");
          } catch (error) {
            setMessage(error instanceof Error ? error.message : "Could not save that folder.");
          } finally {
            setBusy(false);
          }
        })
        .build()
        .setVisible(true);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not open Google Drive.");
    } finally {
      setBusy(false);
    }
  }

  const pickerConfigured = Boolean(pickerApiKey && pickerAppId);
  return (
    <section id="group-buy-drive" className="neu-card p-4 md:p-5 space-y-3">
      <div>
        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">Group-buy receipt folder</h2>
        <p className="mt-1 text-sm text-[var(--color-text-secondary)]">Connect Google Drive, then select the main order folder. We’ll create a Tindahan ni Tinapa Group Buy Receipts subfolder inside it.</p>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        {!canManageDrive ? (
          <span className="text-sm text-[var(--color-text-secondary)]">Ask an admin to manage this Drive connection.</span>
        ) : !connected ? (
          oauthConfigured ? (
            <a href="/api/admin/google-drive/connect" className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold">Connect Google Drive</a>
          ) : <span className="text-sm text-[var(--color-text-secondary)]">Google Drive setup needed.</span>
        ) : (
          <>
            <button type="button" onClick={chooseFolder} disabled={busy || !pickerReady || !pickerConfigured} className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold disabled:opacity-50">
              {busy ? "Opening Drive…" : folderName ? "Change Drive folder" : "Choose main order folder"}
            </button>
            {oauthConfigured && <a href="/api/admin/google-drive/connect" className="text-sm font-semibold underline">Reconnect Google Drive</a>}
          </>
        )}
        <span className="text-sm text-[var(--color-text-secondary)]">
          {connected ? folderName ? `Saving receipts to ${folderName}` : "Drive connected; choose the main order folder." : "PBC's existing receipt uploads stay unchanged."}
        </span>
      </div>
      {connected && !pickerConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set NEXT_PUBLIC_GOOGLE_PICKER_API_KEY and NEXT_PUBLIC_GOOGLE_PICKER_APP_ID in Vercel to choose a folder.</p>}
      {!oauthConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set GOOGLE_OAUTH_CLIENT_ID and GOOGLE_OAUTH_CLIENT_SECRET in Vercel before connecting.</p>}
      {message && <p role="status" className="text-sm text-[var(--color-text-secondary)]">{message}</p>}
    </section>
  );
}
