import test from "node:test";
import assert from "node:assert/strict";
import { decryptGoogleDriveRefreshToken, encryptGoogleDriveRefreshToken } from "./oauth-crypto";

test("encrypts stored Google Drive refresh tokens and restores them", () => {
  process.env.AUTH_SECRET = "REDACTED";
  const encrypted = encryptGoogleDriveRefreshToken("refresh-token-value");
  assert.notEqual(encrypted, "refresh-token-value");
  assert.equal(decryptGoogleDriveRefreshToken(encrypted), "refresh-token-value");
});

test("rejects a changed encrypted Google Drive refresh token", () => {
  process.env.AUTH_SECRET = "REDACTED";
  const encrypted = encryptGoogleDriveRefreshToken("refresh-token-value");
  const [version, iv, tag, ciphertext] = encrypted.split(".");
  const bytes = Buffer.from(ciphertext, "base64url");
  bytes[0] ^= 1;
  const tampered = [version, iv, tag, bytes.toString("base64url")].join(".");
  assert.throws(() => decryptGoogleDriveRefreshToken(tampered));
});

import { createCipheriv, createDecipheriv, createHmac, randomBytes } from "node:crypto";

const version = "v1";
const additionalData = Buffer.from("tindahan-group-buy-drive-token:v1");

function encryptionKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is required to protect the Google Drive connection.");
  return createHmac("sha256", secret).update("tindahan-group-buy-drive-token:v1").digest();
}

export function encryptGoogleDriveRefreshToken(token: string) {
  if (!token) throw new Error("Google Drive did not return a refresh token.");
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", encryptionKey(), iv);
  cipher.setAAD(additionalData);
  const ciphertext = Buffer.concat([cipher.update(token, "utf8"), cipher.final()]);
  return [version, iv.toString("base64url"), cipher.getAuthTag().toString("base64url"), ciphertext.toString("base64url")].join(".");
}

export function decryptGoogleDriveRefreshToken(value: string) {
  const [storedVersion, ivText, tagText, ciphertextText, extra] = value.split(".");
  if (storedVersion !== version || !ivText || !tagText || !ciphertextText || extra !== undefined) {
    throw new Error("Saved Google Drive connection is unreadable. Reconnect Google Drive.");
  }

  try {
    const iv = Buffer.from(ivText, "base64url");
    const tag = Buffer.from(tagText, "base64url");
    const ciphertext = Buffer.from(ciphertextText, "base64url");
    if (iv.length !== 12 || tag.length !== 16 || !ciphertext.length) throw new Error("Invalid encrypted token.");
    const decipher = createDecipheriv("aes-256-gcm", encryptionKey(), iv);
    decipher.setAAD(additionalData);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");
  } catch (error) {
    throw new Error("Saved Google Drive connection is unreadable. Reconnect Google Drive.", { cause: error });
  }
}

import { eq } from "drizzle-orm";
import { google } from "googleapis";
import { Readable } from "node:stream";
import { db } from "@/lib/db";
import { appSettings } from "@/lib/db/schema";
import { decryptGoogleDriveRefreshToken, encryptGoogleDriveRefreshToken } from "@/lib/google-drive/oauth-crypto";
import { isTindahanGroupBuyReceiptFile } from "@/lib/google-drive/receipt-file";

export const TINDAHAN_DRIVE_FILE_SCOPE = "https://www.googleapis.com/auth/drive.file";
const settingKey = "tindahan_group_buy_drive";
const folderMimeType = "application/vnd.google-apps.folder";

type DriveSettings = {
  encryptedRefreshToken?: string;
  folderId?: string;
  folderName?: string;
  parentFolderId?: string;
};

const receiptFolderName = "Tindahan ni Tinapa Group Buy Receipts";

function createSettingsValue(value: unknown): DriveSettings {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const stored = value as Record<string, unknown>;
  return {
    ...(typeof stored.encryptedRefreshToken === "string" ? { encryptedRefreshToken: stored.encryptedRefreshToken } : {}),
    ...(typeof stored.folderId === "string" ? { folderId: stored.folderId } : {}),
    ...(typeof stored.folderName === "string" ? { folderName: stored.folderName } : {}),
    ...(typeof stored.parentFolderId === "string" ? { parentFolderId: stored.parentFolderId } : {}),
  };
}

async function readSettings() {
  const setting = await db.query.appSettings.findFirst({ where: eq(appSettings.key, settingKey) });
  return createSettingsValue(setting?.value);
}

async function saveSettings(patch: Partial<DriveSettings>) {
  const value = { ...(await readSettings()), ...patch };
  await db.insert(appSettings).values({ key: settingKey, value }).onConflictDoUpdate({
    target: appSettings.key,
    set: { value, updatedAt: new Date() },
  });
}

export function createTindahanDriveOAuthClient(redirectUri?: string) {
  const clientId = process.env.GOOGLE_OAUTH_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_OAUTH_CLIENT_SECRET;
  if (!clientId || !clientSecret) throw new Error("Google Drive OAuth is not configured.");
  return new google.auth.OAuth2(clientId, clientSecret, redirectUri);
}

export async function saveTindahanDriveRefreshToken(refreshToken: string) {
  await saveSettings({ encryptedRefreshToken: encryptGoogleDriveRefreshToken(refreshToken) });
}

export async function getTindahanGroupBuyDriveStatus() {
  const settings = await readSettings();
  return {
    connected: Boolean(settings.encryptedRefreshToken),
    folderName: settings.folderName ?? null,
  };
}

async function getTindahanDriveClient() {
  const settings = await readSettings();
  if (!settings.encryptedRefreshToken) throw new Error("Group-buy receipt storage is not connected.");
  const client = createTindahanDriveOAuthClient();
  client.setCredentials({ refresh_token: decryptGoogleDriveRefreshToken(settings.encryptedRefreshToken) });
  return google.drive({ version: "v3", auth: client });
}

export async function getTindahanDrivePickerAccessToken() {
  const settings = await readSettings();
  if (!settings.encryptedRefreshToken) throw new Error("Group-buy receipt storage is not connected.");
  const client = createTindahanDriveOAuthClient();
  client.setCredentials({ refresh_token: decryptGoogleDriveRefreshToken(settings.encryptedRefreshToken) });
  const result = await client.getAccessToken();
  if (!result.token) throw new Error("Google Drive could not provide an access token.");
  return result.token;
}

export async function saveTindahanGroupBuyReceiptFolder(folderId: string) {
  if (!/^[A-Za-z0-9_-]{5,256}$/.test(folderId)) throw new Error("Choose a valid Google Drive folder.");
  const drive = await getTindahanDriveClient();
  const result = await drive.files.get({ fileId: folderId, fields: "id,name,mimeType,capabilities(canAddChildren)" });
  if (result.data.mimeType !== folderMimeType || !result.data.id || !result.data.name || result.data.capabilities?.canAddChildren === false) {
    throw new Error("Choose a Google Drive folder for group-buy receipts.");
  }

  if (result.data.name === receiptFolderName) {
    await saveSettings({ folderId: result.data.id, folderName: result.data.name, parentFolderId: "" });
    return result.data.name;
  }

  const settings = await readSettings();
  if (settings.parentFolderId === result.data.id && settings.folderId) {
    const existing = await drive.files.get({ fileId: settings.folderId, fields: "id,name,mimeType,parents,capabilities(canAddChildren)" });
    if (existing.data.mimeType === folderMimeType && existing.data.name === receiptFolderName && existing.data.parents?.includes(result.data.id)) {
      return existing.data.name;
    }
  }

  const created = await drive.files.create({
    requestBody: { name: receiptFolderName, mimeType: folderMimeType, parents: [result.data.id] },
    fields: "id,name",
  });
  if (!created.data.id || !created.data.name) throw new Error("Google Drive did not create the group-buy receipts folder.");
  await saveSettings({ folderId: created.data.id, folderName: created.data.name, parentFolderId: result.data.id });
  return created.data.name;
}

export async function uploadTindahanGroupBuyPaymentProof(buffer: Buffer, mimeType: string, filename: string) {
  const settings = await readSettings();
  if (!settings.encryptedRefreshToken || !settings.folderId) {
    throw new Error("Group-buy receipt storage is not connected. Ask the shop owner to connect Google Drive in Admin Settings.");
  }
  const drive = await getTindahanDriveClient();
  const response = await drive.files.create({
    requestBody: { name: filename, parents: [settings.folderId], mimeType },
    media: { mimeType, body: Readable.from(buffer) },
    fields: "id,webViewLink",
  });
  if (!response.data.id) throw new Error("Google Drive did not return a receipt file ID.");
  return { fileId: response.data.id, webViewLink: response.data.webViewLink ?? "" };
}

export async function streamTindahanGroupBuyReceipt(fileId: string) {
  const settings = await readSettings();
  if (!settings.folderId) throw new Error("Group-buy receipt folder is not connected.");

  const drive = await getTindahanDriveClient();
  const metadata = await drive.files.get({ fileId, fields: "mimeType,parents" });
  if (!isTindahanGroupBuyReceiptFile(metadata.data, settings.folderId)) {
    throw new Error("Receipt is not in the configured group-buy folder.");
  }

  const response = await drive.files.get({ fileId, alt: "media" }, { responseType: "stream" });
  return { data: response.data as NodeJS.ReadableStream, mimeType: metadata.data.mimeType! };
}

import { NextRequest, NextResponse } from "next/server";
import { isTindahanDriveAdmin } from "@/lib/google-drive/admin-auth";
import { saveTindahanGroupBuyReceiptFolder } from "@/lib/google-drive/tindahan";

export async function POST(request: NextRequest) {
  if (request.headers.get("origin") !== request.nextUrl.origin) {
    return NextResponse.json({ error: "Request was not from this admin site." }, { status: 403 });
  }
  if (!(await isTindahanDriveAdmin())) return NextResponse.json({ error: "Sign in as an admin to continue." }, { status: 401 });

  let folderId: unknown;
  try {
    folderId = (await request.json()).folderId;
  } catch {
    return NextResponse.json({ error: "Choose a Google Drive folder." }, { status: 400 });
  }
  if (typeof folderId !== "string") return NextResponse.json({ error: "Choose a Google Drive folder." }, { status: 400 });

  try {
    const folderName = await saveTindahanGroupBuyReceiptFolder(folderId);
    return NextResponse.json({ folderName }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    console.error("Could not save Tindahan group-buy receipt folder:", error);
    return NextResponse.json({ error: "Could not access that folder. Pick the group-buy receipts folder and try again." }, { status: 400 });
  }
}

import { randomBytes } from "node:crypto";
import { NextRequest, NextResponse } from "next/server";
import { isTindahanDriveAdmin } from "@/lib/google-drive/admin-auth";
import { createTindahanDriveOAuthClient, TINDAHAN_DRIVE_FILE_SCOPE } from "@/lib/google-drive/tindahan";

const stateCookie = "tindahan-drive-oauth-state";

export async function GET(request: NextRequest) {
  if (!(await isTindahanDriveAdmin())) return NextResponse.redirect(new URL("/admin/login", request.url));
  try {
    const state = randomBytes(32).toString("base64url");
    const callbackUrl = new URL("/api/admin/google-drive/callback", process.env.AUTH_URL || process.env.NEXT_PUBLIC_APP_URL || request.nextUrl.origin).toString();
    const client = createTindahanDriveOAuthClient(callbackUrl);
    const response = NextResponse.redirect(client.generateAuthUrl({
      access_type: "offline",
      prompt: "consent",
      scope: [TINDAHAN_DRIVE_FILE_SCOPE],
      state,
    }));
    response.cookies.set(stateCookie, state, {
      httpOnly: true,
      secure: request.nextUrl.protocol === "https:",
      sameSite: "lax",
      maxAge: 600,
      path: "/",
    });
    return response;
  } catch (error) {
    console.error("Could not start Tindahan Google Drive OAuth:", error);
    return NextResponse.redirect(new URL("/admin/settings?drive=setup", request.url));
  }
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

type PickerView = {
  setIncludeFolders: (include: boolean) => PickerView;
  setSelectFolderEnabled: (enabled: boolean) => PickerView;
};
type PickerResult = { action?: string; docs?: Array<{ id?: string; name?: string }> };
type PickerBuilder = {
  addView: (view: PickerView) => PickerBuilder;
  setOAuthToken: (token: string) => PickerBuilder;
  setDeveloperKey: (key: string) => PickerBuilder;
  setAppId: (id: string) => PickerBuilder;
  setCallback: (callback: (result: PickerResult) => void) => PickerBuilder;
  build: () => { setVisible: (visible: boolean) => void };
};
type PickerApi = {
  PickerBuilder: new () => PickerBuilder;
  DocsView: new (viewId?: string) => PickerView;
  ViewId: { FOLDERS: string };
  Action: { PICKED: string };
};
declare global {
  interface Window {
    gapi?: { load: (api: string, callback: () => void) => void };
    google?: { picker?: PickerApi };
  }
}

type Props = {
  connected: boolean;
  canManageDrive: boolean;
  folderName: string | null;
  oauthConfigured: boolean;
  pickerApiKey: string;
  pickerAppId: string;
  notice: string | null;
};

const noticeText: Record<string, string> = {
  connected: "Google Drive connected. Now choose the main order folder.",
  setup: "Google OAuth is not configured yet. Add its credentials to admin-pbc on Vercel.",
  cancelled: "Google Drive was not connected. You can try again.",
  error: "Google Drive could not connect. Check the setup and try again.",
  unauthorized: "Sign in as an admin, then connect Google Drive again.",
  "folder-saved": "Group-buy receipt folder ready.",
};

export function TindahanDriveSetup({ connected, canManageDrive, folderName, oauthConfigured, pickerApiKey, pickerAppId, notice }: Props) {
  const router = useRouter();
  const [pickerReady, setPickerReady] = useState(false);
  const [busy, setBusy] = useState(false);
  const initialMessage = notice === "connected" && folderName ? "Google Drive reconnected." : notice ? noticeText[notice] ?? "" : "";
  const [message, setMessage] = useState(initialMessage);

  useEffect(() => {
    let mounted = true;
    const loadPicker = () => window.gapi?.load("picker", () => mounted && setPickerReady(true));
    const existing = document.querySelector<HTMLScriptElement>("script[data-tindahan-picker]");
    if (existing) {
      if (window.gapi) loadPicker();
      else existing.addEventListener("load", loadPicker, { once: true });
    } else {
      const script = document.createElement("script");
      script.src = "https://apis.google.com/js/api.js";
      script.async = true;
      script.dataset.tindahanPicker = "true";
      script.onload = loadPicker;
      script.onerror = () => mounted && setMessage("Google Drive folder picker did not load. Refresh the page and try again.");
      document.head.appendChild(script);
    }
    return () => { mounted = false; };
  }, []);

  async function chooseFolder() {
    if (!pickerReady || !pickerApiKey || !pickerAppId) return;
    setBusy(true);
    setMessage("");
    try {
      const tokenResponse = await fetch("/api/admin/google-drive/access-token", { cache: "no-store" });
      const tokenBody = await tokenResponse.json() as { accessToken?: string; error?: string };
      if (!tokenResponse.ok || !tokenBody.accessToken) throw new Error(tokenBody.error || "Could not open Google Drive.");
      const picker = window.google?.picker;
      if (!picker) throw new Error("Google Drive folder picker is still loading.");
      const folderView = new picker.DocsView(picker.ViewId.FOLDERS).setIncludeFolders(true).setSelectFolderEnabled(true);
      new picker.PickerBuilder()
        .addView(folderView)
        .setOAuthToken(tokenBody.accessToken)
        .setDeveloperKey(pickerApiKey)
        .setAppId(pickerAppId)
        .setCallback(async (result) => {
          if (result.action !== picker.Action.PICKED) return;
          const folderId = result.docs?.[0]?.id;
          if (!folderId) { setMessage("Choose a folder, then try again."); return; }
          setBusy(true);
          try {
            const response = await fetch("/api/admin/google-drive/folder", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ folderId }),
            });
            const body = await response.json() as { folderName?: string; error?: string };
            if (!response.ok || !body.folderName) throw new Error(body.error || "Could not save that folder.");
            router.push("/admin/settings?drive=folder-saved");
          } catch (error) {
            setMessage(error instanceof Error ? error.message : "Could not save that folder.");
          } finally {
            setBusy(false);
          }
        })
        .build()
        .setVisible(true);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not open Google Drive.");
    } finally {
      setBusy(false);
    }
  }

  const pickerConfigured = Boolean(pickerApiKey && pickerAppId);
  return (
    <section id="group-buy-drive" className="neu-card p-4 md:p-5 space-y-3">
      <div>
        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">Group-buy receipt folder</h2>
        <p className="mt-1 text-sm text-[var(--color-text-secondary)]">Connect Google Drive, then select the main order folder. We’ll create a Tindahan ni Tinapa Group Buy Receipts subfolder inside it.</p>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        {!canManageDrive ? (
          <span className="text-sm text-[var(--color-text-secondary)]">Ask an admin to manage this Drive connection.</span>
        ) : !connected ? (
          oauthConfigured ? (
            <a href="/api/admin/google-drive/connect" className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold">Connect Google Drive</a>
          ) : <span className="text-sm text-[var(--color-text-secondary)]">Google Drive setup needed.</span>
        ) : (
          <>
            <button type="button" onClick={chooseFolder} disabled={busy || !pickerReady || !pickerConfigured} className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold disabled:opacity-50">
              {busy ? "Opening Drive…" : folderName ? "Change Drive folder" : "Choose main order folder"}
            </button>
            {oauthConfigured && <a href="/api/admin/google-drive/connect" className="text-sm font-semibold underline">Reconnect Google Drive</a>}
          </>
        )}
        <span className="text-sm text-[var(--color-text-secondary)]">
          {connected ? folderName ? `Saving receipts to ${folderName}` : "Drive connected; choose the main order folder." : "PBC's existing receipt uploads stay unchanged."}
        </span>
      </div>
      {connected && !pickerConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set NEXT_PUBLIC_GOOGLE_PICKER_API_KEY and NEXT_PUBLIC_GOOGLE_PICKER_APP_ID in Vercel to choose a folder.</p>}
      {!oauthConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set GOOGLE_OAUTH_CLIENT_ID and GOOGLE_OAUTH_CLIENT_SECRET in Vercel before connecting.</p>}
      {message && <p role="status" className="text-sm text-[var(--color-text-secondary)]">{message}</p>}
    </section>
  );
}

import { timingSafeEqual } from "node:crypto";
import { NextRequest, NextResponse } from "next/server";
import { isTindahanDriveAdmin } from "@/lib/google-drive/admin-auth";
import { createTindahanDriveOAuthClient, saveTindahanDriveRefreshToken, TINDAHAN_DRIVE_FILE_SCOPE } from "@/lib/google-drive/tindahan";

const stateCookie = "tindahan-drive-oauth-state";

function finish(request: NextRequest, status: string) {
  const response = NextResponse.redirect(new URL(`/admin/settings?drive=${status}`, request.url));
  response.cookies.set(stateCookie, "", {
    httpOnly: true,
    secure: request.nextUrl.protocol === "https:",
    sameSite: "lax",
    maxAge: 0,
    path: "/",
  });
  return response;
}

export async function GET(request: NextRequest) {
  const state = request.nextUrl.searchParams.get("state") ?? "";
  const expectedState = request.cookies.get(stateCookie)?.value ?? "";
  const stateMatches = state.length > 0 && state.length === expectedState.length && timingSafeEqual(Buffer.from(state), Buffer.from(expectedState));
  if (!stateMatches) return finish(request, "error");
  if (!(await isTindahanDriveAdmin())) return finish(request, "unauthorized");
  if (request.nextUrl.searchParams.has("error")) return finish(request, "cancelled");

  const code = request.nextUrl.searchParams.get("code");
  if (!code) return finish(request, "error");
  try {
    const callbackUrl = new URL("/api/admin/google-drive/callback", process.env.AUTH_URL || process.env.NEXT_PUBLIC_APP_URL || request.nextUrl.origin).toString();
    const client = createTindahanDriveOAuthClient(callbackUrl);
    const { tokens } = await client.getToken(code);
    if (tokens.scope && !tokens.scope.split(" ").includes(TINDAHAN_DRIVE_FILE_SCOPE)) {
      throw new Error("Google Drive file access was not granted.");
    }
    if (!tokens.refresh_token) throw new Error("Google did not return offline access.");
    await saveTindahanDriveRefreshToken(tokens.refresh_token);
    return finish(request, "connected");
  } catch (error) {
    console.error("Tindahan Google Drive OAuth callback failed:", error);
    return finish(request, "error");
  }
}

