  assert.equal(isTindahanGroupBuyReceiptFile({ mimeType: "image/jpeg", parents: ["other-folder"] }, "receipt-folder"), false);
  assert.equal(isTindahanGroupBuyReceiptFile({ mimeType: "application/pdf", parents: ["receipt-folder"] }, "receipt-folder"), false);
});

