        columns: { storefrontKey: true },
      });
      isTindahanReceipt = order?.storefrontKey === "tindahan";
    } catch (error) {
      console.warn("Could not identify payment proof storefront for fileId", fileId, error);
    }

    if (isTindahanReceipt) {
      const session = await auth();
      if (!session?.user) {
        return new NextResponse("Unauthorized", {
          status: 401,
          headers: { "Cache-Control": "private, no-store" },
        });
      }
