# Tindahan ni Tinapa group-buy receipts

This is a separate Apps Script web app. It only stores GB receipt images in a private Drive folder. It does not call the main PBC Apps Script or write to Google Sheets.

The main `Peptide Babe Receipts` folder is shared with anyone who has its link. A child folder would inherit that access, so this script creates `Tindahan ni Tinapa Group Buy Receipts` at the top level of My Drive instead. It keeps the folder private and adds only the admin-pbc Drive service account as an editor, so admin-pbc can display the receipts.

## One-time setup

1. Open [script.google.com](https://script.google.com/) while signed in as the Drive owner. Create a new standalone project named `Tindahan ni Tinapa GB Receipts`. Do not edit the main PBC Apps Script.
2. Replace the starter code with `Code.gs` from this folder.
3. Open **Project Settings → Script properties**. Add these properties:

   - `TINAPA_GB_RECEIPT_SHARED_SECRET`: a private random value with at least 32 characters. Generate one in PowerShell with `node -e "console.log(require('crypto').randomBytes(32).toString('base64url'))"`.
   - `TINAPA_GB_RECEIPT_READER_EMAIL`: `drive-image-proxy@prs-hub-507415.iam.gserviceaccount.com`.

4. Select `setupTindahanGroupBuyReceipts` in the editor and click **Run**. Approve Drive access as the owner. This creates the private GB folder and shares it with the admin-pbc service account. Keep the folder ID from the execution log for reference.
5. Click **Deploy → New deployment → Web app**. Set **Execute as** to **Me** and access to **Anyone** (anonymous; not “Anyone with Google account”). The endpoint is protected by the secret from step 3. Copy the deployed URL ending in `/exec`.
6. From your existing Vercel-linked `admin-pbc` checkout, add these server-only Production and Preview environment variables with Vercel CLI. CLI prompts for each value, so the secret stays out of command history:

   ```powershell
   vercel env add TINAPA_GB_RECEIPT_SCRIPT_URL production
   vercel env add TINAPA_GB_RECEIPT_SCRIPT_URL preview
   vercel env add TINAPA_GB_RECEIPT_SCRIPT_SECRET production
   vercel env add TINAPA_GB_RECEIPT_SCRIPT_SECRET preview
   ```

   Enter the Apps Script `/exec` URL for the URL key, and the exact Script Properties secret for the secret key.

7. After this feature branch is merged and deployed to Vercel, redeploy admin-pbc if Git integration did not deploy it automatically. Group-buy checkout uploads receipts through this endpoint. PBC checkout keeps its existing upload path.

   ```powershell
   vercel deploy --prod
   ```

Never add the shared secret as a `NEXT_PUBLIC_` variable or paste it into storefront code. If you change the Apps Script deployment, update the Vercel URL and redeploy admin-pbc.
---UPLOAD SERVICE---
import { eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { appSettings } from "@/lib/db/schema";
import { getDriveClient } from "@/lib/google-drive/client";
import {
  isTindahanGbReceiptFile,
  parseTindahanGbReceiptUploadResponse,
} from "@/lib/google-drive/tindahan-gb-receipt-validation";

const folderSettingKey = "tindahan_gb_receipts_folder";
const validMimeTypes = new Set(["image/jpeg", "image/png", "image/webp"]);

async function rememberReceiptFolder(folderId: string) {
  const value = { folderId };
  await db.insert(appSettings).values({ key: folderSettingKey, value }).onConflictDoUpdate({
    target: appSettings.key,
    set: { value, updatedAt: new Date() },
  });
}

async function getReceiptFolderId() {
  const setting = await db.query.appSettings.findFirst({ where: eq(appSettings.key, folderSettingKey) });
  const value = setting?.value;
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const folderId = (value as Record<string, unknown>).folderId;
  return typeof folderId === "string" && /^[A-Za-z0-9_-]{5,256}$/.test(folderId) ? folderId : null;
}

export async function uploadTindahanGroupBuyPaymentProof(
  buffer: Buffer,
  mimeType: string,
  filename: string
) {
  const endpoint = process.env.TINAPA_GB_RECEIPT_SCRIPT_URL;
  const secret = process.env.TINAPA_GB_RECEIPT_SCRIPT_SECRET;
  if (!endpoint || !secret) {
    throw new Error("Group-buy receipt uploader is not configured in admin-pbc.");
  }
  if (!validMimeTypes.has(mimeType) || !buffer.length || buffer.length > 3 * 1024 * 1024) {
    throw new Error("Receipt must be a PNG, JPG, or WebP image under 3 MB.");
  }

  let scriptUrl: URL;
  try {
    scriptUrl = new URL(endpoint);
  } catch {
    throw new Error("Group-buy receipt uploader URL is invalid.");
  }
  if (
    scriptUrl.protocol !== "https:" ||
    scriptUrl.hostname !== "script.google.com" ||
    !/^\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(scriptUrl.pathname)
  ) {
    throw new Error("Use the deployed Google Apps Script web app URL for group-buy receipts.");
  }

  const response = await fetch(scriptUrl, {
    method: "POST",
    redirect: "follow",
    cache: "no-store",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      sharedSecret: secret,
      filename,
      mimeType,
      imageBase64: buffer.toString("base64"),
    }),
    signal: AbortSignal.timeout(25_000),
  });
  const responseText = await response.text();
  if (!response.ok) throw new Error("Group-buy receipt upload failed. Try again.");

  const uploaded = parseTindahanGbReceiptUploadResponse(responseText);
  await rememberReceiptFolder(uploaded.folderId);
  return { fileId: uploaded.fileId, webViewLink: "" };
}

export async function streamTindahanGroupBuyReceipt(fileId: string) {
  const folderId = await getReceiptFolderId();
  if (!folderId) throw new Error("Group-buy receipt folder has not been registered yet.");

  const drive = getDriveClient();
  const metadata = await drive.files.get({ fileId, fields: "mimeType,parents" });
  if (!isTindahanGbReceiptFile(metadata.data, folderId)) {
    throw new Error("Receipt is not inside the configured group-buy folder.");
  }

  const response = await drive.files.get({ fileId, alt: "media" }, { responseType: "stream" });
  return { data: response.data as NodeJS.ReadableStream, mimeType: metadata.data.mimeType! };
}
---VALIDATION---
type AppsScriptReceiptResponse = {
  ok?: unknown;
  fileId?: unknown;
  folderId?: unknown;
};

const validMimeTypes = new Set(["image/jpeg", "image/png", "image/webp"]);

export function parseTindahanGbReceiptUploadResponse(responseText: string) {
  let result: AppsScriptReceiptResponse;
  try {
    result = JSON.parse(responseText) as AppsScriptReceiptResponse;
  } catch {
    throw new Error("Group-buy receipt uploader returned an invalid response.");
  }

  if (
    result?.ok !== true ||
    typeof result.fileId !== "string" ||
    !/^[A-Za-z0-9_-]{5,256}$/.test(result.fileId) ||
    typeof result.folderId !== "string" ||
    !/^[A-Za-z0-9_-]{5,256}$/.test(result.folderId)
  ) {
    throw new Error("Group-buy receipt upload failed. Check the Apps Script deployment and try again.");
  }

  return { fileId: result.fileId, folderId: result.folderId };
}

export function isTindahanGbReceiptFile(
  metadata: { parents?: string[] | null; mimeType?: string | null },
  folderId: string
) {
  return Boolean(
    metadata.parents?.includes(folderId) &&
    metadata.mimeType &&
    validMimeTypes.has(metadata.mimeType)
  );
}
