---VALIDATION---
type AppsScriptReceiptResponse = {
  ok?: unknown;
  fileId?: unknown;
  folderId?: unknown;
};

const validMimeTypes = new Set(["image/jpeg", "image/png", "image/webp"]);

export function parseTindahanGbReceiptUploadResponse(responseText: string) {
  let result: AppsScriptReceiptResponse;
  try {
    result = JSON.parse(responseText) as AppsScriptReceiptResponse;
  } catch {
    throw new Error("Group-buy receipt uploader returned an invalid response.");
  }

  if (
    result?.ok !== true ||
    typeof result.fileId !== "string" ||
    !/^[A-Za-z0-9_-]{5,256}$/.test(result.fileId) ||
    typeof result.folderId !== "string" ||
    !/^[A-Za-z0-9_-]{5,256}$/.test(result.folderId)
  ) {
    throw new Error("Group-buy receipt upload failed. Check the Apps Script deployment and try again.");
  }

  return { fileId: result.fileId, folderId: result.folderId };
}

export function isTindahanGbReceiptFile(
  metadata: { parents?: string[] | null; mimeType?: string | null },
  folderId: string
) {
  return Boolean(
    metadata.parents?.includes(folderId) &&
    metadata.mimeType &&
    validMimeTypes.has(metadata.mimeType)
  );
}
---TESTS---
import assert from "node:assert/strict";
import test from "node:test";
import {
  isTindahanGbReceiptFile,
  parseTindahanGbReceiptUploadResponse,
} from "./tindahan-gb-receipt-validation";

test("parses a successful GB receipt upload and returns its Drive folder", () => {
  assert.deepEqual(
    parseTindahanGbReceiptUploadResponse(
      JSON.stringify({ ok: true, fileId: "receipt_12345", folderId: "folder_12345" })
    ),
    { fileId: "receipt_12345", folderId: "folder_12345" }
  );
});

test("rejects failed or malformed Apps Script responses", () => {
  assert.throws(() => parseTindahanGbReceiptUploadResponse("not json"), /invalid response/i);
  assert.throws(
    () => parseTindahanGbReceiptUploadResponse(JSON.stringify({ ok: false })),
    /upload failed/i
  );
  assert.throws(
    () => parseTindahanGbReceiptUploadResponse(JSON.stringify({ ok: true, fileId: "x" })),
    /upload failed/i
  );
});

test("accepts only image receipts directly inside the configured GB folder", () => {
  assert.equal(
    isTindahanGbReceiptFile({ parents: ["gb_folder"], mimeType: "image/jpeg" }, "gb_folder"),
    true
  );
  assert.equal(
    isTindahanGbReceiptFile({ parents: ["main_folder"], mimeType: "image/jpeg" }, "gb_folder"),
    false
  );
  assert.equal(
    isTindahanGbReceiptFile({ parents: ["gb_folder"], mimeType: "application/pdf" }, "gb_folder"),
    false
  );
});
