+
+export async function GET(request: NextRequest) {
+  if (!(await isTindahanDriveAdmin())) return NextResponse.redirect(new URL("/admin/login", request.url));
+  try {
+    const state = randomBytes(32).toString("base64url");
+    const callbackUrl = new URL("/api/admin/google-drive/callback", process.env.AUTH_URL || process.env.NEXT_PUBLIC_APP_URL || request.nextUrl.origin).toString();
+    const client = createTindahanDriveOAuthClient(callbackUrl);
+    const response = NextResponse.redirect(client.generateAuthUrl({
+      access_type: "offline",
+      prompt: "consent",
+      scope: [TINDAHAN_DRIVE_FILE_SCOPE],
+      state,
+    }));
+    response.cookies.set(stateCookie, state, {
+      httpOnly: true,
+      secure: request.nextUrl.protocol === "https:",
+      sameSite: "lax",
+      maxAge: 600,
+      path: "/",
+    });
+    return response;
+  } catch (error) {
+    console.error("Could not start Tindahan Google Drive OAuth:", error);
+    return NextResponse.redirect(new URL("/admin/settings?drive=setup", request.url));
+  }
+}
