+import { NextRequest, NextResponse } from "next/server";
+import { isTindahanDriveAdmin } from "@/lib/google-drive/admin-auth";
+import { saveTindahanGroupBuyReceiptFolder } from "@/lib/google-drive/tindahan";
+
+export async function POST(request: NextRequest) {
+  if (request.headers.get("origin") !== request.nextUrl.origin) {
+    return NextResponse.json({ error: "Request was not from this admin site." }, { status: 403 });
+  }
+  if (!(await isTindahanDriveAdmin())) return NextResponse.json({ error: "Sign in as an admin to continue." }, { status: 401 });
+
+  let folderId: unknown;
+  try {
+    folderId = (await request.json()).folderId;
+  } catch {
+    return NextResponse.json({ error: "Choose a Google Drive folder." }, { status: 400 });
+  }
+  if (typeof folderId !== "string") return NextResponse.json({ error: "Choose a Google Drive folder." }, { status: 400 });
+
+  try {
+    const folderName = await saveTindahanGroupBuyReceiptFolder(folderId);
+    return NextResponse.json({ folderName }, { headers: { "Cache-Control": "no-store" } });
+  } catch (error) {
+    console.error("Could not save Tindahan group-buy receipt folder:", error);
+    return NextResponse.json({ error: "Could not access that folder. Pick the group-buy receipts folder and try again." }, { status: 400 });
+  }
+}
