+import { createCipheriv, createDecipheriv, createHmac, randomBytes } from "node:crypto";
+
+const version = "v1";
+const additionalData = Buffer.from("tindahan-group-buy-drive-token:v1");
+
+function encryptionKey() {
+  const secret = process.env.AUTH_SECRET;
+  if (!secret) throw new Error("AUTH_SECRET is required to protect the Google Drive connection.");
+  return createHmac("sha256", secret).update("tindahan-group-buy-drive-token:v1").digest();
+}
+
+export function encryptGoogleDriveRefreshToken(token: string) {
+  if (!token) throw new Error("Google Drive did not return a refresh token.");
+  const iv = randomBytes(12);
+  const cipher = createCipheriv("aes-256-gcm", encryptionKey(), iv);
+  cipher.setAAD(additionalData);
+  const ciphertext = Buffer.concat([cipher.update(token, "utf8"), cipher.final()]);
+  return [version, iv.toString("base64url"), cipher.getAuthTag().toString("base64url"), ciphertext.toString("base64url")].join(".");
+}
+
+export function decryptGoogleDriveRefreshToken(value: string) {
+  const [storedVersion, ivText, tagText, ciphertextText, extra] = value.split(".");
+  if (storedVersion !== version || !ivText || !tagText || !ciphertextText || extra !== undefined) {
+    throw new Error("Saved Google Drive connection is unreadable. Reconnect Google Drive.");
+  }
+
+  try {
+    const iv = Buffer.from(ivText, "base64url");
+    const tag = Buffer.from(tagText, "base64url");
+    const ciphertext = Buffer.from(ciphertextText, "base64url");
+    if (iv.length !== 12 || tag.length !== 16 || !ciphertext.length) throw new Error("Invalid encrypted token.");
+    const decipher = createDecipheriv("aes-256-gcm", encryptionKey(), iv);
+    decipher.setAAD(additionalData);
+    decipher.setAuthTag(tag);
+    return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");
+  } catch (error) {
+    throw new Error("Saved Google Drive connection is unreadable. Reconnect Google Drive.", { cause: error });
+  }
+}
