export type GroupBuyItemInput = { productId: string; quantity: number };

export type CommerceProduct = {
  id: string;
  name: string;
  fullName: string;
  storefrontKey: string;
  kind: "standard" | "on_hand" | "group_buy";
  price: number;
  stock: number;
  isAvailable: boolean | null;
  batchId: number | null;
};

export type CommerceBatch = {
  id: number;
  status: string;
  deadline: string | Date;
};

type ShippingRates = Record<string, Record<string, number>>;

export function normalizeShippingRates(value: unknown): ShippingRates {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const settings = value as Record<string, unknown>;
  const rates = settings.rates;
  return rates && typeof rates === "object" && !Array.isArray(rates)
    ? rates as ShippingRates
    : settings as ShippingRates;
}

function isOrderable(batch: CommerceBatch | undefined, now: Date) {
  return Boolean(
    batch &&
      batch.status === "open" &&
      new Date(batch.deadline).getTime() > now.getTime()
  );
}

function getShippingRate(config: ShippingRates, region: string, quantity: number) {
  const normalized = region.trim().toLowerCase();
  if (!["luzon", "visayas", "mindanao", "other"].includes(normalized)) {
    throw new Error("Choose a valid shipping region.");
  }
  let rates = config[normalized];
  if (!rates) throw new Error("Shipping is unavailable for this region.");
  const fee = quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
  if (!Number.isSafeInteger(fee) || fee < 0) throw new Error("Shipping is unavailable for this region.");
  return fee;
}

const MAX_DB_INTEGER = 2_147_483_647;

export function prepareGroupBuyOrder(input: {
  items: Array<GroupBuyItemInput & { price?: number }>;
  shipmentPreference: "together" | "separate";
  region: string;
  shippingConfig: ShippingRates;
  products: Map<string, CommerceProduct>;
  batches: Map<number, CommerceBatch>;
  now?: Date;
}) {
  if (!input.items.length) throw new Error("Cart is empty.");
  if (!["luzon", "visayas", "mindanao", "other"].includes(input.region.trim().toLowerCase())) {
    throw new Error("Choose a valid shipping region.");
  }

  const quantities = new Map<string, number>();
  for (const item of input.items) {
    const quantity = Number(item.quantity);
    if (!item.productId || !Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
      throw new Error("Invalid cart item.");
    }
    const totalQuantity = (quantities.get(item.productId) ?? 0) + quantity;
    if (totalQuantity > 100) throw new Error("Maximum quantity per product is 100.");
    quantities.set(item.productId, totalQuantity);
  }

  const now = input.now ?? new Date();
  const orderItems = [...quantities].map(([productId, quantity]) => {
    const product = input.products.get(productId);
    if (
      !product ||
      product.storefrontKey !== "tindahan" ||
      product.kind === "standard" ||
      !product.isAvailable
    ) {
      throw new Error("A product is no longer available. Refresh the catalog and try again.");
    }
    if (product.kind === "on_hand" && product.stock < quantity) {
      throw new Error(`Not enough stock for ${product.name}.`);
    }
    if (product.kind === "group_buy" && !isOrderable(product.batchId ? input.batches.get(product.batchId) : undefined, now)) {
      throw new Error(`The group-buy batch for ${product.name} is closed.`);
    }
    if (!Number.isSafeInteger(product.price) || product.price < 0) throw new Error(`Invalid price for ${product.name}.`);
    const unitPrice = Math.round(product.price * 100);
    if (unitPrice > MAX_DB_INTEGER) throw new Error(`Price for ${product.name} is too high.`);
    const subtotal = unitPrice * quantity;
    if (subtotal > MAX_DB_INTEGER) throw new Error("Order total exceeds the supported payment limit.");
    return {
      productId: product.id,
      productName: product.fullName,
      productKind: product.kind,
      batchId: product.batchId,
      unitPrice,
      quantity,
      subtotal,
    };
  });

  const groups: Array<{ kind: "combined" | "on_hand" | "group_buy"; batchId: number | null; itemIndexes: number[]; quantity: number }> = [];
  if (input.shipmentPreference === "together") {
    groups.push({
      kind: "combined",
      batchId: null,
      itemIndexes: orderItems.map((_, index) => index),
      quantity: orderItems.reduce((sum, item) => sum + item.quantity, 0),
    });
  } else {
    const groupMap = new Map<string, (typeof groups)[number]>();
    orderItems.forEach((item, index) => {
      const kind = item.productKind === "on_hand" ? "on_hand" : "group_buy";
      const key = kind === "on_hand" ? "on_hand" : `batch:${item.batchId}`;
      const group = groupMap.get(key) ?? {
        kind,
        batchId: kind === "group_buy" ? item.batchId : null,
        itemIndexes: [],
        quantity: 0,
      };
      group.itemIndexes.push(index);
      group.quantity += item.quantity;
      groupMap.set(key, group);
    });
    groups.push(...groupMap.values());
  }

  const shipments = groups.map((group) => ({
    ...group,
    shippingFee: Math.round(getShippingRate(input.shippingConfig, input.region, group.quantity) * 100),
  }));
  const subtotal = orderItems.reduce((sum, item) => sum + item.subtotal, 0);
  const shippingFee = shipments.reduce((sum, shipment) => sum + shipment.shippingFee, 0);
  if (subtotal > MAX_DB_INTEGER || shippingFee > MAX_DB_INTEGER || subtotal + shippingFee > MAX_DB_INTEGER) {
    throw new Error("Order total exceeds the supported payment limit.");
  }
  return {
    items: orderItems.map((item, itemIndex) => ({
      ...item,
      shipmentIndex: shipments.findIndex((shipment) => shipment.itemIndexes.includes(itemIndex)),
    })),
    shipments,
    subtotal,
    shippingFee,
    total: subtotal + shippingFee,
  };
}
import { eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { appSettings } from "@/lib/db/schema";
import { getDriveClient } from "@/lib/google-drive/client";
import {
  isTindahanGbReceiptFile,
  parseTindahanGbReceiptUploadResponse,
} from "@/lib/google-drive/tindahan-gb-receipt-validation";

const folderSettingKey = "tindahan_gb_receipts_folder";
const validMimeTypes = new Set(["image/jpeg", "image/png", "image/webp"]);

async function rememberReceiptFolder(folderId: string) {
  const value = { folderId };
  await db.insert(appSettings).values({ key: folderSettingKey, value }).onConflictDoUpdate({
    target: appSettings.key,
    set: { value, updatedAt: new Date() },
  });
}

async function getReceiptFolderId() {
  const setting = await db.query.appSettings.findFirst({ where: eq(appSettings.key, folderSettingKey) });
  const value = setting?.value;
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const folderId = (value as Record<string, unknown>).folderId;
  return typeof folderId === "string" && /^[A-Za-z0-9_-]{5,256}$/.test(folderId) ? folderId : null;
}

export async function uploadTindahanGroupBuyPaymentProof(
  buffer: Buffer,
  mimeType: string,
  filename: string
) {
  const endpoint = process.env.TINAPA_GB_RECEIPT_SCRIPT_URL;
  const secret = process.env.TINAPA_GB_RECEIPT_SCRIPT_SECRET;
  if (!endpoint || !secret) {
    throw new Error("Group-buy receipt uploader is not configured in admin-pbc.");
  }
  if (!validMimeTypes.has(mimeType) || !buffer.length || buffer.length > 3 * 1024 * 1024) {
    throw new Error("Receipt must be a PNG, JPG, or WebP image under 3 MB.");
  }

  let scriptUrl: URL;
  try {
    scriptUrl = new URL(endpoint);
  } catch {
    throw new Error("Group-buy receipt uploader URL is invalid.");
  }
  if (
    scriptUrl.protocol !== "https:" ||
    scriptUrl.hostname !== "script.google.com" ||
    !/^\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(scriptUrl.pathname)
  ) {
    throw new Error("Use the deployed Google Apps Script web app URL for group-buy receipts.");
  }

  const response = await fetch(scriptUrl, {
    method: "POST",
    redirect: "follow",
    cache: "no-store",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      sharedSecret: secret,
      filename,
      mimeType,
      imageBase64: buffer.toString("base64"),
    }),
    signal: AbortSignal.timeout(25_000),
  });
  const responseText = await response.text();
  if (!response.ok) throw new Error("Group-buy receipt upload failed. Try again.");

  const uploaded = parseTindahanGbReceiptUploadResponse(responseText);
  await rememberReceiptFolder(uploaded.folderId);
  return { fileId: uploaded.fileId, webViewLink: "" };
}

export async function streamTindahanGroupBuyReceipt(fileId: string) {
  const folderId = await getReceiptFolderId();
  if (!folderId) throw new Error("Group-buy receipt folder has not been registered yet.");

  const drive = getDriveClient();
  const metadata = await drive.files.get({ fileId, fields: "mimeType,parents" });
  if (!isTindahanGbReceiptFile(metadata.data, folderId)) {
    throw new Error("Receipt is not inside the configured group-buy folder.");
  }

  const response = await drive.files.get({ fileId, alt: "media" }, { responseType: "stream" });
  return { data: response.data as NodeJS.ReadableStream, mimeType: metadata.data.mimeType! };
}

