import { auth } from "@/auth";
import { db } from "@/lib/db";
import { orders } from "@/lib/db/schema";
import { streamFileFromDrive } from "@/lib/google-drive/client";
import { streamTindahanGroupBuyReceipt } from "@/lib/google-drive/tindahan-gb-receipts";
import { eq } from "drizzle-orm";

function generateFallbackSvg(fileId: string): string {
  const cleanId = (fileId || "N/A").trim().slice(0, 32);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="460" height="300" viewBox="0 0 460 300" fill="none">
    <rect width="460" height="300" rx="16" fill="#FDF8F6"/>
    <rect x="1.5" y="1.5" width="457" height="297" rx="14.5" stroke="#F3E8E2" stroke-width="2"/>
    
