      <div className="flex items-center justify-between gap-4 border-b border-[var(--color-neu-shadow-dark)]/30 pb-4">
        <div className="flex items-center gap-3">
          <Link
            href={order.storefrontKey === "tindahan" ? "/admin/group-buy/orders" : "/admin/orders"}
            className="neu-button neu-button-ghost p-2 rounded-xl"
            aria-label="Back to orders"
          >
            <ArrowLeft size={18} />
          </Link>
          <div>
            <h1 className="text-xl font-bold text-[var(--color-text-primary)] flex items-center gap-2">
              {order.orderNumber}
            </h1>
            <p className="text-xs text-[var(--color-text-secondary)]">
              Placed on {formatDateTime(order.createdAt)}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <PaymentStatusBadge status={order.paymentStatus} />
          <OrderStatusBadge status={order.orderStatus} />
        </div>
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left 2 Cols: Order info & Items */}
        <div className="lg:col-span-2 space-y-6">
          {/* Items Card */}
          <div className="neu-card p-5 space-y-4">
            <h2 className="text-sm font-bold text-[var(--color-text-primary)] flex items-center gap-2">
              <Package size={18} className="text-[var(--color-accent)]" />
              Purchased Items
            </h2>

            <div className="space-y-3">
              {order.orderItems?.map((item) => {
                const matched = order.storefrontKey === "tindahan" ? undefined :
                  getProductByName(item.productName) ||
                  (item.productId ? getProductById(item.productId) : undefined);

                return (
                  <div
                    key={item.id}
                    className="flex items-start justify-between gap-3 text-sm py-2.5 border-b border-[var(--color-neu-shadow-dark)]/20 last:border-none"
                  >
                    <div className="flex items-start gap-3 min-w-0">
                      <div className="w-10 h-10 rounded-xl bg-[var(--color-neu-bg)] flex items-center justify-center text-xl shrink-0 shadow-inner mt-0.5">
                        {matched?.emoji || "📦"}
                      </div>
                      <div className="min-w-0">
                        <p className="font-bold text-[var(--color-text-primary)] truncate">
                          {matched?.fullName || item.productName}
                        </p>
                        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                          {matched?.category && (
                            <span className="text-[10px] font-semibold px-2 py-0.5 rounded-md bg-[var(--color-neu-bg)] text-[var(--color-text-secondary)] border border-[var(--color-neu-shadow-dark)]/30">
                              {matched.category}
                            </span>
                          )}
                          {matched?.pill && (
                            <span className="text-[10px] uppercase font-bold tracking-wider px-1.5 py-0.5 rounded bg-[var(--color-accent-muted)] text-[var(--color-accent)]">
                              {matched.pill}
                            </span>
                          )}
                          {order.storefrontKey === "tindahan" && (
                            <span className="text-[10px] font-semibold px-2 py-0.5 rounded-md bg-[var(--color-neu-bg)] text-[var(--color-text-secondary)] border border-[var(--color-neu-shadow-dark)]/30">
                              {item.productKind === "on_hand" ? "On hand" : "Group buy"}
                            </span>
                          )}
                          {matched?.id && (
                            <span className="text-[10px] font-mono text-[var(--color-text-muted)]">
                              SKU: {matched.id}
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-[var(--color-text-secondary)] mt-1">
                          {formatPrice(item.unitPrice)} × {item.quantity}
                        </p>
                      </div>
                    </div>
                    <span className="font-bold text-[var(--color-text-primary)] tabular-nums shrink-0">
                      {formatPrice(item.subtotal)}
                    </span>
                  </div>
                );
              })}
            </div>

            <div className="neu-divider" />

            {order.storefrontKey === "tindahan" && <div className="space-y-2 border-b border-[var(--color-neu-shadow-dark)]/20 pb-4">
              <h3 className="text-xs font-bold uppercase text-[var(--color-text-secondary)]">Shipments and batches</h3>
              {order.shipments.map((shipment) => <div key={shipment.id} className="rounded-xl bg-[var(--color-neu-bg)] p-3 text-xs">
                <p className="font-bold">{shipment.kind === "on_hand" ? "On-hand parcel" : shipment.kind === "combined" ? "Combined parcel" : `Group-buy parcel · ${shipment.batch?.name || "Batch"}`}</p>
                <p className="mt-1 text-[var(--color-text-secondary)]">Shipment status: {shipment.status.replaceAll("_", " ")} · Shipping: {formatPrice(shipment.shippingFee)}</p>
                {shipment.batch && <p className="text-[var(--color-text-secondary)]">Batch status: {shipment.batch.status} · Deadline: {formatDateTime(shipment.batch.deadline)} · ETA: {shipment.batch.eta ? formatDateTime(shipment.batch.eta) : "not set"}</p>}
                <form action={updateTindahanShipment} className="mt-2 flex flex-wrap items-center gap-2">
                  <input type="hidden" name="id" value={shipment.id} />
                  <select name="status" defaultValue={shipment.status} className="neu-input rounded-lg px-2 py-1 text-xs">{["processing", "ready_to_ship", "shipped", "completed"].map((status) => <option key={status} value={status}>{status.replaceAll("_", " ")}</option>)}</select>
                  <button className="neu-button rounded-lg px-2.5 py-1 text-xs font-bold">Update shipment</button>
                </form>
              </div>)}
            </div>}

            <div className="space-y-1.5 text-xs text-[var(--color-text-secondary)]">
              <div className="flex justify-between">
                <span>Subtotal</span>
                <span className="font-semibold">{formatPrice(order.subtotal)}</span>
              </div>
              <div className="flex justify-between">
                <span>Shipping ({order.shippingMethod})</span>
                <span className="font-semibold">{formatPrice(order.shippingFee)}</span>
              </div>
              <div className="flex justify-between text-base font-bold text-[var(--color-text-primary)] pt-2 border-t border-[var(--color-neu-shadow-dark)]/30">
                <span>Total</span>
                <span className="text-[var(--color-accent)]">
                  {formatPrice(order.total)}
                </span>
              </div>
            </div>
          </div>

          {/* Customer & Delivery Card */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="neu-card p-4 space-y-2">
              <h3 className="text-xs font-bold uppercase text-[var(--color-text-secondary)] flex items-center gap-1.5">
                <User size={16} className="text-[var(--color-accent)]" /> Customer Info
              </h3>
              <p className="font-semibold text-sm text-[var(--color-text-primary)]">
                {order.customerName}
              </p>
              <p className="text-xs text-[var(--color-text-secondary)]">
                Phone: {order.customerPhone}
              </p>
              {order.customerEmail && (
                <p className="text-xs text-[var(--color-text-secondary)]">
                  Email: {order.customerEmail}
                </p>
              )}
            </div>

            <div className="neu-card p-4 space-y-2">
              <h3 className="text-xs font-bold uppercase text-[var(--color-text-secondary)] flex items-center gap-1.5">
                <MapPin size={16} className="text-[var(--color-accent)]" /> Delivery Address
              </h3>
              <p className="text-xs text-[var(--color-text-primary)]">
                {order.deliveryAddress}
              </p>
              <p className="text-xs text-[var(--color-text-secondary)]">
                {order.city}, {order.province} {order.postalCode ?? ""}
              </p>
            </div>
          </div>

          {/* Timeline Card */}
          <div className="neu-card p-5 space-y-4">
            <h2 className="text-sm font-bold text-[var(--color-text-primary)]">
              Order Activity &amp; History
            </h2>
            <OrderTimeline events={order.orderEvents ?? []} />
          </div>

