const r = await tools.exec_command({cmd, shell:"powershell", sandbox_permissions:"require_escalated", justification:"May I query the public tracking endpoint for the test order just created, using its order number and synthetic test phone, to verify the saved total and shipment?", yield_time_ms:30000, max_output_tokens:1000});
